window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["21764541"]={"book":{"id":21764541,"title":"爱的五种能力","author":"赵永久","translator":"","publisher":"中国华侨出版社","pubdate":"2013-4","isbn":"9787511330765","tags":["情感","爱情","恋爱","心理学","两性心理学","心理","情商","两性"],"memCount":19},"np":1,"pb":[22],"idx":[{"i":13551,"t":"通过片段的学习让你在与他人沟通中能体会到对方的心情，让你成为共情的高手，使你与他人关系更加和谐。","l":"TF2-2","c":"@波波","g":1,"p":1},{"i":12007,"t":"情绪管理——随心而动","l":"TF2-2","c":"汐曦","g":0,"p":1},{"i":11897,"t":"说出需求的三步表达法","l":"TF2-3","c":"汐曦","g":0,"p":1},{"i":7262,"t":"爱的五种能力之一","l":"TF1-2","c":"@波波","g":1,"p":1},{"i":3844,"t":"掌握基于实时肯感受的述表达及基于感受和需要的请求表达法","l":"TF2-4","c":"青墨玉明","g":1,"p":1},{"i":3483,"t":"学会情绪觉察，并掌握穿越情绪按钮的方法。","l":"TF2-4","c":"Shooshoo","g":1,"p":1},{"i":3482,"t":"掌握述情句式：“事实+感受”","l":"TF2-3","c":"Shooshoo","g":1,"p":1},{"i":3287,"t":"保持客观，杜绝“编故事”","l":"TF2-2","c":"Shooshoo","g":1,"p":1},{"i":2057,"t":"叶菲TF2-4级别补定级","l":"TF2-4","c":"新页","g":1,"p":1},{"i":1964,"t":"爱的五种能力之觉察情绪","l":"TF3-2","c":"马辉","g":1,"p":1},{"i":1668,"t":"爱的五种能力之述情的3个句型","l":"TF3-1","c":"马辉","g":1,"p":1},{"i":1458,"t":"新页TF3-2定级","l":"TF3-2","c":"新页","g":1,"p":1},{"i":1436,"t":"新页TF2-4定级","l":"TF2-4","c":"新页","g":1,"p":1},{"i":1338,"t":"用影响的方式处理问题，用强化的方法施加影响","l":"TF2-4","c":"马辉","g":1,"p":1},{"i":1279,"t":"爱的五种能力之允许","l":"TF2-3","c":"马辉","g":1,"p":1},{"i":950,"t":"爱的五种能力之共情","l":"TF2-2","c":"马辉","g":1,"p":1},{"i":920,"t":"爱的五种能力之放下对与错","l":"TF2-1","c":"马辉","g":1,"p":1},{"i":910,"t":"爱的五种能力之表达感受2","l":"TF1-2","c":"马辉","g":1,"p":1},{"i":869,"t":"爱的能力之表达情感","l":"TF1-2","c":"马辉","g":1,"p":1},{"i":782,"t":"察觉情绪","l":"TF1-1","c":"马辉","g":1,"p":1},{"i":730,"t":"爱的需求层次，提升爱的能力","l":"TF2-1","c":"fionacao","g":1,"p":1},{"i":598,"t":"在情感关系中“爱”和“理”哪个更重要","l":"TF1-2","c":"fionacao","g":1,"p":1}],"ms":[{"id":13551,"topic":"通过片段的学习让你在与他人沟通中能体会到对方的心情，让你成为共情的高手，使你与他人关系更加和谐。","learn_goal":"","remark":"《爱的五种能力》这本书的作者是国内资深情感教练赵永久先生，书中结合真实案例详述爱一个人需要具备爱的五种具体的能力，也就是情绪管理、述情、共情、允许、影响，以便帮助你重新认识爱，修复爱，拥有爱，传播爱。","level":"TF2-2","duration":1,"status":30,"type":0,"chaishujia":{"username":"@波波","city":"厦门"},"club":{"name":"泉州鲤跃刺桐","city":"泉州"},"prologue":"\u003cp>大家好，我叫波波，我用三个标签介绍一下自己。电子公司技术主管，国际象棋老师，灵性的修行者。\u003c/p>\u003cp>【F】今天我要拆的书是《爱的五种能力》，作者是国内资深\u003ca href=\"https://baike.baidu.com/item/%E6%83%85%E6%84%9F%E6%95%99%E7%BB%83/1350858\">情感教练\u003ca href=\"https://baike.baidu.com/item/%E8%B5%B5%E6%B0%B8%E4%B9%85\">赵永久先生，书中结合真实案例详述爱一个人需要具备爱的五种具体的能力，也就是情绪管理、述情、共情、允许、影响，以便帮助你重新认识爱，修复爱，拥有爱，传播爱。\u003c/p>\u003cp>【A】本书与同类书相比，更强调的是向内求，开始反思和成长自己，不断提升自己爱的能力的方式，来实现家庭关系更和睦，夫妻相处更融洽，本书获《拆掉思维里的墙》作者古典、百合网副总裁慕岩认可推荐，它在豆瓣上的评分也达到8.6分。\u003c/p>\u003cp>【B】你是否有：工作上得心应手，情感上不知所措；交往很久，对方却迟迟不想结婚；婚姻里矛盾不断等；如果有其中之一，那这本书或许就是你需要的。\u003c/p>","ratings_count":1,"texts":[{"id":17577,"quote":"\u003cp>共情是指你能去理解别人，对别人的感受感同身受，并照顾到对方的心情，让对方知道你很理解他的感受，让对方会有明显的被理解的感觉。\u003c/p>\u003cp>那么在遇到现实问题时如何共情呢？它就是按照先关注“情（指情绪）”，再关注“事”的顺序进行的。有以下四个步骤：\u003c/p>\u003cp> 第一步：接受 \u003c/p>\u003cp>当一个人有了负面情绪后，去接受这个人有情绪这个事实，并且开始关注这个人的情绪。\u003c/p>\u003cp>简单说，就是当你注意到你的爱人或身边的人心情不好了，你就开始去关注他（她）的心情。并且关注的时候是以一种接纳的态度来进行的，就是你允许他心情不好。 \u003c/p>\u003cp>共情的做法是开始关注，并接纳这种情绪，让对方感觉到“我心中有你”！感觉到我们接纳并关注他。\u003c/p>\u003cp> 此步使用的语句一定是问号结束的——“你好像不开心？”“你好像挺生气的？”这样做是因为你是在向对方求证，只是在猜，语气太肯定给对方的感觉是你关注的是你有没有猜对，而不是关注他的情绪。 \u003c/p>\u003cp>第二步：分享\u003c/p>\u003cp> 就是要引导对方分享他内在的感受和外在发生的事情。\u003c/p>\u003cp> 一个人会有负面的感受，一定是有原因的，哪怕这个原因不是当下刚刚发生的事情，也是他想起了一些以往的事情，或者对眼前自己的境况的一种伤感，或是对未来的焦虑，这都是属于负面情绪，都是需要有人理解和共情的。就是要去聆听对方内在的声音，听他去诉说内在的想法和感受，搞明白对方为什么会有情绪。 \u003c/p>\u003cp>所以，在共情过程中，必须先认真地聆听对方讲述他有负面感受的原因。也就是他所经历的或想到的事情，满足对方述说的需求。聆听的时候，一定要把事情从头到尾完全听完，认认真真地听，中间尽量不要打断对方，让对方感觉到完全被关注和接纳。\u003c/p>\u003cp>第三步：肯定 \u003c/p>\u003cp>是最为关键的一步。它是去肯定对方起情绪的那个逻辑，基本等于告诉她“你是有资格起情绪的”。\u003c/p>\u003cp>就是要肯定对方起情绪的内在的那个思维逻辑过程，肯定的是起情绪的原因，而不是这件事情中的对和错。如果是本能的情绪，肯定这个本能，也就是肯定起情绪的逻辑。 \u003c/p>\u003cp>一般使用带问号的句型，比如说：“你感觉自己那么努力，却没有选上经理你！所以你很生气和失落，是吗？”\u003c/p>\u003cp>第四步：启发\u003c/p>\u003cp>就是通过苏格拉底的“诘问”，比如： “你觉得他为什么会这样做？”，“为什么他不这样对其他人？” ，“他每次都这样对你吗？”通过提问的方式启发对方，促使对方自己去思考问题，进而使用他（她）的智慧去解决问题。\u003c/p>\u003cp>通过引导，启发对方理解他人，或从另外的角度看问题，同时进一步去关注如何解决这个问题，如何面对未来。 \u003c/p>\u003cp>依照这四步，你就可以很好地完成一次共情的过程，练好这四个步骤，你就可以成长为一个共情的高手。\u003c/p>","explains":"\u003cp>我看大部分的小伙伴已经看完手上的资料啦，下面进入片段解读:\u003c/p>\u003cp>【What】这个片段就是告诉我们共情的定义和怎样做才能达到共情。\u003c/p>\u003cp>【Why】我们在亲密关系的沟通中，往往先关注事情 而经常发生冲突，如果在沟通的过程中我们能先关注对方的心情，从理顺心情开始，让对方感觉到我们更爱她（他），那么“共情”是一个可以使用的技巧。                                                                                 \u003c/p>\u003cp>【How】那么具体怎么做呢，就是四步：接受—&gt;分享—&gt;肯定—&gt;启发 ，并且这四步是层层递进的关系。 【预防异议】也许有人会认为我直接把事情处理好就行了，哪里要这么多繁琐的步骤，但是你可能没有注意到，表面上事情好像处理了，但是和对方的关系总觉得不是那么和谐。\u003c/p>\u003cp>【举例】我举一个例子，上个月的一天傍晚，我太太下班回到家时，我听到防盗门“哐”的一声撞到墙上，接下来是包“嗖”地丢到沙发上的声音，然后听到她整个人“噗”一下坐到沙发上。我感觉到她今天的心情跟往常很不一样，就赶快到客厅，先是把门关上，然后，再去沙发那里关心她。 “你好像很生气哦！怎么了？”我扶着她的肩膀问她。 “气死我了！”说这句话时，她明显地带着生气的情绪。 \u003c/p>\u003cp>“发生什么事情了？”我想赶快搞清楚状况。 \u003c/p>\u003cp>“工作上的事情，今天白天我和我们部门领导大吵了一架，她说我财务报表不完整，其实已经很完整了，她就是更年期没事找事。”\u003c/p>\u003cp> 这时我明白发生了。到这里我完成了共情的前面两步，接下来是第三步，肯定，我说 “你感觉自己的报表做得很完整，却被误会挨骂！\u003c/p>\u003cp>所以你很生气和委屈，是吗？” 得到她肯定后，进行第四步启发，我说“以前你的领导也常常这样发飙吗？老婆说：“不是！第一次” 我问：“那你觉得为什么今天她就发飙了呢？” 老婆说：“最近她被她的表妹骗了几十万的钱，可能压力也挺大的！”这样，老婆已经说出了她领导发飙的原因可能是最近压力大，她就可能会更加理解领导，心里的情绪就会逐渐消失，并且也使她学会了去考虑她人行为背后的需求，使她更加能够理解她人。\u003c/p>\u003cp>【这样做的好处】先关心对方的情绪，让对方感觉到你是爱她的、理解她的，才能更好地沟通达到共情的基础从而进一步沟通解决问题。\u003c/p>","interaction":"\u003cp>【A2】催化应用（分布催化1）\u003c/p>\u003cp> 大家先思考一下，本片段的四步骤可以用到未来的哪个场景呢？比如说和你家人相处中或者与同事相处过程中，先组内讨论下，稍后请一位小伙伴给大家分享一下。\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp> 下周一成绩出来，有些考生会因考不好而情绪低落。比如自己成绩在所报区没进面试，但在其他区排第一。\u003c/p>\u003cp>感谢这位小伙伴提供的案例，谢谢！\u003c/p>\u003cp>【A2】催化应用（分布催化2）\u003c/p>\u003cp> 结合自己刚才想到的场景，运用本拆四步骤与对方进行沟通，先组内讨论，稍后请一位小伙伴来分享一下。\u003c/p>\u003cp>\u003cstrong>学习者案例：\u003c/strong>\u003c/p>\u003cp>接受：你好像心情很低落。\u003c/p>\u003cp>分享：如果可以的话，您可以说说，什么让您感到失落。\u003c/p>\u003cp>肯定：自己成绩在所报区没进面试，在其他区排第一，换做我也会有情绪。\u003c/p>\u003cp>启发：要稳妥上岸的话，笔试两科目要到达怎样的水平，面试要达到怎样的能力？\u003c/p>\u003cp>非常感谢这位小伙伴的分享，他在这里完整应用了共情四步骤。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1654778062000,"updated_at":1655968990000,"ria":true},{"id":12007,"topic":"情绪管理——随心而动","learn_goal":"","remark":"你是否常常有情绪却置之不理，察觉不到情绪在提示什么，任由情绪发酵最终不可收拾？和朋友闹了小矛盾生闷气，结果越想越气愤，大吵一架恨不得老死不相往来？看到家里被孩子玩儿得乱糟糟有点小不爽，苦苦压抑结果大发脾气，伤害了亲子关系？忽视情绪的提示，可能后果很严重！让我们一起来学习如何跟着情绪的提示来管理情绪吧！","level":"TF2-2","duration":25,"status":19,"type":0,"chaishujia":{"username":"汐曦","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":null,"ratings_count":1,"texts":[{"id":15968,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1627567642000,"updated_at":1647526317000},{"id":11897,"topic":"说出需求的三步表达法","learn_goal":"","remark":"在爱人、朋友眼中，你是一个强势的人吗？你会经常感觉另一半不理解你、不配合你吗？你会常常觉得自己好心被当做了驴肝肺吗？这可能是因为你没有正确地表达自己，让对方误解了你的意图。一起来学习一下说出需求的三步表达法吧！","level":"TF2-3","duration":25,"status":19,"type":0,"chaishujia":{"username":"汐曦","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":null,"ratings_count":1,"texts":[{"id":15850,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1626091683000,"updated_at":1647526331000},{"id":7262,"topic":"爱的五种能力之一","learn_goal":"夫妻之间如何正确表达爱意","remark":"赵永久先生的关于夫妻之间的互动表达的技巧专著；","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"@波波","city":"厦门"},"club":{"name":"厦门鹭见欢喜分舵","city":"厦门"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我叫波波，我用三个标签介绍一下自己。我现在在某电子公司做技术主管，同时我是一位灵性的修行者，当然我最喜欢的是我是一位国际象棋老师的身份，因为下国际象棋不仅可以提高我们的专注力，而且能使我们的思维更细致更严谨，通过我的教学发现100个学生有90个孩子比之前在数学思维方面会更优秀。今天拆的书是国内资深情感教练赵永久写的《爱的五种能力》，要很好地完成一件事情，往往需要具备相应的能力，同样的爱别人也是一种需要学习的能力，本书讲述了情绪管理、述情、共情、允许、影响五种爱的能力，学习本书能使你在婚姻和情感中具备爱的能力，能够更加得心应手地处理情感问题。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10677,"quote":"\u003cp>\u003cstrong>放下对和错，让彼此做自己\u003c/strong>\u003c/p>\u003cp>在生活中，人们很容易听到有人这样来评价另一个人：“这个人不求上进，每个月就挣那点工资，也不想办法多挣点钱。”\u003c/p>\u003cp>&nbsp;这句话的出发点是认为人上进是对的，不上进是错的。而实际上平平淡淡，并不想挣太多钱就是错的吗？ \u003c/p>\u003cp>未必，只是说这话的人拿自己的对错标准去要求别人，认为别人不对而已。而实际上每个人有权选择自己过什么样的生活。\u003c/p>\u003cp>&nbsp;并且人们对幸福的理解不一样，有些人的幸福建立在更多的金钱上，而有些人即便没有很多钱，也能幸福地生活着。\u003c/p>\u003cp>&nbsp;一旦别人做的事情不符合自己的对错标准，人们会起的情绪基本都是愤怒、生气一类的情绪。这类情绪的作用是使自己产生生理唤起、精神亢奋、力量增大，为战斗做准备。这是人类在面对敌人、野兽时的需要，也是人们想要别人害怕自己、服从自己时的需要。本质上，这类情绪的目的就是想要对方按自己的标准行事，想要控制对方。\u003c/p>\u003cp>&nbsp;在爱情的关系里，我们都是成人，所以，想控制人时，人们一定不会像一个孩子一样，只是无理取闹，一定会拿一些对错的标准来帮助自己，以使自己能够完成控制别人的目的。有了对错作为标准，人们的控制欲都被穿上了合理的外衣，但常常迷惑的只是自己。\u003c/p>\u003cp>&nbsp;想要控制别人的人、控制欲强的人，多数很难意识到自己的问题，他们在控制别人的时候，往往需要借助对和错，他们能够看到的是对方如何如何错了，而不是自己的控制。\u003c/p>\u003cp>&nbsp;但因为别人做的事情不符合自己的标准就起情绪了，其实那一刻自己也失去了自由，也被别人控制了。因为自己情绪的开关，掌握在别人的手里，别人只要一做他们认为不对的事情，他们就起情绪。\u003c/p>\u003cp>&nbsp;自己会不会起情绪、能不能幸福？是由别人来决定的，只要别人不按照自己认为对的方式做事，自己的幸福就消失了。\u003c/p>\u003cp>&nbsp;这样因对错而起的情绪，发泄出来会伤害关系，扰动对方，使对方难以做自己，不发泄出来自己痛苦，难以做好自己。管理好因对错而起的情绪，可以让彼此都做自己，可以让彼此都更加幸福。\u003c/p>\u003cp>&nbsp;那么，人们如何管理这种因自己标准而起的情绪呢？\u003c/p>\u003cp>&nbsp;\u003cem>\u003cstrong>管理的具体方法\u003c/strong>\u003c/em>：\u003c/p>\u003cp>&nbsp;\u003cem>\u003cstrong>一\u003c/strong>\u003c/em>、\u003cstrong>觉察\u003c/strong>：意识到自己有情绪； \u003c/p>\u003cp>\u003cem>\u003cstrong>二\u003c/strong>\u003c/em>、\u003cstrong>区分\u003c/strong>：这一次的情绪主要是第一时间起的本能的情绪？还是有对错标准参与才起的理性情绪？\u003c/p>\u003cp>\u003cem>&nbsp;\u003cstrong>三\u003c/strong>\u003c/em>、当\u003cstrong>确定\u003c/strong>这是因自己对和错标准而起的情绪后，在内心告诉自己：放下对和错；\u003c/p>\u003cp>&nbsp;\u003cem>\u003cstrong>四\u003c/strong>\u003c/em>、然后\u003cstrong>用心去感受\u003c/strong>对方的心，感受一下对方做这个事情时内在的感受是什么？\u003c/p>\u003cp>&nbsp;至此，如果意识到自己有情绪时在内心运行这个过程，情绪往往自动就消失了，因为放下了理性，用心去感受对方，往往更容易理解对方，让自己成为一个内心平和、善解人意的人。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;【I部分】在亲密关系的相处中，经常会因为相互之间对事情的看法或观点不一致而产生冲突、争吵乃至大动干戈，这个起因就是我们的信念系统，对事情固有的评判标准引发自己的情绪 ，从而进一步产生冲突，以至于矛盾升级。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;那么针对这种由于对错的评判引起的情绪，我们可以试着采取在拆页中所提到的四个步骤来管理自己的情绪：\u003cem>\u003cstrong>觉察；区分；\u003c/strong>\u003c/em>以及\u003cstrong>\u003cem>确定对和错标准\u003c/em>\u003c/strong>引起的情绪之后，试着放下对或错；\u003cstrong>\u003cem>用心去感受一下对方的内心\u003c/em>\u003c/strong>，以及对方在做这个事情的感受；这样就可以主动调整自己的情绪，使自己达到内心和平、善解人意。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 这里我认为比较不好把握的是区分，因为家是讲爱的地方，家是放松的地方，在家里，爱是排在前面的，正确是排在后面的，如果对方没有伤害人的话，放下自己的对错标准，多用心去感受一下对方的感受，允许对方开心快乐；这样，彼此都自由了，幸福快乐也就更多了，家庭也就更和谐了。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;下面我给大家举个例子：我爱人在客厅看电视，她不是端端正正地坐在沙发上看电视，经常是整个人半躺在沙发上，双脚放在茶几上的。当我看到这个场面时，我会有一股无明的生气，觉得作为女人坐要有坐相，要矜持，而且茶几是用来放食物和茶水的，不是用来放脚的，这样子太没教养了，多不好看啊。如果没有学习这个拆页我们可能就因为这个事情开始争吵不休了，现在当我升起情绪时，我会觉察自己的情绪，接下来区分这个事情是因为有了对爱人的坐姿和脚放茶几上觉得是不好的，因此先放这个评判，站在爱人的角度去体会一下她上班一天也是很辛苦的，也许这样的坐姿她能够使身体更放松，心情更舒畅，而且这是在家里只要没有外人又不伤害别人，只要在单位和社交场合注意形象就好了，经过这四个步骤后我的心情也好了，爱人的心情也好，何乐而不为呢。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; 【A1部分】现在我们进行分组，以我左手边为一组，右手边为一组。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 大家回想一下，最近有没有经历类似的体验呢？是什么时候，是什么事情，当时是怎么说的呢？以小组为单位，给大家3分钟时间，在组内分享下各自的经验，3分钟后，我会请一会伙伴来分享。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;小伙伴分享：昨天晚上我和爱人在家里吃饭，吃完饭后到底是由谁来洗完的问题和老公起了争执，老公觉得洗碗是我的事，因为家务活就应该老婆来做，而我认为大家都上班挺辛苦的，凭什么就要我来洗碗呢，当时听到叫我洗碗就火冒三丈、觉得莫名不可思议，后来觉察到自己有了情绪，觉得应该先放下对错，把碗洗了再说吧。\u003c/p>\u003cp>&nbsp; &nbsp; 这位小伙伴得非常棒，她做到了，一是马上觉察到自己有情绪了，二是放下家务由谁来做的对错，如果能够体会一下对方的当时感受再进行一个相互的沟通，这个事情就可以完美解决了。\u003c/p>\u003cp>&nbsp; 【A2部分】经过刚才对相关经验的回顾，相信大家对这个方法有了比较深刻的理解，给大家1分钟时间，写下自己可以运用的一个场景并写出可操作性的计划，然后邀请一位小伙伴分享一下\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;小伙伴分享：在接下来到元宵的一周内，由于孩子比较毛躁而引起自己生气时，可以使用觉察；区分；以及确定对和错标准引起的情绪之后，试着放下对或错；用心去感受一下对方的内心，以及对方在做这个事情的感受，这四个步骤来静下心和孩子沟通。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1551078856000,"updated_at":1551163743000,"ria":true},{"id":3844,"topic":"掌握基于实时肯感受的述表达及基于感受和需要的请求表达法","learn_goal":"让学习者在现场运用“事实+感受”及“感受+需要”表达自己","remark":"目的是想让大家通过现场体验，清楚怎样进行述情，并能在生活中不断去用这种方法，让他人更容易懂自己、爱自己，使自己成为一个“易爱”的人；并且我们在实际生活中有请求胡时候，我们可以选择什么样的方式表达自己的请求，让他人更好的了解我们的需要，更好地响应我们的请求，避免不必要胡误解。","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"青墨玉明","city":"株洲"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"Hello，大家好！我叫罗小青，我喜欢大家叫我小青。今天我带拆第一个片段主题为：掌握基于事实+感受的述情表达法，片段出自《爱的五种能力》第128页。\r\n【F】:本书属于致用类图书，全书循序渐进的引出了爱的五种能力，分别是：情绪管理、述情、共情、允许、影响。各种能力的培养都是基于非暴力沟通的四个基本要素，与第二个片段关联紧密。\r\n【A】:本书结构简单易懂、内容简洁，本书在当当网“两性关系”的图书畅销榜中排名第11，在豆瓣网的评分为9.1分。本书丰富的实例与练习结合，让读者更容易吸收书本知识。\r\n【B】:通过阅读本书，可以掌握爱的五种能力，从而改善我们的人际关系，今天我带拆的就是第二种能力-述情。\r\n 下面请欣赏原文片段，首先，我需要一位小伙伴替我朗读原文片段。","ratings_count":0,"texts":[{"id":6775,"quote":"\u003cp>【学习目标】\u003cstrong>让学习者在现场运用“事实+感受”的述情方式表达自我。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>实际生活中，爱人如果做了一件事情或说了一句话，自己感觉到很不舒服，人们通常有两种做法，都是容易伤害到关系的：\u003c/p>\u003cp>\u003cstrong>一些人是忍者，把不舒服的感觉压抑到内心深处，委曲求全。\u003c/strong>比如：\u003c/p>\u003cp>爱人吃了有异味的食物，还来吻你！你承受不了那气味，很不舒服，但你选择了忍者。\u003c/p>\u003cp>看起来你是个能忍的人，但这样做对方可能就不知道你对这些味道是接受不了的，下一次他可能还会这样做，所以，你也许会很多次地承受这种很难闻的气味。\u003c/p>\u003cp>等有一天你实在无法承受，你可能对他大发雷霆，这时他就蒙了，他会想不明白，为什么以前你都能接受，而这次你就接受不了呢？他甚至会联想到你是不是外边有人了，不再喜欢他了。如果真是这样的话，对你们的关系影响就大了。\u003c/p>\u003cp>\u003cstrong>还有一些人常用的方法就是发飙，指责或抱怨对方，甚至攻击对方\u003c/strong>，这样的人可能会这样说：“滚！臭嘴，熏死我了，别碰我！”\u003c/p>\u003cp>这样说完内心是很爽的，但可能会伤害到对方，让对方感觉你不接纳他，对你们的关系可能会有伤害。\u003c/p>\u003cp>因此，这两种方法都是不可取得，最好的方法就是告诉对方你的感受，\u003cstrong>使用述情的两个基本功：事实+感受。\u003c/strong>\u003c/p>\u003cp>事实：你吃了大蒜后来吻我！\u003c/p>\u003cp>感受：有一股大蒜味，很难闻！ \u003c/p>\u003cp>（附件1：原文片段）\u003c/p>","explains":"\u003cp>【\u003cstrong>行动步骤\u003c/strong>】实际生活中，假如我们因某些人遇到不舒服的事，我们一般会做出什么样的反应？（附件4）\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>忍久了无法再忍时便会爆发，发飙时自己爽了却伤了他人，摧毁和谐关系。那么我们该用什么方法呢，根据原文片段，我们可以找到一种述情的方法来充分表达自己又不伤害他人。具体做法是（附件4）：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>观察事实\u003c/strong>\u003c/p>\u003cp>观察是非暴力沟通的第一要素，要注意区分评论，它提倡在特定的时间和情境中进行观察，并清楚地描述观察结果，而这个结果就是我们这要说的事实。例如，今晚到场的有12人，这是谁也无法改变的事实。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>体会感受\u003c/strong>\u003c/p>\u003cp>感受是非暴力沟通的第二要素，要注意区分想法，大家可以看到附件3（感受、想法词），当不舒服时，去感受词中找到自己不舒服时的感受。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>述情表达\u003c/strong>\u003c/p>\u003cp>基于观察到的事实和体会到的感受，用\u003cstrong>“我看到\u003c/strong>\u003cstrong>……\u003c/strong>\u003cstrong>，我的心情是\u003c/strong>\u003cstrong>……\u003c/strong>\u003cstrong>”\u003c/strong>的句式充分表达不舒服时的自己。\u003c/p>\u003cp>【\u003cstrong>相关案例\u003c/strong>】举个例子，每次我一洗完澡，老公立马进入到卫生间时，他就会说我没把水拖干净，事实我有拖地只是拖得不是特别干，以前我会跟他辩论，最后总是不欢而散。后来我\u003cstrong>观察事实\u003c/strong>，我看到“有五次我一洗完澡，老公你立马去用卫生间后，第一句话就是说我没有拖地”；我\u003cstrong>体会感受\u003c/strong>，自己当时有“不高兴、不满”，趁他说我的时候，我用\u003cstrong>述情方式\u003c/strong>对他说了“我看到有五次我一洗完澡，你立马进卫生间，你五次的第一反应都是我没有拖地，每次你一说完我就会情不自禁的不高兴和不满”，奇迹般的他再也没有跟我辩论，还似乎听进了我的真实感受，并再也不因这个事情说我了。\u003c/p>\u003cp>【\u003cstrong>不那么做的坏处\u003c/strong>】：如果不那么做，我们很有可能会无意之间指责对方，把对事的意见变成针对人了，一不小心把简单事情说得很复杂，把简单沟通变成暴力沟通。\u003c/p>\u003cp>【\u003cstrong>反面案例\u003c/strong>】记得有一次我的上司在交给我一项工作后的第二天就催我交作业，我二话不说心里嘀咕说天天就知道催催催，这人真讨厌，结果越来越讨厌我的她。\u003c/p>\u003cp>【\u003cstrong>正面案例\u003c/strong>】当时我用了拆书页所讲的方法了，领导提前一天交给了我这项工作，到今天已经过了10小时了我还没有完成，在这期间我做一个重要的PPT用了6小时\u003cstrong>（观察事实）\u003c/strong>，工作没做完我感到着急和焦虑\u003cstrong>（体会感受）\u003c/strong>，对上司说“我知道过去了10小时您交办的事情我还没有做完，现在我自己感到着急和焦虑，我还需要三个小时完成，请您再给我三个小时。”\u003cstrong>（述情表达）\u003c/strong>，这样一述情完，我自己心里也舒坦了，更加关注事实和感受而非埋怨上司。\u003c/p>\u003cp>&nbsp; &nbsp; 【\u003cstrong>适用边界\u003c/strong>】为了自己的沟通更加畅通、高效，该方法适用于工作和生活的多数场所，特别是与家人和比较亲近的朋友间的沟通中，但对有危险的场所就要慎重的使用此方法。\u003c/p>","interaction":"\u003cp>【A1】激活经验（显像提问）\u003c/p>\u003cp>听完我的讲解，相信大家对述情的表达已有了一定的了解。下面我们分成A、B两组来进行一次体验，每组自己选定一位小组长。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>请大家回忆近期沟通中，是否出现过你说了半天对方还不明白你所说的情况，你当时有什么样的感受，请回忆当时的场景并在小组内进行分享讨论。时长为3min，讨论完后我将邀请一位伙伴进行分享。\u003c/p>\u003cp>请问我的指令清晰吗？（\u003cstrong>稍作停顿\u003c/strong>）现在开始。（\u003cstrong>做好计时\u003c/strong>）\u003c/p>\u003cp>下面请A组一位伙伴来做一下分享。谢谢！\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>王方圆：上周跟男朋友沟通中，因为男朋友手机打不开网页，自己就把家里WIFI重启了，她说了三遍让他试一下打开网页，但男朋友始终没有尝试打开网页，这让自己感到很烦躁，如果男朋友在面前，自己会打他。\u003c/p>\u003cp>【A1+】（反思加工）\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>请大家想想今后遇到类似的场景，我们可以如何利用今天所学的三步骤，观察事实、体会感受、述情表达，利用“我看到……，我的心情是……”的句式准确表达自己，试想一下对方听到你的话语时他会有什么样的反应并在小组内进行分享。时长为3min，我将邀请一位伙伴进行分享。\u003c/p>\u003cp>请问我的指令清晰吗？（\u003cstrong>稍作停顿\u003c/strong>）现在开始。（\u003cstrong>做好计时\u003c/strong>）\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>王方圆：如果今后再遇到这类事情，我会告诉他“在重启WIFI之后，我说了三次让你尝试打开网页试试，你都没有去试、只截了一个连接4G网络的图给我，这让我感到很厌烦，我只希望你去操作一下、试试可否打开网页。”这样说完，充分表达了自己的想法后，自己没有再打他的想法了。\u003c/p>\u003cp>【小结】今天我跟大家分享的\u003cstrong>基于事实和感受的述情表达法\u003c/strong>到这就结束了。希望大家在今后的沟通中，多去观察事实、体会感受和述情表达，让自己的\u003cstrong>沟通更加畅通、高效，让自己的关系更加亲密\u003c/strong>。谢谢！当我们陈述自己的时候可以用述情表达，但当我们需要表达自己需求的时候，这还不够，接下来请看第二片段。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":6776,"quote":"\u003cp>【学习目标】\u003cstrong>让学习者在现场运用“感受+需要”表达自己的请求。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们无法给别人我们自己都没有的东西。\u003c/strong>有时，我们会发现自己没有心情去关心别人。一般来说，这反应了我们也需要得到关心。如果告诉他人我们正处于痛苦中，我们无法顾及他们的感受和需要，别人很可能就会伸出援手。\u003c/p>\u003cp>然而，在许多的时候，我们\u003cstrong>需要自己的体贴\u003c/strong>。联合国前秘书长汉马斯克德曾经说道：“\u003cstrong>你越是留意自己内心的声音，就越能够听到别人的声音。\u003c/strong>”一旦我们能够\u003cstrong>敏锐的察觉并照顾自己的感受和需要\u003c/strong>，我们就有能力迅速调整好状态，来倾听他人。如果做不到这一点，我们还有另外两种选择。\u003c/p>\u003cp>\u003cstrong>其中一种选择是大声地提出请求\u003c/strong>。有一次，我应邀去协调两个帮派之间的矛盾。在冲突中，双方都有人死亡。最严重的一个月，一方死了两人，另外一方死了一人。为了帮助他们倾听彼此的意见并找到解决冲突的办法，我紧张地工作了三天。在开车回家的路上，我感到筋疲力尽，我和自己说，我再也不想去协调任何冲突。\u003c/p>\u003cp>可是，一到家，我就看到我的两个孩子在吵架。我没有力气去了解他们的情况，于是，我就大声地提出了我的请求：“我很痛苦！我现在真的不想过问你们的事情！我需要安静！”我年仅九岁的大儿子停了下来，问道：“你愿意和我们说说嘛？”我相信，如果我们能够直接地表达我们的痛苦，那么，即使对方也处于痛苦之中，有时他也能够意识到我们的需要。当然，我并不想冲着孩子大声地喊：“你们怎么回事？你们就不会乖一点吗？我在外面忙了一整天，还不够累吗？”我也不想说别的来指责孩子。\u003cstrong>我大声地提出请求，是为了提醒他们注意我此时此刻的痛苦和需要。\u003c/strong>（附件2：原文片段）\u003c/p>","explains":"\u003cp>【\u003cstrong>行动步骤\u003c/strong>】当大家感觉烦躁时，还有一个人在你耳边不停地说，你会有什么反应？\u003c/p>\u003cp>&nbsp;原文片段告诉我们，当我们有负面情绪时，我们可以通过以下三步：\u003cstrong>一是体会感受，\u003c/strong>参照附件3（感受、想法词）体会自己的感受，可以套用“我的心情是…….”的句式来识别自己的感受。\u003cstrong>二是识别需要\u003c/strong>（需要是非暴力沟通的第三个要求）\u003cstrong>，\u003c/strong>基于感受，去寻找自己有这种感受后当下的需要，可以套用“我需要……”的句式来识别自己的需要。\u003cstrong>三是表达请求\u003c/strong>（请求是非暴力沟通的第四个要求）\u003cstrong>，\u003c/strong>基于感受和当下需求，为了让别人更加清楚的了解我们需要什么，我们需要将自己的需要变成请求准确的表达出来，可以套用“我的感受是……，我需要……”。那么接下来我们一起看看发生在我身上的案例。\u003c/p>\u003cp>【\u003cstrong>意译原文\u003c/strong>】\u003c/p>\u003cp>记得上个月，老公因为应酬多特别忙碌，有一个星期连着4天都在凌晨1点以后回到家。有一天晚上，他凌晨两点多回来，我\u003cstrong>体会感受，\u003c/strong>我很清楚的感受到我非常担心也非常生气。我\u003cstrong>识别需要\u003c/strong>，在那一刻我希望他早点休息，我自己也需要睡眠。最后我\u003cstrong>表达请求，\u003c/strong>我现在有点疲惫也很担心你，我没精力去关注你，我需要一个安静的睡觉环境。没想这一次之后，老公每次回来都静悄悄，不再把我吵醒，且他有机会就会回来得很早，我无形中又感受到了非暴力沟通的魅力。\u003c/p>\u003cp>&nbsp; &nbsp; 【\u003cstrong>预想质疑】\u003c/strong>：也许大家觉得这样有点太费时间，完全没有必要去思考这么多。实际上不那么去做，需要、请求只留在我们内心，他人不明白，最后我们反过来还会责备他人，造成很多的不必要的误解。\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>听完我的讲解，相信大家对表达请求已有了一定的了解，下面我们还是按刚才的A、B两组来进行一次讨论。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>请大家认真听一下要讨论的场景：小明（男）和小丽（女）一对恋人，再过两天就是小丽的生日了，小丽特别重视仪式感，每个生日都要有礼物、有烛光晚餐，而小明近期忙于工作，完全不记得小丽生日的事情，结果到了生日那天小丽没有再次提醒，小明依然不记得，最后两人吵架了、分手了。\u003c/p>\u003cp>请大家讨论一下生日当天发生了什么，是什么导致了最后就分手了。再引用今天所学的表达请求的三步骤，想想小丽和小明分别可以怎样表达自己的请求，避免恶果发生，请提出一个可行的方案。并在小组内进行分享讨论。讨论时间为6分钟，讨论完后我会邀请一位伙伴进行分享。\u003c/p>\u003cp>请问我的指令清晰吗？（\u003cstrong>稍作停顿\u003c/strong>）现在开始。（\u003cstrong>做好计时\u003c/strong>）\u003c/p>\u003cp>下面请二组两位小伙伴来做一下分享。谢谢！\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>小丽（熊亦娴）：亲爱的，我的生日为什么忘了？\u003c/p>\u003cp>小明（陈裕真）：我知道亲爱的比较重视仪式感，本想好好给亲爱的过个有仪式感的生日，但最近工作真是太忙了。\u003c/p>\u003cp>小丽（熊亦娴）：我前天不是提醒过你吗？\u003c/p>\u003cp>小明（陈裕真）：前天正想去给你买礼物，结果突然接到老板电话，要去完成报告，就一直在忙报告，结果给忘记了，没有及时买礼物给你，我自己感到很抱歉、很难过（体会感受）。我希望下次生日可以多提醒一次，我一定给你过一个具有仪式感的生日（识别需要）。希望这次你原谅我，我希望接下来陪你过每一个生日，并都充满仪式感，可以吗？（表达请求）\u003c/p>\u003cp>小丽（熊亦娴）：可以，同意。\u003c/p>\u003cp>&nbsp; &nbsp; 熊亦娴总结分享：通过体会感受、识别需要，最后小丽在听完小明表达完请求之后，自己感到特别感动，责备他的那种想法慢慢淡化了，而转向原谅他，自己内心的愤怒也少了很多，这种感觉很棒。\u003c/p>\u003cp>【A2】催化应用（分步催化1）\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>请大家想想自己在工作、生活或学习中，会在什么情况下发出需要他人支持的请求，想象那样的一个场景（时间、地点、人物、事件），并在小组内进行讨论。讨论时长为3min，稍后我将邀请一位小伙伴进行分享。\u003c/p>\u003cp>请问我的指令清晰吗？（\u003cstrong>稍作停顿\u003c/strong>）现在开始。（\u003cstrong>做好计时\u003c/strong>）\u003c/p>\u003cp>下面请一组一位伙伴来做一下分享。谢谢！\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>Lily：我本月20日就要考试了，考试科目有5科，在未来几天内要去询问杏梅姐关于快速阅读的方法，并将该方法应用于自己接下来的备课中，希望杏梅能支持到自己。\u003c/p>\u003cp>【A2】催化应用（分步催化2）\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>请运用今天所学的表达请求的三个步骤：体会感受、识别需要、表达请求，说出自己的请求并获得他人的支持。先在各组内进行分享，讨论分享时长为5min，稍后我将邀请一位小伙伴进行分享。\u003c/p>\u003cp>请问我的指令清晰吗？（\u003cstrong>稍作停顿\u003c/strong>）现在开始。（\u003cstrong>做好计时\u003c/strong>）\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>Lily:杏梅姐，我这个月20号有个考试，要考5科目，时间比较紧，我自己比较着急了（体会感受），我希望本次备考中能掌握快速阅读的方法（识别需要），你能教教我快速阅读的方法，好吗？（表达请求）\u003c/p>\u003cp>李小军（杏梅）：好啊，我推荐使用思维导图备考，在如何使用思维导图方法我们可以在线下进行进一步沟通。\u003c/p>\u003cp>我问李小军：你听完Lily的话语之后，能听出她的确很需要这个东西吗？\u003c/p>\u003cp>李小军：我能听出，她说了本月20日就考试，且要考5科目，时间比较紧，她比较着急，我很理解也很愿意帮助她。\u003c/p>\u003cp>【小结】今天我跟大家分享的\u003cstrong>基于感受和需要的表达请求法\u003c/strong>到这就结束了。希望大家在今后的沟通中，有需求有请求时，能想到表达请求三个步骤“\u003cstrong>体会感受、识别需要、表达请求\u003c/strong>”，让我们的自己的感受越来越好，让他人也更加清楚我们的需要。谢谢大家！\u003c/p>\u003cp>【结语】我们今天学习了两个片段，首先是\u003cstrong>基于事实和感受的述情表达法\u003c/strong>，接着学习了\u003cstrong>基于感受和需要的请求表达法\u003c/strong>。我也相信，通过这种述情和请求表达的方式，我们可以更好的与自己和他人相处。我的带拆到此完毕，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1508108112000,"updated_at":1508280930000,"ria":true},{"id":3483,"topic":"学会情绪觉察，并掌握穿越情绪按钮的方法。","learn_goal":"学习者能够学会更多地情绪觉察，并了解如何穿越情绪按钮","remark":"拆书家Shooshoo 2-4定级","level":"TF2-4","duration":30,"status":29,"type":0,"chaishujia":{"username":"Shooshoo","city":"合肥"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天的拆书家Shooshoo。经常参加拆书帮活动的朋友可能还会记得我这个 “美食爱好者”“手机拍照侠”和“0.7文青”。人生需要自我突破，但更需要一个团队，一个平台来携手共进，互助双赢。加入拆书帮这个大家庭，是因为我相信一个人可以走的更快，但一群人可以走的更远。希望大家能够在漫长的自我成长之路，相互鼓励，共同进步。\r\n为便于一会的交流讨论，首先我们分下组。今天我们在座的有6位小伙伴，分2组，每组3人。","ratings_count":2,"texts":[{"id":6356,"quote":"\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>F：《爱的五种能力》是国内资深情感教练赵永久先生的著作，他提出的理念是，爱也是一项需要学习和修炼的能力。它不是一种单一的能力，而是多种能力的综合。包括了五种具体的能力，有了这五种能力，无论跟谁生活，都会容易幸福。\u003c/p>\u003cp>A：这本书是国内第一套系统的爱情理论，相对于国外很多著作，它更贴近国内婚恋状况的实际，细数国人情感认知误区，很容易引发共鸣。书中囊括了改善情感关系中最为本质且有效的技巧，包括如何觉察情绪，述情黄金句式，共情（感同身受，将心比心）基本功训练等等。这些毫不花哨却效果斐然的技巧让无数的读者惊喜，他们不仅口口相传，甚至买了多本赠送亲朋好友。同时，也有很多情感心理大咖反复为这本书打call。\u003c/p>\u003cp>B：每个人都想把握幸福，在感情之路上打怪升级修成正果。但感情问题难免出现障碍，比如无法沟通，难以理解，拒绝接纳这样的困难。 从而帮助我们促进人际关系和谐，提高亲密度，成就婚姻幸福。\u003c/p>\u003cp>我们今天将要学习的知识点，不仅传授了情感沟通的“术”，更是点出了情感沟通的“道”。当你抓住其中精髓，你会发现，很多问题，将不再是问题。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【原文片段】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>下面，就让我们一起来看一下今天要拆解的第一个图书片段——\u003c/p>\u003cp>\u003cbr> \u003cstrong>做情绪的主人：觉察\u003c/strong>\u003c/p>\u003cp>如果这是在事情发生的当时，你能觉察到你有情绪了，就有机会管理这个情绪，做情绪的主人。如果觉察不到，就可能被这个情绪控制，情绪是你的主宰者。有些人会被情绪驱使做出一些令自己后悔的事情，而在事情发生后才意识到自己做了什么。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 诸多负面的情绪，犹如一些潜藏在人内心里的恶魔，它们时常跟人争夺对人体的控制权，如果人没有体察情绪的意识，就有可能经常被这些“恶魔”控制，很多做错事的人，事后都常说这类的话：“我并不想那样做的，但我控制不了自己。”“我当时脑子里一片空白，根本不知道自己在做什么！”有时事后甚至会恨自己。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 人们需要战胜心中的恶魔，管理好自己情绪，做自己主人，就需要带着觉察去生活，这需要刻意的练习，才能做到或做得更好。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 情绪作为我们人类心理的重要功能，是时刻都存在的，只不过大多数时候我们的情绪是平静的，这时我们好像没有什么感觉。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 其实不是没有感觉，而是感觉到了平静，平静也是一种感觉。就像水的温度，零度也是温度，那些负面的情绪像是零下的温度，正面的情绪像是零上的温度，平静像是零度，零度的水不是没有温度，平静也不是没有感觉，是一种非常舒服的感觉，并且是我们多数时间的感觉，说明你整个人处于一种和谐的状态当中，潜意识不需要提示你什么。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 情绪会随着生活中发生的各种事情有起有伏，可是有的人能够时刻觉察到自己的情绪，有的人觉察不到，觉察不到的人就容易被情绪控制着做些情绪化的事情，也就是受情绪的支配做些事情。人在被情绪支配的时候所做的事情，基本都是为了快速地宣泄情绪而做事情，当然也就想不起来要做情绪管理。 \u003c/p>\u003cp>找个小本子和一支笔，随身带在身上，或者用手机也可以，一旦觉察到内心有了情绪，情绪上不再是平静时，随时随地就记录下来\u003c/p>","explains":"\u003cp>\u003cstrong>【学习目标】跟随完成这个RIA现场学习后，学习者可掌握情绪觉察能力的提升方法,提高对日常生活中对自我情绪的感知和理解。\u003c/strong>\u003c/p>\u003cp>好的，相信大部分小伙伴已经看完了这个片段。\u003c/p>\u003cp>\u003cstrong>（预防异议）\u003c/strong>有的小伙伴可能会觉得有些小题大做，情绪谁没有呀，还用特意想办法去觉察它发现它吗？哈哈，就是因为情绪在每个人身上时时刻刻都可能发生，它对我们的日常生活影响才至关重要。就像呼吸空气一样，我们每天都在呼吸，但并不觉得这是一件大事，甚至意识不到它。但是如果有一天，空气质量和可用量受到严重影响，你才会发现连自己最基本的生命安全都受到了威胁。\u003c/p>\u003cp>\u003cstrong>（举例）\u003c/strong>很多铸成大错的人都会说这样的话：我也不知道怎么了，根本控制不了我自己,不知道做了什么。像前段时间大火的江歌案凶手陈世峰，他不仅多次暴打自己的前女友刘鑫，甚至情绪失控时砍伤无辜的江歌十几刀致死，等事情无法收拾了才悔恨不已。 可见，人如果没有体察情绪的意识，就很容易被负面情绪的恶魔所控制。\u003c/p>\u003cp>\u003cstrong>（细化行动步骤）\u003c/strong>咏春拳一代宗师叶问曾对来学武的李小龙说：练武不练功，到老一场空。想要管理情绪，做自己的主人，就要带着觉察去生活，而这只有通过刻意练习才能做到或做得更好。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 一．\u003cstrong>我们要做的首先是感知自己的情绪。\u003c/strong>当我们心绪有所起伏的时候，闭上眼睛，将注意力集中到当时的情绪上：现在我的情绪处于正值还是负值？更具体一点，它是兴奋、激动、自豪 还是焦急、愤怒、委屈？当你愿意去观察自己的情绪，在脑海中植入意识，就是在内心种下了觉察的种子。\u003c/p>\u003cp>\u003cstrong>二．仅仅感知到就够了吗？答案是否定的。情绪的觉察也是一种能力，需要不断练习。原文给出了一个非常行之有效的方法，\u003c/strong>那就是随身携带纸笔（当然用手机备忘录也是可以的），随时记录自己的情绪，完成后即可大幅提高自己的情绪觉察能力，在情绪起来的第一时间就能觉察到，使情绪管理成为可能。\u003cstrong>比如说，情绪的出现原因是什么，是外部环境还是内心压力？比如抽烟的朋友每次抽烟是否都处于焦虑期？每次生气是不是都是因为类似的小事？知道坏情绪形成的原因，才知道好习惯如何养成。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们可以通过这些元素优化出一个格式，让记录更精确，甚至方便后期分析：\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>时间\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>地点\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>事件\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>情绪\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2017/10/20\u003c/p>\u003cp>8:50am\u003c/p>\u003c/td>\u003ctd>\u003cp>地铁上\u003c/p>\u003c/td>\u003ctd>\u003cp>去公司上班\u003c/p>\u003c/td>\u003ctd>\u003cp>很着急\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>\u003cstrong>【A1 激活经验】\u003c/strong>\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>（显像提问法）请大家回忆一下，在你们最近的工作生活中，有没有明显的起激烈情绪的情况。比如你跟你的合作方沟通不畅，他误解了你的意思，让你很抓狂；或者，当你看到商场里浓郁的圣诞气息，孩子们的笑容，又是什么样的心情？\u003c/p>\u003cp>可以根据我们最新学习的情绪记录表格，记录一下当时的情况。描述情绪的用词尽量详细精准。每位同学不少于两条，不多于三条。\u003c/p>\u003cp>请稍作思考和讨论，一会我将邀请小伙伴给大家分享一下。\u003c/p>\u003cp>&nbsp;\u003cstrong>（学习者案例分享记录）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>学员：我写了两条，给大家分享一下：\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>时间\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>地点\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>事件\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>情绪\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>昨天早上\u003c/p>\u003c/td>\u003ctd>\u003cp>在公司\u003c/p>\u003c/td>\u003ctd>\u003cp>领导把重要发票弄丢了，让我去甲方公司找财务要第一联单扫描复印\u003c/p>\u003c/td>\u003ctd>\u003cp>愤怒：\u003c/p>\u003cp>不是自己的问题却在收拾烂摊子\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>前天\u003c/p>\u003c/td>\u003ctd>\u003cp>家\u003c/p>\u003c/td>\u003ctd>\u003cp>爸爸给我打电话，说他在医院住院了，让我注意身体\u003c/p>\u003c/td>\u003ctd>\u003cp>低落，悲伤：\u003c/p>\u003cp>长这么大了没有关心到父母，却让父母反过来关心我\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【A1+】\u003cbr>\u003c/p>\u003cp>\u003cstrong>Shooshoo:\u003c/strong>那么，下次再遇到类似的情绪，我们是不是可以用今天的方法，先去正视内心的情绪呢？\u003c/p>\u003cp>\u003cstrong>学员：\u003c/strong>是的，在感受到这样的愤怒或悲伤之后，我不会再回避、忽视或者一味陷进去，而是会平静地去觉察它们，然后及时记录下来，好更加了解自己。\u003c/p>\u003cp>\u003cstrong>Shooshoo:\u003c/strong>赞一个，我相信通过你的觉察和记录积累，你也可以通过分析，更加了解自己的情绪和内心变化，并对此有更加敏锐的感知力！\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>刚才，我们一起学习了情绪管理的第一步：觉察。当然，要实现我们身心灵的成长，强化情绪管理的经营能力，\u003cstrong>这只是最基础的知识。下面的片段将会给大家带来一种更为具体深入的情绪管理方法（与下一片段的逻辑关系），\u003c/strong>掌握之后相信可以让你亲密关系经营能力不断提升。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":6357,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>下面，就让我们一起来看一下今天要拆解的第二个片段——\u003c/p>\u003cp>\u003cstrong>情绪管理方法二：穿越“情绪按钮”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>儿时受到的伤害越多的人，情绪按钮越多，这样的人在成人后的生活中，尤其是情感关系里情绪也就越多，进而影响到个人的人格魅力和情感关系的稳定。 \u003cbr> &nbsp;&nbsp;虽然人人都有情绪按钮，但因为人的经历不同，可能会导致的情绪按钮也不同；即便相同的经历，有的人会留下情绪按钮，有的人不会。 \u003cbr> &nbsp;&nbsp;人的各种心理障碍，其实就是较为严重的情绪按钮。比如有人对开车的恐惧，有人对某个形状的食物的恐惧、有人对唱歌的恐惧，等等。 \u003cbr> &nbsp;&nbsp;需要特别说明的是，情绪按钮并非完全是由过往经历中的伤害导致的。人的心本来就是脆弱的，成长过程中没有得到历练、成长、变强大的部分，依然脆弱。一旦被触碰，也会起情绪，这也是一些情绪按钮形成的原因，属于未成长好的脆弱。\u003c/p>\u003cp>\u003cstrong>情绪按钮被唤醒时，为了摆脱情绪，人们一般会采取逃避的方法。\u003c/strong>比如一个怕狗的人，潜意识认为狗是有危险的，看见狗就远远地躲着走。这样可以不用感受内心的恐惧，但这也使他失去了穿越情绪按钮、战胜内心恐惧的机会。 \u003cbr> &nbsp;&nbsp;&nbsp; 如果要穿越情绪按钮，人们需要直面内心的恐惧，挑战自己。怕狗的人在狗出现的时候，也就获得了克服对狗恐惧的机会。 \u003cbr> &nbsp;&nbsp;&nbsp; 穿越“情绪按钮”的方法 \u003cbr> &nbsp;&nbsp;&nbsp; 情绪按钮被触碰时，内心的情绪被唤起，如果此时，人们不逃避，不转移注意力，感受着内心的情绪，同时做深呼吸，就可以逐渐穿越情绪按钮。 \u003cbr> &nbsp;&nbsp;&nbsp; 具体步骤： \u003cbr> &nbsp;&nbsp;&nbsp; 1．一旦觉察到情绪按钮被触碰，\u003cstrong>感受着内心的情绪，不要转移注意力。\u003c/strong>如果可以承受的话，不要逃避内心的痛苦，注意力集中在情绪上，一直感受着情绪，直到情绪慢慢消退。 \u003cbr> &nbsp;&nbsp;&nbsp; 2．同时做\u003cstrong>深呼吸\u003c/strong>，把气吸到腹部，这样胸腔下方的横膈膜会下降，腹部鼓起，肺部底端肺泡里的废气得以和氧气充分交换。 \u003c/p>\u003cp>每一次情绪按钮被触碰时，都做这个“穿越”的练习，情绪按钮就会被消除一部分，假以时日，情绪按钮就会被彻底消除。穿越之后，人的内心由敏感变强大，别人再次触碰情绪按钮时，原来的情绪就不会再被唤醒。\u003c/p>","explains":"\u003cp>\u003cstrong>【学习目标】跟随完成这个RIA现场学习后，学习者可以掌握如何“情绪按钮”的穿越方法，并在近期主动识别并穿越自己已有的情绪按钮。。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>好的，多数小伙伴已经看完了这个片段，\u003cstrong>上一片段我们一起学习了情绪管理的基础：觉察，那么这一片段我们将更要深入学习情绪管理的一些具体方法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（预防异议）\u003c/strong>也许有的小伙伴要说了，第一次听说这个概念，我好像没有情绪按钮啊？其实，情\u003cstrong>绪按钮是一种心理机制，它并非某些人特有，而是每个人都有的，只不过有的人多些，有的人少些，多的人敏感脆弱，少的人呢，就会十分淡定坚强。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（强调不这么做的坏处）\u003c/strong>通过这些情绪按钮，别人就可以像控制机器人一样控制我们，只要一触碰情绪按钮，我们就会有固定的情绪反应。受情绪按钮的影响，他人在无意中的行为，瞬间能让你情绪爆炸，一发不可收拾。而自己随口一句话，也可能让别人怒发冲冠，而你还一脸蒙圈，不明白发生了什么。这样的例子在生活中真是比比皆是。\u003cstrong>人在“情绪按钮”被触碰后头脑中的一些想法通常是非理性的，人们容易在此时形成偏执的想法，演化成各种心理障碍。 一旦触动了情绪按钮，人就难以控制自己的行为，为情绪所左右，做出让自己后悔的事情来。 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>（细化行动步骤）所以说，\u003c/strong>情绪按钮并非无法克服。每一次情绪按钮被触发的时候，都是一次穿越它的机会。那么具体要怎么做呢？\u003c/p>\u003cp>\u003cstrong>第一，正视并感受。\u003c/strong>\u003c/p>\u003cp>回避不愉快的感受是人之常情，但选择直面才是强者的必经之路。当情绪起来的时候，看着它，问问自己，我现在是什么感受？具体地说，现在到底是哪一种情绪占据了我？这就要用到我们前一个片段说到的觉察方法，勤加练习，就会对自己的情绪越来越敏感。\u003c/p>\u003cp>\u003cstrong>第二，深呼吸（关闭情绪脑）。\u003c/strong>非理性情绪占据了你的大脑，就把肺叶里的废气最大程度的置换出去！每一次深呼吸都是滤清自己的过程。当然，这里说的深呼吸不仅指的是一种呼吸方式，其更深层次的含义是通过一种方法制造情绪隔绝，及时关闭“情绪脑”。\u003c/p>\u003cp>\u003cstrong>第三，情绪溯源。\u003c/strong>通过对片段中“情绪按钮”的深度理解，我们还可以延伸出这一心理障碍的根治方法：当你经过第一步和第二步得以冷静下来，那么请再多问自己一个问题：\u003cstrong>我为何会对此起这种情绪？它从何而来？我是否还应该受它影响？\u003c/strong>弄清楚病源在哪里，才能对症下药。当你看清楚深埋在心的是曾经的伤害对你的后遗症，或是曾经的弱势带来的产生的恼羞成怒，那时候，告诉自己，应当放下，你已经不是曾经的自己，你已经成长了，而且会不断成长下去，所以勿须让这过往的伤痛跟随你一生。\u003c/p>\u003cp>\u003cstrong>（举例）\u003c/strong>这样的例子有很多。情绪按钮一方面是由过往经历中的伤害导致的（比如我们说“一朝被蛇咬十年怕井绳”）。而另一方面，成长过程中没有得到历练、变强大的部分，一直很脆弱，一旦被触碰，也会起情绪。（比如一个人一紧张就说话结巴，多年来没得到改善，也会特别介意人提起这件事情）。\u003c/p>\u003cp>在座的不知道有没有哈迷，哈利波特第三部阿兹卡班的囚徒里有一幕非常让人印象深刻，就是黑魔法防御术课上，老师在课堂上放了一个神奇的柜子，里面的生物会变成你内心深处最恐惧的东西，从而控制你。罗恩的是蜘蛛，纳威是他严厉的祖母，而哈利是他父母的死。这也是一个非常典型的触发和穿越情绪按钮的例子。\u003c/p>\u003cp>而我的一个朋友，就曾经遇到这样的问题：她对争执中别人表现出来的暴力倾向过分的敏感和恐惧，导致破坏了好几段亲密关系。情侣之间难免有分歧和争吵，但是每次当男友提高音量，不复平时的温柔和善时，她就受惊过度，急于想结束这段关系，逃离这个“凶暴”的男人。而她也常常在痛苦中迷惑：难道她就找不到一个始终温和儒雅的伴侣吗？\u003c/p>\u003cp>我们知道，始终保持温和儒雅，是违逆人类本性的，人都有生气暴躁的时候，俗话说兔子急了还咬人呢！其实我们在那位朋友平时交流中透露的信息可以知道，她从小成长在一个存在家暴恶习的家庭，眼睁睁目睹母亲被父亲施暴多年，在心理上存在巨大的阴影。因此她特别惧怕男友表现出的暴力倾向，也害怕遇到父亲那样的人，重复母亲遭受的痛苦，导致她在一段又一段的恋情失败。\u003c/p>\u003cp>\u003cstrong>（反转）通过我们今天学习的方法，她就可以通过以下几个步骤去正确引导自己，主动去穿越这个情绪按钮：\u003c/strong>\u003c/p>\u003cp>①&nbsp; 正视并感受自己的情绪：每次他对我大吼大叫，我很害怕，随之产生退缩分手的想法；\u003c/p>\u003cp>②&nbsp; 深呼吸，冷静下来，不要让当时情绪控制自己，不要做过多争执；\u003c/p>\u003cp>③&nbsp; 思考追溯：为什么会像现在这样对于一种正常的反应显得过度敏感惊惧？追溯到童年阴影及形成的未痊愈伤痕，理清情绪。\u003c/p>\u003cp>那么下次，可以平心静气的对待类似的事情，战胜心理惯性，收获一段美满的关系。\u003c/p>\u003cp>\u003cstrong>（适用边界）\u003c/strong>我们今天所介绍的情绪按钮穿越技巧并不是万金油，暂时只适用于浅层次情绪管理。\u003c/p>\u003cp>\u003cstrong>（正面+好处）\u003c/strong>但每一次情绪按钮的穿越，都会给人生带来巨大的成长。能克服情绪按钮的人，势必会成为一个心智越来越成熟的人。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 我们刚才一起学习了解了如何穿越情感按钮的基本方法。那么，现在让我们设想这样一个场景进行演练：\u003c/p>\u003cp>你和你的男（女）朋友或爱人计划了很久的旅行，当你向领导请了假，机票也订好了，甚至行李都打包完毕。这时候，对方告诉你他因事去不了了。你瞬间大发雷霆，闹得不可开交。其实时候你心里也明白TA这次是工作需要迫不得已，并非有意失约，但你就是控制不了你自己，好像打从心底特别反感被放鸽子这件事。\u003c/p>\u003cp>\u003cstrong>（也可以举出自己的类似案例）\u003c/strong>\u003c/p>\u003cp>那么学习了第二个片段以后，根据所学的方法（一）感受并正视；（二）深呼吸（关闭情绪脑）；（三）情绪溯源。\u003c/p>\u003cp>\u003cstrong>你对于类似的情绪按钮，有什么样的新的理解和认识？\u003c/strong>\u003c/p>\u003cp>演练时间5分钟，现在开始，5分钟后我会请1组小伙伴分享一下他们的处理方式。\u003c/p>\u003cp>\u003cstrong>（学习者案例分享记录）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>你为什么不能去？请你给我一个合理的解释。\u003c/p>\u003cp>\u003cstrong>学员B（丈夫）：\u003c/strong>虽然之前我们约好了，我也跟公司打了报告请假了。但是因为这个项目很关键，我也是主要负责人。如果我走了，这个项目肯定就没办法进行下去，这样的话我们公司就会遭受比较大的损失，所以领导就临时把我叫回来了。我也没有办法，我内心也很愧疚，但是我觉得旅行这件事，这次我没有做到，我下一次一定会弥补你，或者我下一次一定会陪你去。\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>我重要还是公司重要？这已经是你第几次失约了？你告诉。\u003c/p>\u003cp>\u003cstrong>学员B（丈夫）：\u003c/strong>肯定是你重要，但是另一方面说，如果这次我不在导致公司大笔经济损失，那我在公司以后的晋升肯定会受到影响。\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>那你有没有站在我的角度为我想一想呢？你只考虑到工作，这对我不公平。\u003c/p>\u003cp>\u003cstrong>学员B（丈夫）：\u003c/strong>我这么努力也是想为你创造一个更好的条件。如果我晋升到一定职位，以后假期一定会多一些，有更多的时间陪你。\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>公司离开你就不能转了吗？我就是想要你这一次陪我，我不要下一次，关于下一次的承诺我不相信了。\u003c/p>\u003cp>\u003cstrong>学员B（丈夫）：\u003c/strong>那你说我们应该怎么办？\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>跟我一起走吧，其他的解释我不接受。\u003c/p>\u003cp>\u003cstrong>学员B（丈夫）:\u003c/strong>可以，我现在就打电话给我老板说我辞职，我要陪媳妇去旅行。\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>那是你的问题我不管。\u003c/p>\u003cp>\u003cstrong>学员B（丈夫）:\u003c/strong>我就是想让你明白，我们暂时开开心心地去旅行以后我要怎么办。去再找工作吗？\u003c/p>\u003cp>\u003cstrong>两人不欢而散。妻子忿忿不平，打电话给对闺蜜（学员C）诉苦。恰巧这位闺蜜\u003cstrong>上过拆书帮Shooshoo老师关于情绪按钮穿越课程。\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学员C（闺蜜）\u003c/strong>\u003cstrong>：\u003c/strong>亲爱的，原来是这样。如果我是你，期待了那么久的旅行被放鸽子，我也会很失望很不爽。\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>就是的嘛！气死我了！\u003c/p>\u003cp>\u003cstrong>学员C（闺蜜）\u003c/strong>\u003cstrong>：\u003c/strong>亲爱的，事已至此，你就也想开点先。女人生气老得快哦~哈哈！\u003c/p>\u003cp>然后，我们把整个事情捋一捋先。你老公对失约这件事情感觉到很抱歉，那种迫不得已的情况下，他在不断地对你解释，你却非常生气，认为他失约了，说话不算话，打乱了你们所有的计划和你对他的期待，对不对？你觉得你这次一定要去，否则也不能相信他关于下一次的承诺和对你许诺的补偿？\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>是的。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cstrong>学员C（闺蜜）\u003c/strong>\u003cstrong>：\u003c/strong>\u003cstrong>\u003c/strong>你有没有注意到，在他对你反复解释安抚的情况下，你依然起这样的情绪，其实有点儿不太正常？回想一下，是不是曾经的经历对你造成了影响？\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>因为他已经爽约过很多次，我已经不相信他。对于他的承诺，我脑海里就三个字：我不听！\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cstrong>学员C（闺蜜）\u003c/strong>\u003cstrong>：\u003c/strong>\u003cstrong>\u003c/strong>所以亲爱的，我可不可以这样理解：他过往反复的失约经历，以及对你的心理造成了影响，形成了一个情绪按钮。所以当他每次再次失约的时候，就相当于按下了这个按钮，就像启动引擎一样，让你大发雷霆。实际上你并不是不知道这次失约可以理解，但是你就是不想接受他失约的这个现实。\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>是的。这个情绪按钮以及触动了，然后爆炸了。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cstrong>学员C（闺蜜）\u003c/strong>\u003cstrong>：\u003c/strong>然后这场大战就爆发了，双方都觉得不可调和。要么就一起去，可是一起去诗与远方了，回来以后面包怎么面对？\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>是的，况且，即使他再陪我一起去，我的心里也有疙瘩。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cstrong>学员C（闺蜜）\u003c/strong>\u003cstrong>：\u003c/strong>\u003cstrong>\u003c/strong>所以就等于一个情绪按钮被触动，原地爆炸不可收拾。那我们能不能尝试穿越这个情绪按钮呢？首先，你有没有意识到当时争吵的情绪是怎么样的\u003cstrong>（正视和感受情绪）？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>非常愤怒和委屈，又一次事到临头失约。我觉得他不在乎我。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cstrong>学员C（闺蜜）\u003c/strong>\u003cstrong>：\u003c/strong>\u003cstrong>\u003c/strong>好的，那我们感受到这个愤怒，深呼吸一下（隔绝情绪），是不是觉得稍微冷静一点？\u003c/p>\u003cp>\u003cstrong>学员A（妻子）（深深吸气）：\u003c/strong>是的，至少不再想直接冲着他大喊大嚷了。\u003c/p>\u003cp>\u003cstrong>\u003cstrong>学员C（闺蜜）\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/strong>太好了，你看嘛亲爱的，一场大战可能就能避免了。我们知道你老公这次失约虽然让人不开心，但归根到底原因却是合理充分的，再吵闹下去也是没有结果。\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>是的。\u003cstrong>（情绪溯源）\u003c/strong>我虽然依然感觉不开心，但我了解到，是老公之前的失约行为已经在我心里形成了情绪按钮，对吗？\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cstrong>学员C（闺蜜）\u003c/strong>\u003cstrong>：\u003c/strong>知道自己这次的情绪并不是简单地针对这件事本身，而是来源于由来已久的情绪按钮被触发，亲爱的，你是不是能心平气和的面对和处理这件事呢？\u003c/p>\u003cp>\u003cstrong>学员A（妻子）：\u003c/strong>是的，我应该不会那么生气，而是坐下来跟老公好好谈谈，表达下自己的委屈，同时跟他计划好补偿和下一次旅行。\u003cstrong>（对学员B：）\u003c/strong>老公，我明白，这次你是真的迫不得已才失约的，\u003cstrong>但我受到了之前爽约经历的影响，一下子就爆炸了。\u003c/strong>你以后答应我的事一定要尽量安排好哦，而且，这次你不能去的话，可要好好补偿我呢！\u003c/p>\u003cp>\u003cstrong>学员B（激动）：\u003c/strong>当然了老婆！还是你最善解人意！\u003c/p>\u003cp>\u003cstrong>Shooshoo:\u003c/strong>太棒了！大家请给三位优秀的小伙伴鼓掌！\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请各位小伙伴，根据自己已知的情绪按钮，运用三个基本方法，设想一下，如果再次发生别人碰触到你某个情绪按钮的情况，你打算如何穿越?\u003c/strong>\u003c/p>\u003cp>比如说，你曾因为犯了一个低级错误，某总监狠狠的训斥了一通。这件事对你打击很大，每次想起来你都感到很羞愧，并且你对这位总监产生了非常深刻的恐惧心理。平时工作的时候，你总是能不找他就不找他，能绕着走就绕着走，甚至跟他说话，看着他的脸都会让你紧张万分，没法好好表现自己。于是他对你更是颇有微词。但是非常不巧的是，下周公司安排了一个项目，由你作为负责人，而该总监正是你的直接汇报人。你将怎样通过这样一个机会，主动去穿越那个两三年来的情绪按钮？\u003c/p>\u003cp>或者你有一些其他类似的案例，请加工一个你可能会遇到的具体例子，讨论一下，稍后我会请小组代表给大家分享。\u003c/p>\u003cp>\u003cstrong>（学习者案例分享）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学员D\u003c/strong>\u003cstrong>：\u003c/strong>我生活中作为一个父亲，孩子上小学，正处于狗都嫌的年纪。平时孩子不听话的时候是很多的。从理性上，我平时看了很多育儿的书，包括正面管教等等，我也知道孩子的脾气需要被了解被感知。但当他说“我不，我就不”的时候，我的脾气马上就爆发，按耐不住就想抽他。其实我感觉这就是一种情绪按钮。\u003c/p>\u003cp>这样分析的话，可能跟我母亲对待我的方式有关。我母亲是个脾气比较暴躁的人，我小时候如果有什么事情做不好的话，她就一通训。我平时对待同事和朋友都是非常温和的人，但是对待孩子就会突然变得暴躁。这么一想，可能就是我的母亲对于我的管教方式，对我造成了影响——我的潜意识里就觉得孩子不听话就得训。所以我遇到类似的问题就不受理性控制了，每到这时候我的情绪就被激发起来。\u003c/p>\u003cp>如果再遇到这样的情况，经过\u003cstrong>情绪溯源\u003c/strong>，我已经了解了这个情绪按钮从何而来，后面如果遇到孩子这种不听话而我又想大发雷霆的情况，按照今天学习的内容，我将会：\u003c/p>\u003cp>\u003cstrong>深呼吸，隔绝情绪，努力让自己先平静下来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>然后\u003c/strong>问自己：我现在很生气，但我为什么会生气？是因为他的行为还是我内心长久埋藏的芥蒂？哦，原来是情绪按钮的触发。那为什么他会反抗？可能他有他的想法。接下来跟孩子进行平等沟通：他为什么不想这样做？去了解他的心理。\u003c/p>\u003cp>\u003cstrong>Shooshoo:\u003c/strong>非常棒！请大家为这位小伙伴出色的学习和实践能力鼓掌！\u003cbr>\u003cbr>\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>今天我们一起学习了两个片段，了解了觉察在情绪管理中的基础作用，掌握情绪觉察训练方法，并且进一步具体化了情绪管理的方法之一—穿越情绪按钮。希望大家能通过对此的了解，抓住这些方法的精髓，早日学会做情绪的主人，营造幸福快乐的人生。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1503492150000,"updated_at":1503497780000,"ria":true},{"id":3482,"topic":"掌握述情句式：“事实+感受”","learn_goal":"学习者能够学会用“事实+感受”进行述情，客观表达，避免争吵","remark":"拆书家Shooshoo  2-3定级","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"Shooshoo","city":"合肥"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今晚的拆书家Shooshoo。经常参加拆书帮活动的朋友可能还会记得我这个 “美食爱好者”“手机拍照侠”和“0.7文青”。欢迎大家加入拆书帮这个大家庭，不仅是为了让自己变得更优秀，同时也为了结识优秀的你们。希望大家能够相互鼓励，共同进步。","ratings_count":0,"texts":[{"id":6355,"quote":"\u003cp>【图书介绍】\u003c/p>\u003cp>F：《爱的五种能力》是国内资深情感教练赵永久先生的著作，他提出的理念是，爱情需要学习，婚姻需要练习。人不是生而会爱，生而懂爱。爱也是一项需要学习和修炼的能力。但它不是一种单一的能力，而是多种能力的综合。包括了五种具体的能力，有了这五种能力，无论跟谁生活，都会容易幸福。\u003c/p>\u003cp>A：这本书是国内第一套系统的爱情理论，相对于国外很多著作，它更贴近国内婚恋状况的实际，细数国人情感认知误区，很容易引发共鸣。这本书一经推出便荣获豆瓣9.1分高分的推荐，口碑极好。著名心理学家杨凤池、麻辣情医吴迪等大咖都倾情推荐，甚至有许多读者买了几本几十本用来送人，希望更多的朋友能习得爱的能力，获得幸福。\u003c/p>\u003cp>B：如果你急需正确经营婚姻恋爱关系的方法，帮助你突破情感桎梏，那么这本书就是你最好的指引。而今天所学的知识点，将会帮你有效减少矛盾和争吵，让生活各方面关系都更容易走向和谐。\u003c/p>\u003cp>【原文片段】\u003c/p>\u003cp>实际在生活中，爱人如果做了一件事情或说了一句话，自己感觉到很不舒服，人们通常有两种做法，都是容易伤害到关系的： \u003cbr> &nbsp;&nbsp;&nbsp; 一些人是\u003cstrong>忍着\u003c/strong>，把不舒服的感觉压抑到内心深处，\u003cstrong>委曲求全\u003c/strong>。 \u003cbr> &nbsp;&nbsp;&nbsp; 等有一天你实在无法承受，你可能对他大发雷霆，这时他就蒙了，他会想不明白，为什么以前你都能接受，而这次你就接受不了呢？他甚至会联想到你是不是外边有人了，不再喜欢他了。如果真是这样的话，对你们的关系影响就大了。\u003c/p>\u003cp>还有一些人常用的方法就是\u003cstrong>发飙，指责或抱怨对方\u003c/strong>，甚至攻击对方.” \u003cbr> &nbsp;&nbsp;&nbsp; 这样说完内心是很爽的，但可能会伤害到对方，让对方感觉你不接纳他，对你们的关系可能会有伤害。 \u003cbr> &nbsp;&nbsp;&nbsp; 因此，这两种方法都是不可取的，最好的方法是告诉对方你的感受，使用述情的\u003cstrong>两个基本功：事实\u003c/strong>\u003cstrong>+ 感受\u003c/strong>。 \u003cbr> &nbsp;&nbsp;&nbsp; \u003cstrong>述情就是这样：只说事实+感受，就能起到很好的效果，既让对方明白了你的感受，又不会伤害两人的关系，是在情感关系以及各种人际关系中的最佳沟通方式。\u003c/strong> \u003cbr> &nbsp; 还有一种情况，就是当爱人做了一件令你很开心的事情时，也就是说这件事情是你很希望他做的，你也需要使用这个句型，来告诉他你很喜欢他这样做。他的这种行为就会慢慢地越来越多，你就会有越来越多的幸福和开心的时刻。\u003c/p>","explains":"\u003cp>\u003cstrong>【学习目标】学习了该片段之后，学习者能够理解并掌握黄金句式之一“事实+感受”，并在日常生活中有意识地运用，改善述情能力。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>在座的朋友们，我们都知道,越来越多人重视精神生活的今天,情感生活的和谐依然在其中占着举足轻重的位置。当我们越来越多的看到日常生活或新闻信息中充斥着各种情感受挫的案例,我们的直观感受是什么？是不是会感觉，现代人的情感经营能力其实是十分欠缺的？\u003c/p>\u003cp>\u003cstrong>（预防异议）\u003c/strong>也许有的小伙伴要说，说话我还不会么？中国的俗话说，一句惹人笑，一句惹人跳。每个人都会说话，但不一定会好好说话，尤其跟熟人更是不注意，话一出口，覆水难收，就造成很多不必要的争吵。\u003c/p>\u003cp>赵老师告诉我们，之所以会不断的出类似的问题，其实是我们并没有懂得如何有效“述情”，即正确地表达自己的感受和想法。连沟通都成问题，又谈何创造幸福呢？在片段里，赵老师给出了一个黄金句式,那就是在交流中，尽量使用“事实+感受”的叙述结构。虽然这不是解决所有问题的万金油，但熟练使用，不仅能改变一些错误的思维模式，也可以帮助我们避免很大一部分争吵。\u003c/p>\u003cp>\u003cstrong>深度挖掘+扩展思维：\u003c/strong>\u003c/p>\u003cp>说到这里，也许有的小伙伴要问了，如何正确把握“事实＋感受”呢？\u003c/p>\u003cp>\u003cstrong>第一步：什么叫做事实？我们如何保证自己叙述的是事实？\u003c/strong>\u003c/p>\u003cp>1.请在场学员思考并提问\u003c/p>\u003cp>2.总结并讲解：\u003c/p>\u003cp>百科：事实是指事情的真实情况，包括事物、事件、事态，即客观存在的一切物体与现象。\u003c/p>\u003cp>我们注意它的一个关键特性：客观。所以，我们如果想在述情的时候保证自己叙述的是客观事实，首先要做到的就是：只叙述事情存在的过程和状态，不要加入自己的主观判断和加工，不要说“我感觉”，“我认为”，“我觉得”。一旦在本该就事论事的情况出现主观感性的理解，就等于是在把自己加工过的意志强加给对方，必然无法让对方做到坦然接受，无法心平气和的听你说话，甚至产生抵触心理，引起争论和反驳。\u003c/p>\u003cp>比如，我们说：“我觉得小张这个人工作不认真”,”小王做事太粗心大意”，那么听的人会不会觉得你的说法太过武断没有说服力？甚至嘴上不说，但在心里反驳你？这就是因为你表达的仅仅是你的主观想法。如果你这样说：“上次小张在上班时间低头玩了一个多小时的手机”“小王上周会议做的不到500字的材料，出现了好几处错误。”事实一出，就很难有反驳的余地，不用过多评价，听的人也能感觉到小张的不认真和小王的粗心大意。\u003c/p>\u003cp>\u003cstrong>第二步：如何更好的表达感受？\u003c/strong>\u003c/p>\u003cp>表达感受相信我们都会，但你会很好的表达感受吗？举个例子，如果要表达因为对方做的一件事导致你“不太开心”，你们一般会怎么说？\u003c/p>\u003cp>1.请学员思考并分享\u003c/p>\u003cp>2.总结并讲解：\u003c/p>\u003cp>①在表达感受时，首先要避免针对对方而展开抱怨指责，而只是从我出发，描述自己的情绪和感受；\u003c/p>\u003cp>②尽量使用精确程度更高的情绪形容词，比如：\u003c/p>\u003cp>开心：兴奋、激动、满足、惊喜、崇拜、幸福感爆棚等等\u003c/p>\u003cp>难过：郁闷、失望、委屈、愤怒、心里不平衡、空虚寂寞冷等等\u003c/p>","interaction":"\u003cp>\u003cstrong>A3 促动学习者的现场演练\u003c/strong>\u003c/p>\u003cp>那么，现在我要请小伙伴们设想这样一个场景：\u003c/p>\u003cp>如果你今天工作强度非常大，人也很累，回到家并不想像平时那样准备晚饭。但是你的爱人是个不太愿意吃外卖的人，而且他由于加班，比你回来更晚一些。让他意外的是，今天他一打开门就看到你懒洋洋的躺在沙发上，厨房里冰锅冷灶。他的脸立马就拉下来了，一场大战爆发在即。\u003c/p>\u003cp>这时候，你要怎么表达，才能让他接受你今天不想做饭的事实，而且也不会影响到你们的感情，避免发生争吵？\u003c/p>\u003cp>请记得使用赵老师给出我们的句型。（考虑在表达感受后给出合理建议）\u003c/p>\u003cp>\u003cstrong>（学员演练分享）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>丈夫（开门，看见妻子在躺着玩手机，不高兴）：\u003c/strong>现在都几点了，怎么还在玩手机，晚上吃什么呢？\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>亲爱的，你回来啦？来，赶紧坐下来。今天下午我都拎包准备走了， 又听说第二天XX办要来检查，老板非让我把三个材料做完再走。等回来我都累死了，就在沙发上躺了一会儿玩玩手机……\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>我也加班了，你看我比你还迟呢！\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>是呀，亲爱的。不过你看我，翻手机也不是随便翻的，你上次看上的那款手表，正好在做活动，我都下单了。\u003c/p>\u003cp>\u003cstrong>丈夫（不好意思）：\u003c/strong>好吧，亲爱的，我错了。那你看，都这个点了，我们还没吃饭呢？\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>要不，我们让外卖小哥送点来？明天我去买点你爱吃的菜，好不好？\u003c/p>\u003cp>\u003cstrong>丈夫（犹豫）：\u003c/strong>可是吃外卖不太好吧？\u003c/p>\u003cp>\u003cstrong>妻子（撒娇）：\u003c/strong>亲爱的，你看我这么累~\u003c/p>\u003cp>\u003cstrong>丈夫：\u003c/strong>好吧，那我们下楼到外面吃吧？\u003c/p>\u003cp>\u003cstrong>妻子：\u003c/strong>好的好的！\u003c/p>\u003cp>\u003cstrong>Shooshoo:\u003c/strong>非常感谢两位小伙伴，表演非常入戏，让其他小伙伴忍不住给了热烈的掌声。这位“妻子”也非常优秀，首先她懂得安抚情绪，在对方发火前让他赶紧坐到身边。大家可能会注意到，如果一个人站在门口，而另一人坐在沙发上，两人之间的距离会非常不利于沟通。让他坐到身边后，距离拉近了，才能更好地陈述事实：“本来我下班都要走了,却发生了什么（事实），因此感到十分辛苦（感受）。更妙的是，她对自己的行为做出了解释：“我可不是随便翻手机哦……”最后又提出了解决问题的建议。这时候丈夫大部分的情绪以及被安抚了，于是最后他提出了解决方案：“那我们一起出去吃个饭吧？”于是一场冲突就被完美化解，甚至增添了一些美好回忆。\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>今天我的分享就到这里。由于亲密关系对我们来说非常重要，直接影响我们的幸福程度，所以越是面对亲密的人，你给出的信息就要越准确、越清晰，对方对自己的理解越直接越深刻，给我们的“爱的回应”就越丰富越有针对性。希望以上的方法可以帮助到大家处理日常生活中的问题是学会正确述情，记住先说事实，再表达感受，记住事实+感受这个黄金句型。同时期待大家下次来拆书帮，分享你们运用之后得到的益处。希望在拆书帮这个大家庭里。我们一起努力，成就更好的自己。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1503491893000,"updated_at":1503498308000,"ria":true},{"id":3287,"topic":"保持客观，杜绝“编故事”","learn_goal":"学习者能够学会应对突发事件，减少胡思乱想和负面情绪","remark":"拆书家Shooshoo2-2定级","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"Shooshoo","city":"合肥"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今晚的拆书家Shooshoo。经常参加拆书帮活动的朋友可能还会记得我这个 “美食爱好者”“手机拍照侠”和“0.7文青”。我热爱烘焙，对美食有着非同一般的热情，也爱用手机随时随地定格美好瞬间。虽然经常被朋友调侃为文艺青年，但我认为自己最多只修炼了七成功力，所以是个“0.7文青”。加入拆书帮这个大家庭，为了让自己变得更优秀，同时也为了结识优秀的你们。一个人可能走得更快，但一群人必定能走的更远。希望大家能够在自我提升之路上，相互鼓励，共同进步。首先，为了便于讨论交流，我们把在座各位分为2组","ratings_count":0,"texts":[{"id":6128,"quote":"\u003cp>\u003cstrong>&nbsp;【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>F：《爱的五种能力》是国内资深情感教练赵永久先生的著作，他提出的理念是，爱情需要学习，婚姻需要练习。人不是生而会爱，生而懂爱。爱也是一项需要学习和修炼的能力。但它不是一种单一的能力，而是多种能力的综合。包括了五种具体的能力，有了这五种能力，无论跟谁生活，都会容易幸福。\u003c/p>\u003cp>A：这本书是国内第一套系统的爱情理论，相对于国外很多著作，它更贴近国内婚恋状况的实际，细数国人情感认知误区，很容易引发共鸣。书中囊括了改善情感关系中最为本质且有效的技巧，包括如何觉察情绪，述情黄金句式，共情基本功训练等等。这些毫不花哨却效果斐然的技巧让无数的读者惊喜，他们不仅口口相传，甚至买了多本赠送亲朋好友。同时，也有很多情感心理大咖反复为这本书打call。\u003c/p>\u003cp>B：每个人都想把握幸福，在感情之路上打怪升级修成正果。那么当感情问题出现障碍，比如无法沟通，难以理解，拒绝接纳这样的困难出现时，《爱的五种能力》给出的指导和方法就恰巧是对症的良药，引导你通过感性的同频，实现关系的和谐。彼此同心，其利断金。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【原文片段】\u003cbr>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003ca href=\"http://life.self.com.cn/balance/news_12310681ba4e35bc-6.html\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>情绪是原始的，也是非理性的，它对人的保护是不够精细的，有时是会搞错的。\u003c/strong>想要管理好自己的情绪，就先要在众多起情绪的事情里边，把这样的情绪找出来，并学会管理它们，不要让它们总是出来打扰到你平静的心情，也不要让它们总是来影响你的生活。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 因\u003cstrong>假设\u003c/strong>而起情绪的事情在我们的生活中很常见。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 而实际上，很多时候，人们并不知道事实是什么，就凭自己的一个假设，坚定地认为事实就是这样的，情绪也就随之而起，如果后来证实事实并非你想的那样，\u003cstrong>你会发现你被你的情绪欺骗了，你只是自然而然做出了一个非理性的假设。\u003c/strong> \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 当然，人们分析事物时，总是先假设，然后再验证假设，进而得到事物的真相的，这里的问题是，人们很多时候并没有验证自己的假设，就认为自己的假设是事实，进而会起情绪，把事情搞砸。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 人们都会做假设，但往往一个人会做出什么样的假设，\u003cstrong>是和自己的心理特点有关系的\u003c/strong>。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 同样的事实，发生在不同人的生活中，人们做出的假设是不一样的，这是因为每个人的心理特点不同，对事物的感受和想法也不相同。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 一个人越是客观，就越是能够摆脱这样的假设和情绪，一个人越是主观，就可能会有更多这样的假设，因假设而引起的情绪也会越多，俗话说：“世间本无烦恼，庸人自扰之。”那些容易因假设而产生大量情绪的人，大概就是属于这里说的“庸人”吧。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 多数人的多数情绪，都是这样产生的，都是因为自己的假设引起的，心中所谓的敌人，只不过都是自己假设出来的“假想敌”而已，看到这里，也请你想一想，你最近一次生气，会不会就是这个原因呢？ \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; \u003cstrong>如果在爱情的关系中，一个人总是会把自己的假设当成事实，想想他会有多少的情绪要起，对整天起情绪的人而言，哪里还有什么幸福可言？\u003c/strong>况且男女之间的事情，假设起来是非常容易的。 生活中很多人际之间的误会，是因为这样的假设而引起的，这些情绪，真的是很原始和不理性，甚至多余。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 因此，我们必须学会管理这种因假设而起的情绪，让自己可以更加平静地去享受生活，\u003cstrong>而不是经常编个故事气自己。\u003c/strong> \u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>管理的方法：保持客观，不再编故事 \u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 对于因假设而起的情绪，我们知道那是自己编的故事，是假设，有时可能是事实，有时可能不是事实。我们要管理这类情绪，而不是不做假设。不做假设，人们可能就没有创新和推理的能力了，也就不能很好地分析事物了。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 管理这类情绪，有两个方法，可以根据具体发生的事情的类型和重要程度，结合使用。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 在觉察到自己有情绪，又意识到自己的情绪是因假设而起，你可以： \u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>一、无为 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>所谓无为，就是知道自己暂时了解不到真相，而真相又是可以随着时间的推移而呈现出来的，并且知不知道真相关系也不是特别大，或者不知道真相也不会引起太大的不良后果，这时，选择什么也不做。\u003c/strong> \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 简单说，就是知道自己针对眼前发生的事情，所产生的每个想法都是假设，不是事实，索性不再做任何假设，等待事情自然呈现真相。 \u003c/p>\u003cp>我在平时等人时，尤其是有人跟我约了咨询时，我通常会在等待时看会儿书，如果到了时间我等的人还没有到，我不会立即打电话问对方，而是采取“无为”的方式，静静地等待，一般过不了多长时间对方就到了。 \u003c/p>\u003cp>&nbsp;&nbsp; \u003cstrong>&nbsp;\u003c/strong>\u003cstrong>二、验证 \u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; \u003c/strong>\u003cstrong>当你有了一个假设，这个假设让你感觉事情可能很严重，你不一定要无为，你可以采取另一个方法，跟随情绪的提示，去验证你的假设，更早地让事实的真相呈现出来。\u003c/strong> \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 但切记，在你的假设没有得到验证之前，你要牢牢记住，这只是你的假设，这样，你的情绪就会好得多。 \u003c/p>\u003cp>这个方法，不只是可以管理你的一些情绪，还可以让你和他人之间少产生误会和误解，但也请你务必记得，这个方法，不是不让你做假设，而是在假设没有得到验证之前，你必须清醒地知道，这只是个假设，还不是事实，单单就这一点，就可以让你的很多没必要的情绪消失。\u003c/p>","explains":"\u003cp>\u003cstrong>【学习目标】跟随完成这个RIA现场学习后，学习者可掌握客观对待突发情况的心态方法，在未来生活中杜绝因非理性假设引起负面情绪和不良后果。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（预防异议1）\u003c/strong>今天这个片段想必很多妹子会有共鸣，而男性朋友可能会想：只有女人才有那么多情绪，那么喜欢胡思乱想呢！但其实，男人女人都会编故事，不仅仅是在我们的爱情中、婚姻中，在工作和社交活动中的方方面面都会不自觉地充当“故事大王”。\u003c/p>\u003cp>\u003cstrong>那么我们可以分析一下，为什么当时会这样想呢？\u003c/strong>\u003c/p>\u003cp>首先请大家看一下，我给大家展示的片段最前面的这张图：\u003c/p>\u003cp>大家第一眼觉得像什么？（有没有自愿回答的？）\u003c/p>\u003cp>是的，这就是大名鼎鼎的\u003cstrong>墨迹测试\u003c/strong>，实际上这只是一摊随意弄成的墨迹，不同的人却看到不同的东西。 \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 有的人看到蝴蝶、有的人看到蝙蝠、有的人看到人的内脏、有的人看到魔鬼，其实，那什么也不是，就是一团墨迹，本身没有任何意义，人们看到的都是自己的假设，由于人们的假设往往和自己的心理特点有关。 \u003c/p>\u003cp>因此，我们可以说，爱假设、编故事的本质，其实是放任自己被负面情绪操纵，让想象占据自己的内心，持续地恐惧、愤怒、不安。一编故事，就起情绪。一起情绪，势必要找出口灭火。长此以往，别人跟你的交往就会陷入“一波未平一波又起”的“情绪救灾”活动中。这得多累呀？故事编 久了，想要维持任何一段感情都基本是天方夜谭。\u003c/p>\u003cp>我以前也犯过类似的错误。比如，有一次给一个做品牌的朋友在微信发信息问一个工作相关的资料，之前关系一直还不错，我以为对方会秒回的，结果过了大半天都毫无动静。我心里就急呀，就想这姑娘怎么回事呀，看没看到你至少吱个声儿呗，直接无视算什么情况。做人哪能这么不厚道呢，有事找我帮忙的时候就很热情，有事找上身了就不吭声。就这么纠结生气了好一会儿，对方直接打电话过来了，说之前一直在开会，看到信息就赶紧给回电。你看，我不仅误会了对方的好心意，还白白生了半天气，有没有很不值？\u003c/p>\u003cp>好在，赵老师在这个片段中已经给大家最佳的心理指引和解决方法，那就是：把无为和验证结合起来。\u003c/p>\u003cp>\u003cstrong>无为\u003c/strong>就是让我们面对突发状况先冷静下来，隔绝负面情绪，不要冲动行事。\u003cstrong>（预防异议2）怎样做到无为？\u003c/strong>也许有的小伙伴认为情急之下什么都不做很难，其实简单来说我们可以从三个方面着手：\u003c/p>\u003cp>A.&nbsp; 转移注意力，做好自己手头的事情\u003c/p>\u003cp>B.&nbsp; 想象一下冲动造成误解的严重后果，悬崖勒马\u003c/p>\u003cp>C.&nbsp; 回忆平时与对方的感情积累，品德认知\u003c/p>\u003cp>\u003cstrong>验证\u003c/strong>则是求证事实和真相。如果你认为有必要了解真实情况，除了直接求证外，也可以选择从第三方间接了解。\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分步催化1\u003c/strong>\u003c/p>\u003cp>现在老师要按照之前的分组，让大家设想一下在你的工作和生活中，可能产生的让你情绪失控，胡思乱想，情不自禁开始编故事的场景：\u003c/p>\u003cp>比如你周末和朋友约好一起看一场大师级的音乐会，你好不容易抢到了票，盛装准备出席，临近一个小时你的朋友打电话告诉你他有事来不了，让你独自去或另找他人；\u003c/p>\u003cp>比如下周一的早上，你的上司突然把你叫到办公室，让你把手头完成一大半的项目交接给同事XXX，同时分配了你并不了解的工作给你……等等等等\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>【学习者案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学员：\u003c/strong>这个片段看完之后，发现里面很多情况自己都发生过。我是一个教师，在上课时经常会关注学生的反应和表情，其中一个学生经常会让我产生恼火的假设。因为他在上课时表情经常保持拈花微笑的感觉，我在讲课时看到他这样就会想：他在想什么呢？他的表情让我会觉得：他仿佛认为他自己比我的水平更高，他在俯视我，偶尔点点头，居高临下地赞许一下。他不一定是真的这么想，但是让我感觉很不好。现在我就选择上课的时候无视他，不看他，转而多关注别的学生，因为一看他就会影响我的心情，会让我假设自己是不是讲课不够好。这也是我近期会反复碰到的问题。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分步催化2\u003c/strong>\u003c/p>\u003cp>在刚才小伙伴们讨论的这些场景中，你会怎样运用我们今天学习的方法进行化解呢？\u003c/p>\u003cp>\u003cstrong>【学习者案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Shooshoo\u003c/strong>\u003cstrong>：\u003c/strong>根据这位小伙伴的分享，在他上课的时候，可能会因为某个学生的表情和反应产生不好的设想。那么根据我们今天所学习的方法，\u003cstrong>无为和验证\u003c/strong>，当时小伙伴已经采取了暂时冷置的方法去\u003cstrong>“无为”\u003c/strong>地应对一下（先不去胡思乱想，先把课讲好），那么近期你有没有打算再跟他沟通验证一下呢？\u003c/p>\u003cp>\u003cstrong>学员：\u003c/strong>是的，我一开始选择了无视，可能无形中完成了“无为”，但是还没有做到第二条“验证”。通过今天的学习后，我近期会带着我的假设去跟他沟通：这堂课你学习到了什么？你认为哪些地方对你是有启发的？又有哪些地方你觉得讲的不够好？结合具体情况，根据他实际的表达再进行判断和分析：也许他确实是自视甚高的学生，也有可能只是喜欢这样微笑，通过无为，结合验证把这个事情确认好解决好。\u003c/p>\u003cp>\u003cstrong>Shooshoo:\u003c/strong>相信通过无为和验证这两种方法，这个学生将来在你课堂上的表情和表现不在会对你的心理产生太多影响。\u003c/p>\u003cp>【总结】\u003cbr>今天我的分享就到这里。希望以上的方法可以帮助到大家在与人相处时更好的控制自己的情绪，减少胡思乱想，提高感情浓度，同时期待大家下次来拆书帮，分享你们运用之后得到的益处。希望在拆书帮这个大家庭里。我们一起努力，成就更好的自己。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1500909096000,"updated_at":1513339734000,"ria":true},{"id":2057,"topic":"叶菲TF2-4级别补定级","learn_goal":"完成TF2-4级别定级","remark":"赵永久先生总结的一生爱的能力培养的五项能力","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"新页","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"开场： 大家好！我叫叶斐，叶是叶子的叶，斐是成绩斐然的斐，因为我对每个阶段的自己都有不同的目标和要求，所以也给自己取了个小名叫新页，希望每天都是新的一页，每天都有新的改变。今天我要带拆的书籍是《爱的五种能力》。","ratings_count":0,"texts":[{"id":4691,"quote":"\u003cp>【图书介绍】\u003c/p>\u003cp>\u003cstrong>F 特征（核心是“书”，用于满足好奇心）：\u003c/strong>\u003c/p>\u003cp>《爱的五种能力》是由知名情感教练、婚姻家庭咨询师赵永久所著，他提出：爱一个人需要具备爱的能力，它包含情绪管理、述情、共情、允许和影响这五种具体能力。而这五种能力恰恰也是情商的具体体现。该书结合了真实的案例来详述这五种能力，帮助你重新认识爱，修复爱，拥有爱，传播爱。\u003c/p>\u003cp>\u003cstrong>A 优势（重点是“比较”，用于建立安全感）：\u003c/strong>\u003c/p>\u003cp>这本书一经推出便荣获豆瓣9.1分高分的推荐，口碑极好。著名心理学家杨凤池、麻辣情医吴迪、百合网CEO田范江都倾情推荐，甚至有许多读者买了几本几十本用来送人，他们希望更多人看到这本书，希望更多的人可以更幸福。\u003c/p>\u003cp>\u003cstrong>B 利益（强调的是“学习者”的利益，用于引发兴趣）\u003c/strong>\u003c/p>\u003cp>如果此刻你一直单身，迟迟找不到合适的人；或者全心全意对对方好，人家却不领情；在婚前信心百倍，婚后不尽人意；婆媳关系一直处得不理想，很苦恼；正考虑要不要离婚；或婚姻关系中已经出现了第三者等等，我建议阅读此书，因为这正是你所需要的。\u003c/p>\u003cp>\u003cstrong>第一个RIA\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>【阅读原文】\u003c/p>\u003cp>情绪是原始的，也是非理性的，因此，它有时是不够精细的，有时也是会搞错的，想要管理好自己的情绪，就先要学会在众多起情绪的事情里边，先把这样的情绪找出来，并学会管理它们，不要让它们总是出来打扰到你平静的心情，也不要让它们总是来影响到你的生活。\u003c/p>\u003cp>这些的情绪是这样产生的：\u003c/p>\u003cp>一个周末的下午，你约一个新认识的异性朋友两点钟见面，你提议到一个你常去的咖啡馆见面，定好地点后，你把地址通过短信发到他（她）手机上了。\u003c/p>\u003cp>你是一个守时的人，在一点五十分之前就到了，足足提前了十分钟。\u003c/p>\u003cp>看到咖啡馆里没有你约的朋友，你找了个靠窗的位置坐了下来，随后，你顺手拿起了一本杂志漫不经心的翻起来。\u003c/p>\u003cp>时间很快到了你们约定的时间，下午两点钟，他（她）还没有到，你心里有了一个对他（她）的看法：原来这是一个不太守时的人，居然迟到了。\u003c/p>\u003cp>时间已经过去了五分钟了，他（她）还没有到，你心想，他（她）居然迟到了五分钟，看来他（她）不怎么把你放在眼里，你有一点点小生气了。\u003c/p>\u003cp>十分后，他（她）还没有到，你压住心中的一些气愤，拿起手机，准备给他（她）打个电话，拨完号码，你深呼吸了一下，并把手机放在耳边听着拨号音。\u003c/p>\u003cp>“对不起，您拨打的号码已经关机！”手机里传来了这样的声音，你更加生气了，你觉得这个人简直是不把你放在眼里。\u003c/p>\u003cp>二十分钟后，他（她）还是没有到，电话依然是打不通，你已经很生气了，心想做人怎么可以这样呢？既然是遇到了事情需要晚来，也要打个电话说一声啊！\u003c/p>\u003cp>你越想越生气，觉得这样的人简直不可交，于是，你拿起手机，放下杂志，走出了咖啡馆。\u003c/p>\u003cp>你生气了，这是潜意识在对你进行提示，那么，你的潜意识在提示你什么呢？\u003c/p>\u003cp>很明显，潜意识在提示你，有人居然不尊重你，你需要给这样的人一点教训，或远离这样的人。\u003c/p>\u003cp>但是，潜意识的工作方法是纯粹感性的，是很原始的，潜意识忽略了一个重要问题，这个人不尊重你只是你的一个假设，不一定是事实，事实有很多种可能，到目前为止，你还不知道什么是事实呢？\u003c/p>\u003cp>可你已经很生气了，这就是潜意识原始和非理性的地方。\u003c/p>\u003cp>这个人不尊重你，只是你编的一个故事而已，只不过你很相信你的编的这个故事，所以，你才会很生气，甚至决定马上离开这个地方，再也不想见到这个人。\u003c/p>","explains":"\u003cp>\u003cstrong>学习目标：在跟随我完成本次RIA现场学习后，学习者能够在情绪出现失衡的情况下不在潜意识中对事情进行错误的假设，而是放下情绪询问真正的事实是什么。\u003c/strong>\u003c/p>\u003cp>小伙伴认真阅读了第一个拆页之后，是不是有种似曾相识的感觉，当然此刻也许有的小伙伴心里会有些不服气，因为他曾经验证过他所谓的假设就是事实，因此在下一次出现类似事情的时候，不自觉地就会按照之前的假设去想象，\u003cstrong>（预防可能的异议）\u003c/strong>所以在我们的现实生活中，当遇见令自己当下不开心的事情时，我们一般潜意识中会浮现的多数是不好的假设，会把责任强加在对方身上，把错误一股脑都指向对方等等。结果呢，自然引发了很多不必要的误会和矛盾，可能自己一整天都被坏的情绪所笼罩，甚至因而失去了一个很重要的朋友，如果事情是发生在夫妻情侣之间还可能引发争吵，严重的都可能闹离婚闹分手。\u003cstrong>（强调不那么做的坏处）\u003c/strong>这让我想起当年淘宝刚盛行的时候，我一个朋友的老公也赶了潮流成天在淘宝上买这买那不亦乐乎。有一天我朋友很郁闷的找我聊天，说她感觉他老公外面有人了。我很纳闷，毕竟他老公是个很典型的宅家技术男。她义正言辞的说，我发现他精神出轨了，经常和这个亲啊，那个亲啊，时不时还发个么么哒的表情，她觉得很恶心。我说你有找你老公询问吗？她说没有，她怕自己难以接受事实。但她脑海里已经有了想离婚的念头了。\u003cstrong>（举实例）\u003c/strong>事情进展到这，我们可以看到主人公在不知道事实的真相时因为潜意识的假设已经有了一个决定，那就是离婚，可到底是不是误解，她因为过多的沉浸于自己的假设中已经没有强烈的意愿去了解事实的原貌了。而一旦做了决定就很可能出现不可挽回的结果。如果运用我们拆页的建议，先厘清此刻的潜意识是假设而非事实，那么就可以相对冷静的去寻找事实的真相究竟是什么？\u003cstrong>（细化行动步骤）\u003c/strong>我当时对她说：“如果你只是偶然瞥见聊天中有这样的表情或昵称那也许是现在淘宝卖家为了和买家拉近关系而常用的聊天手法罢了，未必就是你假设中出现的精神出轨，尽管我不知道事实是什么，但我建议你和你老公心平气和的沟通一次，也听听他是如何回答再做判断也不迟？”过了两天，她开心的给我打了一通电话，说是她误解了，他老公把聊天记录都给她看了，正如我所说的就是淘宝常见的聊天手法罢了，只不过她不爱上网也不懂现在网络玩的这些东西，因而出现错误的假设了。所以如果我们生活当中只要遇到令自己不开心的事就一股脑的把错误的假设当成事实来看，会引发很多不必要的灾难的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（显像提问法）\u003c/strong>现在请小伙伴认真听这些词汇，哪一个让你感觉熟悉——误解、委屈、难过、愤怒、烦躁、懊恼……哪个词是你熟悉的，是你近期经历过的？写下这个词。\u003c/p>\u003cp>然后，你最近一次有感受到这种情绪，是什么时候，是什么事情？思考两分钟，我会找一到两位小伙伴进行分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>分享一个愤怒的感受。过年回来，孩子感冒了出现上吐下泻的现象，然后我老爸就开始发飙。其实这两年一直是这样的，只要一出现事情，他就会接二连三的发飙，那眼睛瞪的圆溜溜的，平时我都忍着他，但那天我就情绪控制不住了。我就跟我爸说：“要么你就和妈在妹妹家过，我们回自己家过算了，没有和你在一起的时候孩子也好好的，我心情也很开心……“反正是闹掰了。后来他也不干了，平时还会拖拖地打扫下卫生，这下啥都不做了，也就是早上敲个房门示意他要出去了，剩下的给孩子做饭啥都没了。其实老人家68岁了，但依然是这样，现在是我生命当中最大的困扰。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>针对你刚才说的情境就是你眼里的爸爸，这是你潜意识的假设还是事实呢？你是否能够厘清呢？\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>我认为是事实。已经长达两年都是这样，就是对我们的行为举止，任何一切都不满意，不停的抱怨。其实在吃年夜饭的时候，我曾尝试和他沟通，因为那个晚上他又抱怨了。我运用《非暴力沟通》的方法询问他：“老爸，你的需求是什么呢？”他马上说：“我们要你勤快一点，早上早起一点。”我就说：“行，那2017年我尽可能多做一些家务，但我周末有时候睡得太迟隔天会睡会懒觉没有办法那么早起，毕竟你9点半就睡了”。然后我妈就在那说：“别吵，别吵，就这样吧。”我说：“我们还是要沟通的，要不问题不解决会影响到家庭氛围的，你也不高兴呀。”我妈就说：“那你们继续。”后来我发现我们家的沟通状态是这样，只要一有事就会起情绪。但我现在通过书籍的不断阅读，我尽可能的去管理我的情绪，就是把情绪的反应时间拉长，如果确实要发火再发火，不发火就压下去。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>在A运用了《非暴力沟通》中，其实我发现你是有找到了事实的真相就是爸爸希望你勤快点，希望你早起一些。而你之前说你眼里爸爸的那些是事实，似乎和你所找到的不符合哦，那其实是你的潜意识的假设。因为你在两年的时光中都认为爸爸容易唠叨发脾气说个不停，所以只要他一开口你内心就有了抵抗的情绪，你难以去专注他所表述的内容背后真正的意图。如果你在和你爸爸的对话中真正能够静下心来把问题继续深挖，把自己潜意识中对爸爸的形象的错误猜想放下，探求下他的需求我如何满足——比方勤快一些，那我就多做家务，可以限定到具体的家务内容看是洗地板还是洗碗呢？我早起一点，比方原本睡到几点到了周末我就提前起床一些，有商有量，各退一步，直至协商一致。然后你再提出请求说：“爸爸，如果我能做到这些，你以后是否少说一些，这样对你身体也不好呀等等之类的话呢？”你看，这样是否能够起到一个很好的帮助作用呢？\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>路漫漫啊，我试看看吧。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+】反思加工经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>再遇到这样的情况，你可以怎样应用刚才学的方法去回应？\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>我试着按照你所说的把潜意识的假设放下，放下对爸爸一直以来的成见，去再次平和的沟通，深挖下有没有可能性，就像你所说的，是否可以限定家务内容等等，双方能否达成协商一致。\u003c/p>\u003cp>\u003cstrong>【A2 】催化学习者应用\u003c/strong>\u003c/p>\u003cp>好的接下来我们换个场景，设想一下，你周一到了办公室，倒了一杯热茶，准备开始一天的工作，想起今天的拆页，你要停下来问自己，哪些事情可以有不同的做法，哪些事情可以因此有不同的结果，甚至是非常美妙的结局？请在小组内分享下你的应用。\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>在公司里我发现领导层内部有很大矛盾，以至于我们底下的在做事显得无用功，一会否定这个事，一会又要做那个事。2017年我变聪明了，按照自己的想法来，估计他们之间还是存在摩擦我就没有必要跟着他们团团转了。按照之前年会大家的述职报告，我认为有些项目可以强推去做了，这是我认为的时机，要不会丧失公司现有的机遇。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>回到拆页的知识点，是要询问哪些是你的潜意识假设，你是否学会放下去探求事实的真相。而现在你所表述的是你今天要强推的项目未必是在领导的计划之中？\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>我是觉得有些项目是没有必要做的，领导要做是为了显示他的权威罢了。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>那这里是否有涉及到是你的错误假设而非真实的事实呢？毕竟你作为当事人，是否也有当局者迷的可能性呢？你认为该项目领导是为了显示权威而实际没有必要做，事实是这样么？这个是我单方面的再次向你询问，希望你私下再去思考，只有通过这样来回的发问才可以促进我们对真相的寻求，让事实更好的呈现也避免我们陷入假设的情绪中。当然你对于2017年认为本来要围着领导团团转做项目，现在跳开这些错误的假设，真正用你观察后浮现的事实考量得出——我可以真正做对公司有进展的项目，去推进，正好处于机遇时期而不要把公司陷入权利斗争中白白牺牲。如果这是对的事实，那么相信这个改变会帮到处于困境的公司和团队，提振大家的士气，也是一个美好的开始。因为时间关系，我们直接进入第二个RIA的学习，若有小伙伴想继续探讨，我们等活动结束后再进行哦。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}},{"id":4692,"quote":"\u003cp>\u003cstrong>第二个RIA\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>【阅读原文】\u003c/p>\u003cp>人们如何管理这种因自己标准而起的情绪呢？\u003c/p>\u003cp>管理的具体方法：\u003c/p>\u003cp>一、觉察：意识到自己有情绪；\u003c/p>\u003cp>二、区分：这一次的情绪主要是第一时间起的本能的情绪？还是有对错标准参与才起的理性情绪？\u003c/p>\u003cp>三、当确定这是因自己对和错标准而起的情绪后，在内心告诉自己：放下对和错；\u003c/p>\u003cp>四、然后用心去感受对方的心，感受一下对方做这个事情时内在的感受是什么？\u003c/p>\u003cp>至此，如果意识到自己有情绪时在内心运行这个过程，情绪往往自动就消失了，因为放下了理性，用心去感受对方，往往更容易理解对方，让自己成为一个内心平和、善解人意的人。\u003c/p>\u003cp>就情感关系而言，爱人想做一些自己愉快的事情时，如果没有伤害到其他人，尽量给他宽松的空间，让他去做，因为这样做了他会开心快乐。\u003c/p>\u003cp>爱人的开心快乐，有时比自己的正确可能还要重要，因为人们找爱人，不是为了正确的，而是为了开心快乐、幸福。\u003c/p>\u003cp>比如：一个已婚女士回到家就看到老公在客厅看电视，他不是端端正正地坐在沙发上看电视，而是整个人半躺在沙发上，双脚放在茶几上的。\u003c/p>\u003cp>看到这个场景，如果讲正确，他可能是不正确的，因为茶几是用来放食物和茶水的，不是用来放脚的。再说他这样坐没坐相，多不好看啊！\u003c/p>\u003cp>一旦开始觉得他是不对的，女人的情绪就开始起来了。她会感觉到气愤，控制欲开始起作用了。而她也被他控制了，因为他只要把脚放到茶几上，就可以让她起情绪，她完全没有了一天的好心情，她的情绪开关在他的脚上。\u003c/p>\u003cp>她可能并没有意识到家是讲爱的地方，家是放松的地方，人们在单位要好好坐着，在社交场合要注意形象，如果在家里还要像外面一样循规蹈矩，家又和外面有什么区别呢？\u003c/p>\u003cp>在家里，爱是排在前面的，正确是排在后面的，那些人们发明出来用来约束人的礼节，有时要靠边儿站。愉快有时比正确还要重要，真的爱他，就允许他把脚放在茶几上看电视，虽然要再擦茶几，但他愉快了，也是值得的。\u003c/p>\u003cp>一个人要想管理好自己的理性情绪，就要在意识到又想拿自己的标准要求别人时、又想用自己的正确来打压别人的愉快时，如果对方没有伤害人的话，放下自己的对错标准，多用心感受对方的感受，允许对方开心快乐。这样，彼此都自由了，幸福快乐也就更多了\u003c/p>\u003cp>。\u003cbr>\u003c/p>","explains":"\u003cp>\u003cstrong>学习目标：在跟随我完成本次RIA现场学习后，学习者能够在因自己标准而起的情绪情况下，通过掌握具体的管理方法，让自己放下对错标准，允许对方开心快乐也让自己开心快乐。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>看到小伙伴都认真的把拆页阅读完毕了，可能有的人觉得这么管理情绪不能第一时间去表达自我，有些麻烦更有些矫情了，但如果我们当下痛快了结果却不能达到双赢的局面，你认为这还是你想要的吗？\u003cstrong>（预防可能的异议）\u003c/strong>所以，在现实生活中如果出现因自己的对和错标准而起的情绪后，往往会带来不太愉快的结果，会由此引发批评甚至责骂的做法，一旦上纲上线就会伤害彼此的感情。\u003cstrong>（强调不那么做的坏处）\u003c/strong>根据拆页那位已婚女士看到老公双脚放在茶几看电视的案例，我突然想起我之前和老公两人，一人负责做饭一人负责洗碗这事情上，我也是因对和错的标准容易起情绪，我老公习惯于吃饱饭休息一个钟头后再去收拾碗筷，而我当下认为吃饱后收拾碗筷是再自然再正确不过的事，为啥要休息一小时再行动，万一来客人呢，结果，可想而知我们为此拌了几次嘴。\u003cstrong>（举实例）\u003c/strong>若按照拆页管理情绪的方法：1、觉察。我在当下要意识到自己已经有了情绪。2、区分。我有情绪的反应主要在当下因有对与错的标准才起的理性情绪。3、当我意识到自己认为吃饱饭后马上收拾碗筷为对，不马上收拾碗筷为错的标准，那么即刻在内心告诉自己，放下对和错。4、试着用心去感受对方的心——他只是希望用自己比较舒服的方式去做家务，不希望在这个讲爱讲放松的家里有太多的条框限制，何况这不是必要的。\u003cstrong>（细化行动步骤）\u003c/strong>通过这样的情绪梳理，当下会发现其实放下对错标准，允许对方开心快乐，原来是多么美妙的事，因为彼此会感觉到心灵的自由，幸福快乐也会愈来愈多。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>接下来我们现在马上做一个演练。请大家认真听一下要演练的场景：这是发生在家长和三岁孩子之间的对话，有一天你看到孩子偷偷拿了其他小朋友的玩具回家，你会怎么教育他？现在，请每两人一组，进行演练。请大家运用到这个情绪管理方法并延伸出它的积极意义来完成这段对话。演练时间为3分钟，现在开始。3分钟后，我们会请一到两组现场对话，看看他们是怎么表达的。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>小C，你这个东西是从哪里来的呀？\u003c/p>\u003cp>\u003cstrong>C：\u003c/strong>隔壁同桌的。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>你为什么想要把它拿回来呢？\u003c/p>\u003cp>\u003cstrong>C：\u003c/strong>很好玩呀。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>你很喜欢它吗？\u003c/p>\u003cp>\u003cstrong>C：\u003c/strong>是呀。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>你有没有跟你的同桌说一下呢？\u003c/p>\u003cp>\u003cstrong>C：\u003c/strong>没有，他不在。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>那你是否有想过，他回来看到心爱的玩具不见了，会很着急呀？\u003c/p>\u003cp>\u003cstrong>C：\u003c/strong>会着急呀。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>同样的，如果你心爱的玩具不见了，你是不是也会着急。\u003c/p>\u003cp>\u003cstrong>C：\u003c/strong>会呀。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>那是不是我们下次应该和他打声招呼，等他同意了，再拿回家呀。\u003c/p>\u003cp>\u003cstrong>C：\u003c/strong>那玩具也是我的呀。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>怎么说是你的呀？\u003c/p>\u003cp>\u003cstrong>C：\u003c/strong>反正我喜欢的都是我的呀。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>那妈妈是谁的呀？\u003c/p>\u003cp>\u003cstrong>C：\u003c/strong>我的呀。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>那你同桌如果也认为妈妈是他的，同样道理，是不是以后你的玩具也是他的咯。\u003c/p>\u003cp>\u003cstrong>C：\u003c/strong>那我不管，反正现在这玩具就是我的了。\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>额，让妈妈想一下…\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>好的，我们先暂停一下。其实刚才你们在进行对话时，已经有小伙伴在默默鼓掌了，觉得这个场景再现得很真实。现在我想询问一下B，通过刚才的场景扮演，你作为家长，是如何处理对和错作为标准的这个情绪呢？\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>我之前看过一则文章，它说在小孩子的观念当中是不存在“偷”的，所以不能站在家长的角度去强加这个观念给他。所以在当下我比较能够迅速的放下对和错这个标准的情绪。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>非常好，那你用家长这个视角，是否能体会到孩子在接受你这样的教育方式时，他的个人体验是什么？或是他长大以后会有什么不同？\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>作为小孩子，他可能只是喜欢这个东西，想把它拿回家多玩一会罢了，并非是我们所认为的“偷”。所以运用刚才我那样的引导方式，应该小孩子是比较能接受的。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>谢谢B。在现实生活中，多数家长在没有耐心的情况下，较容易站在一个制高点去批评孩子指责孩子，但如果在这样的现实情况中，妈妈直接说你这样做是不对，你要那样做才是对的。几次下来，小孩子会形成寻找对和错的思考方式，长大以后会是个好人但未必拥有爱心。但假使妈妈在对话中是说：“如果你同桌在你不知道的情况下把你心爱的玩具拿走了，你会不会伤心？”既然你会伤心，那你现在把同桌的玩具拿走，他是不是也会伤心呢？”孩子很可能就能意识到要把玩具还回去，这样会帮助他学会爱自己也学会了爱别人。这样的孩子长大以后就很难成为坏人，因为坏人和好人的标准其实就是会不会伤害人，也就是心中有没有爱。所以通过这样的演练我们能从理解他人感受他人，延伸到我们管理好情绪而做的沟通和表达其实会给对方带来极其积极和深远的意义，因此不可小瞧情绪的管理哦。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>刚才我们涉及了夫妻、亲子之间的关系，你觉得这套情绪管理方法还适合涉及你工作或生活中的哪个关系的情境，同事之间、上下级之间、亲戚之间、朋友之间？\u003c/p>\u003cp>（请大家思考并想出具体情境后）请加工一个具体的例子，可以是发生过的也可以是自己目前正困扰的，说明自己将如何运用这套情绪管理方法？\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>上周五我回老家的时候，发现妈妈和一个亲戚在通电话，内容大概是发现两个枕头不知道哪里去了。妈妈就随意猜测说可能是姑妈拿走了或者是哪个同宗族的人拿走了。然后这个通电话的亲戚又把我妈妈说的话传出去了。结果就出现一些没必要的尴尬了。后来我发现，妈妈开始在那自责，就说自己不该乱说话，后悔了。当时如果我按照这个管理情绪的方法，我应该当下先询问妈妈的感受？理解她内心，平复其情绪。而那时我是在纠结第二点就是区分那个部分，用对和错的标准在看待我妈。今天这一拆给我的提升很大。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>你当时是没有放下对和错的标准。\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>是呀，如果当时我放下，直接去问妈妈你是不是很难过呀？\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>感受妈妈当下的心情。\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>毕竟人不可能犯错。我应该当时和我妈妈做个类似的对话的，妈妈你是不是很难过？妈妈，我们可以通过别的渠道和对方去沟通一下，不会有什么尴尬的，毕竟是多年的亲戚朋友。我突然发现这个例子启发我，原来我一直不太会关心人。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>没有去感受到对方的心理。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>D：\u003c/strong>我理解的这种接纳，就像你刚才说的人总会犯错，我是否能够接纳妈妈会犯错误这个事情。像这样的接纳是我近期很大的体悟，我有时候上课会发现有的学员不喜欢，当下我可能会有情绪。人总喜欢接纳好的，自己喜欢的，而拆页知识点所表达的接纳是不是要让我们学会去接纳我们不认为好的，不喜欢的。这是很重要的功课啊。\u003c/p>\u003cp>\u003cstrong>A: \u003c/strong>我再分享个例子，前天我师父来厦门，师姐和我招待了他。昨天我师姐电话里和我说：“师父这次来厦门要买车就是来找我们要钱，他也不管我们师兄妹几个现在是什么个情况，就张口找我们要钱……”就这样不停的抱怨了半个小时。我现在回过头来看那段通话，我觉得我做得好的地方就是放下对和错，就是没有评判我师姐和我这通电话里抱怨的内容。但我还缺的就是当下没有和我师姐去表达一个感受就是我理解她的心情。这一拆的知识点能让我的内心更接近对方的心灵，更柔软一些。\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>情感部分链接得更流畅一些。\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>原本我是把情绪的反应时间拉长，现在能在放缓的过程中尽可能的去接纳和感知对方的情绪。好比对爸爸，我其实可以试着去感受下爸爸的焦虑，感受下爸爸的情绪。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：\u003c/strong>是的，我太认同了，你可以链接到第一个拆页的案例并试着去体会和感受，又是一层递进。其实我们内心很多时候所设立的对与错是自己认为的，未必放之四海而皆准的。所以这个过程中尽可能用最柔软的部分就是用心感受去建立彼此之间的情感桥梁。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>五、结语（1分钟）\u003c/strong>\u003c/p>\u003cp>好的，第二个知识点的带拆就到这，我们现在回顾一下两个片段的知识点：第一个片段是通过错误的假设还是事实让我们明白哪个方式会带来好的结果，第二个片段是通过掌握具体的管理方法，让自己放下对错标准，允许对方开心快乐也让自己开心快乐来更好的管理和解决情绪问题，达到双赢的效果。希望大家在今后的工作、学习以及家庭生活中能始终管理好自己的情绪，避免一些不必要的误会和麻烦，让自己也让周围亲近的人愈来愈感觉与你相处非常幸福、快乐。回去之后可以认真阅读一下《爱的五种能力》这本书，里面有许多案例可以更高效的帮助你学会情绪管理的方法。今天的拆书活动就到此结束，谢谢各位！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1488279214000,"updated_at":1488279214000,"ria":true},{"id":1964,"topic":"爱的五种能力之觉察情绪","learn_goal":"提高觉察情绪的能力，学会引导当事人分享他的感受和发生的事情","remark":"","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"马辉","city":"珠海"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"学习目标：大家好，我是马辉，今天很高兴可以和大家一起做TF3-2的拆书活动，希望通过今天的学习后，大家可以在日常生活中意识到自己或身边的人在什么时候，什么情况下起了情绪，并可以使用相对精准的情绪词语来描述自己和身边的人的情绪。学会引导当事人分享他内在的感受和外在发生的事情。从而提高我们情绪觉察的能力。\r\n图书介绍：场景：首先给大家介绍一下今天要拆的这本书《爱的五种能力》，大家在日常生活中有没有看到这样一种情况，有一些女孩子常常不把自己喜欢什么，不喜欢什么告诉自己男朋友或老公，反而让对方去猜，女生觉得：如果你爱我，你就应该知道.........，这就是缺乏这本书里提到的述情的能力。\r\n提问：大家以前遇到或者看到身边的人遇到这种事，一般是怎么处理的呢？会不会有的人说吵吵更健康，也有的人说什么都要我说出来他才知道，说明他不懂我，我们不合适，分手吧。其实这就是由于缺乏了述情能力导致的。\r\n影响：有些夫妻，虽然结婚了，但彼此并不真正懂得对方，也不主动打开自己的心和对方述情，这个时候如果出现一个他认为懂他的人，他会不会精神出轨，甚至离婚呢？\r\n解决：这本《爱的五种能力》的作者就在书里提","ratings_count":0,"texts":[{"id":4641,"quote":"\u003cp>《爱的五种能力》情绪的觉察\u003c/p>\u003cp>觉察就是意识到自己起了情绪。就像看到了情绪一样，仿佛人跳出了自己的身体，从旁观者的角度看自己的内心。一个人带着觉察的意识时，才能看到自己的情绪。当一个人没有意识到情绪的存在时，情绪是人的主宰者，情绪会驱使人做一些不理智的事情，这些事情可能会伤害他人，而人在事情发生后才意识到自己做了什么。觉察情绪的提示作用，就可以摆脱情绪对自己的控制，重新做自己的主人。\u003c/p>\u003cp>觉察别人的情绪，理解他人，对他人的感受感同身受，并照顾到对方的心情，让对方知道你很理解他的感受。在情感关系里，如果你不能准确说出爱人内心的感觉，他会感觉你不理解他，进而会上升到你不爱他的层面。如果你能准确说出他的感受，他就会感觉自己的心和你的心很近。\u003c/p>\u003cp>练习觉察情绪的方法是非常重要的一个能力，当你或身边的人的情绪处于非平静状态时，就可以用相对精准的情绪词语去问自己或对方，是不是有些生气？是不是有些伤心？是不是有些委屈？等等。用的描述情绪的词语越准确，效果越好。这时表示你关注和接纳他的情绪。\u003c/p>\u003cp>然后，引导当事人分享他内在的感受和外在发生的事情。一个人有负面感受，一定是有原因的，哪怕这个原因不是当下刚刚发生的事情，而是他想起了一些以往的事情。这一步需要注意，聆听的时候，一定要把事情从头到尾完全听完，要认认真真的停，中间尽量不要打断，让对方感觉到完全被关注和接纳。\u003c/p>","explains":"\u003cp>I 拆书家讲解：\u003c/p>\u003cp>大家看完拆页了吗，请问***，你画出的关键词有哪几个呢？拆页里的提高觉察情绪的能力的方法有2个步骤，***你可以分享一下你觉得这2个步骤是怎么样的吗？....情绪觉察对自己，对身边的人都是很重要的，同意吗？\u003c/p>\u003cp>那**，在你的日常生活中，有没有遇到那种特别可以觉察或者特别不能觉察别人情绪的事情或人吗，可以举一个具体的例子谈一下当时是什么情况，你当时的感受是怎么样的吗？\u003c/p>\u003cp>那种容易理解和接纳别人情绪的人，更受大家的欢迎，大家同意吗？而那些能够理解自己，能够识别自己的情绪，不逃避情绪的人，也会活的更通透，大家同意吗？\u003c/p>\u003cp>以前我有时候心情不好的时候，就爱给一个业余时间学心理学的好朋友打电话，因为她是完全接纳我的情绪的，每次对她倾诉倾诉，倾诉完，觉得舒服很多。\u003c/p>\u003cp>请问***， 你画出的关键词又有哪些呢？你有没有出现过，或者看到过别人出现过这样一种情况，就是被负面情绪控制，在情绪的引导下，说过伤害身边的人的话，或者做过伤害身边的人的事儿呢？当时是怎么回事呢？ &nbsp;所以缺乏对情绪的觉察能力，对自己，对身边的人都可能会造成伤害，大家同意吗？\u003c/p>\u003cp>I解释自测题：\u003c/p>\u003cp>之所以让大家做这个自测题，是通过这个题目，让大家看到自己对自己的情绪觉察能力，自己对身边的其他人的情绪觉察能力的高低。这8个题目总分40分，分数越高，表示你对自己和别人的情绪觉察能力越高。***你的分数是多少呢？**你的分数呢？由此可见，不同的人，对情绪的觉察能力是不同的。大家有没有听到过这样一句话：我当时不该那么做，或者我不该说那么伤人的话的，我并不想那样，可是当时我控制不了自己，当时我脑子里一片空白......？这就是没有觉察到自己的情绪，被自己的情绪控制了。如果你提高自己的情绪觉察能力，会不会能更好的认识自己，更好的和周围的人交流，做一个善解人意的人呢？\u003c/p>\u003cp>好，那接下来请大家用1-2分钟时间阅读一下手里的拆页内容，在阅读过程中，请画出您认为的几个关键词。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>今天我选取的片段是《情绪的觉察》。那我怎么知道自己是否能觉察自己的情绪，是否能觉察对方的情绪呢?我们就做一个自测题，大家可以看到手上拿到的测试题，提示大家，这个测试题有8个题，请大家按照1到5分的标准来打分。1分表示完全不符合，5分就表示非常符合我的实际情况。所以他是2个极端的分数。如果你觉得自己好像有点儿像，但又没5分那么强烈，你就可以在中间分数取值。请大家仔细阅读表格里面的每句话，根据自己的实际情况来给自己打分。请问我表述清楚了吗？好，现在请大家做一下这个自测题，时间1分钟。\u003c/p>\u003cp>自测量表：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>TF3-2今天我选取的片段是《情绪的觉察》。那我怎么知道自己是否能觉察自己的情绪，是否能觉察对方的情绪呢?我们来做一个自测题，通过这几个题来评判一下。大家可以看到手上拿到的测试题，提示大家，这个测试题有8个题，请大家按照1到5分的标准来打分。1分表示完全不符合，5分就表示非常符合。所以他是2个极端的分数。如果你觉得自己好像有点儿像，但又没5分那么强烈，你就可以在中间分数取值。请大家仔细阅读表格里面的每句话，根据自己的实际情况来给自己打分，分数越高，表示您对情绪的觉察能力越好。请问我表述清楚了吗？\u003c/td>\u003c/tr>\u003ctr>\u003ctd>题目\u003c/td>\u003ctd>1\u003c/td>\u003ctd>2\u003c/td>\u003ctd>3\u003c/td>\u003ctd>4\u003c/td>\u003ctd>5\u003c/td>\u003c/tr>\u003ctr>\u003ctd>1、我开心或郁闷或委屈的时候，我会直接告诉我的那个ta\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>2、我一直可以很好的管理我的情绪，不被坏情绪趋势影响，去转嫁到家人身上\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>3、当我遇到让我生气，愤怒的事情时，我第一反应是先觉察到一下自己的情绪，而不是先倾向于分析事情的原因，利弊得失，\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>4、当我伤心难过时，我会选择直接面对和感受这个情绪，而不是选择逃避情绪和做一些其他事分散注意力\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>5、当我亲近的人感到高兴，幸福的时候，我可以马上感受到ta的高兴，兴奋\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>6、当我看到别人伤心难过的时候，我也可以感受到ta&nbsp;的难过并愿意倾听他诉说\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>7、当我看到伴侣为了工作的琐事对我倾诉时，我可以很快识别引导他看到自己的情绪，而不是认为ta首先应该自我反省是不是自己的问题\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>8、当我对家人或朋友发脾气时，我可以站在ta的立场去感受他此刻的心情\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>总分\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>I 解释自测题：\u003c/p>\u003cp>之所以让大家做这个自测题，是通过这个题目，让大家看到自己对自己的情绪觉察能力，自己对身边的其他人的情绪觉察能力的高低。这8个题目总分40分，分数越高，表示你对自己和别人的情绪觉察能力越高。***你的分数是多少呢？**你的分数呢？由此可见，不同的人，对情绪的觉察能力是不同的。大家有没有听到过这样一句话：我当时不该那么做，或者我不该说那么伤人的话的，我并不想那样，可是当时我控制不了自己，当时我脑子里一片空白......？这就是没有觉察到自己的情绪，被自己的情绪控制了。如果你提高自己的情绪觉察能力，会不会能更好的认识自己，更好的和周围的人交流，做一个善解人意的人呢？\u003c/p>\u003cp>好，那接下来请大家用1-2分钟时间阅读一下手里的拆页内容，在阅读过程中，请画出您认为的几个关键词。\u003c/p>\u003cp>A3促动参与\u003c/p>\u003cp>相信大家都画出了自己的关键词，也看到了提高情绪觉察的练习的2个步骤，第一个步骤，用比较精准的情绪词语去问自己或对方。第二个步骤引导当事人分享他内在的感受和外在发生的事情，倾听时做到关注和接纳。\u003c/p>\u003cp>前面我们通过做自测题，理解自测题，看拆页，理解拆页，知道了觉察情绪的重要性，以及怎么提高觉察自己和别人情绪的能力，接下来请大家2个人一组，我们做一个场景演练。场景是这样的，小明是今年7月份刚毕业的光电系的应届生，在公司职位是技术支持，这个工作对外部客户接触比较多。但是入职快半年，他觉得自己不适合做这个工作，有两次还跟客户起了争执,但他觉得是客户不懂技术，不是他的责任。刚入职的时候他还想过1年以后转岗做技术型销售，现在他觉得自己连销售的工作也不适合，怀疑自己的沟通能力，该何去何从他也很困惑，迷茫。这天下班的班车上，小花刚好和小明坐在一起，小花要运用拆页的2个步骤来觉察李雷的情绪，接纳他的情绪，倾听他背后的故事。小明在小花的引导下说出了自己的困惑，迷茫，对小花进行倾诉。\u003c/p>\u003cp>A2催化应用\u003c/p>\u003cp>我们今天拆的内容让大家了解了觉察自己的情绪，觉察他人的情绪的重要性，也学到了提高觉察他人情绪的2个步骤。那请大家回去后应用这2个步骤，在身边的人身上。第一步询问他的情绪是不是你推测的那样？第二步，引导她把她遇到的事情倾诉给你，你做一个很好的聆听者。。做完这个作业后，请大家微信联系我，把你做的作业的情况反馈给我做记录，谢谢大家。请问大家清楚做什么作业了吗？\u003c/p>\u003cp>反馈的作业完成情况：\u003c/p>\u003cp>朱艳：我问儿子，你看起来好象不开心哦？是有什么事情吗？儿子回答：我的英语考试打了88分，我觉得我应该可以打95分的。就因为有二题的单词写漏了字母，好不应该啊，有些懊恼，所以不开心。\u003c/p>\u003cp>廖威雄：我看到同事好像很累的样子，就询问他：你怎么了？一大早就感觉你好像很疲惫呢，有什么事吗？\u003c/p>\u003cp>同事回答：是啊，这些天好累啊，这周项目赶进度，每天都加班到晚上9点半，有一个星期都没运动过了，晚上又睡不好。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1487308549000,"updated_at":1487726786000,"ria":true},{"id":1668,"topic":"爱的五种能力之述情的3个句型","learn_goal":"使用述情3个句型中的一个，提高自己表达需求，想法和感受的能力","remark":"","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"马辉","city":"珠海"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是马辉，是二级拆书家。今天我和大家一起来拆TF3-1。首先介绍一下这次拆书的学习目标，在跟随我一起学习完这个拆页后，大家可以使用述情的3个句型中的其中一个，来让对方更了解自己，改进自己表达自己需求，想法和感受的能力，解决人们觉得伴侣不懂自己的问题。\r\n场景：首先给大家介绍一下今天要拆的这本书《爱的五种能力》，大家在日常生活中有没有看到这样一种情况，有一些女孩子常常不把自己喜欢什么，不喜欢什么告诉自己男朋友或老公，反而让对方去猜，女生觉得：如果你爱我，你就应该知道.........，这就是缺乏这本书里提到的述情的能力。\r\n提问：大家以前遇到或者看到身边的人遇到这种事，一般是怎么处理的呢？是不是很多人会说柴米油盐酱醋茶的琐事难免的啦，甚至可能开玩笑说吵吵更健康，其实这就是由于缺乏了述情能力导致的。\r\n影响：有些夫妻，虽然结婚了，但彼此并不真正懂得对方，也不主动打开自己的心和对方述情，这个时候如果出现一个他认为懂他的人，他会不会精神出轨，甚至离婚呢？\r\n解决：这本《爱的五种能力》的作者就在书里提出在生活中提高自己情绪管理、述情、共情、允许、影响五种能力，及练习的具体方法","ratings_count":0,"texts":[{"id":4229,"quote":"\u003cp>爱是需要能力的\u003c/p>\u003cp>大多数的家庭没有给人们真正的爱的功课，父母用自己的方式爱孩子，孩子长大了用自己的方式爱自己的爱人和孩子，结果却不一定遂愿。付出的人真正付出了爱，但被爱的人常常感觉不到爱，或父母不知道如何爱孩子，孩子长大了也不知道如何爱别人，因为不会爱。\u003c/p>\u003cp>爱是需要能力的，爱上一个人不难，难的是懂得如何跟相爱的人相处。正所谓“相爱容易相处难”，爱是一门学问，并非天生就会，需要后天学习。\u003c/p>\u003cp>述情这种爱的能力在爱情的经营中是非常重要的，用带着爱的方式表达自己的需求，想法和感受。\u003c/p>\u003cp>人们在表达和沟通上常犯的错误是，要么有了情绪或需求不说，闷在心里，忍不住了才爆发。要么常常用指责和抱怨的方式来表达和沟通。\u003c/p>\u003cp>隐忍伤害自己，指责和抱怨伤害对方。所以述情是情感关系里最合适的沟通方式，让人明白“原来你是这么想的。”\u003c/p>","explains":"\u003cp>我们归纳一下这个拆页的意思：爱是需要能力的，而述情是爱的能力非常重要的一个能力。那什么叫述情呢？述情就是觉察自己的情绪，并且正确表达自己的感受和想法。老婆对老公说：你总是这样，从来不帮我分担家务，我现在很生气。这叫不叫述情呢？老公有没有可能说：什么叫“从来”，上周日晚上地是谁拖的，碗是谁洗的，不是我做的吗？所以老婆说的不是事实，这不叫述情，因为述情是基于客观事实的，这种绝对性的字眼，比如：总是，从来等等，不是客观事实。在日常沟通中，人们其实经常会这么说，就会直接导致对方的反对，感觉夸大或者扭曲了事实，会激起对方反驳的欲望。就可能争论的焦点从老公不做家务，变成了对老婆说话方式的争论。举个例子：老公对老婆说：你就应该下班早点儿回家带孩子！”这个是述情吗？老婆可能会觉得：谁规定的我就应该下班早点儿回家，或者我回来晚了点儿，难道就错了？我下班后和闺蜜吃个饭，逛个街有什么不对吗，你不也是有时候下班就和同事去喝酒烧烤。这也不是述情，为什么呢？“你应该”是从“做正确的事”角度讲的，是讲道理，不是讲情。意思是对方应该这样做。这样做是对的，不做就是错的，上升到了对和错的高度。而对错并没有绝对的标准，所以双方很容易发生争论。\u003c/p>\u003cp>所以，我们归纳出述情的基本步骤：第一个步骤：识别自己在当下产生了情绪，比如比一个女孩儿给他男朋友打电话，打了三个都没人接，她继续打，此时她可以摸着自己的心，觉察一下此刻她是什么感觉？生气吗？委屈吗？有没有被抛弃的感觉呢？情绪经常会和身体的感受关联，比如你的心，你的胃。第二个步骤：运用述情的基本句型来讲话。\u003c/p>\u003cp>句型一：事实+感受\u003c/p>\u003cp>当爱人让自己感受不好或好时，用这个句型告诉爱人自己的感受。比如：老婆说看到你来轻轨站接我，我觉很开心。或者老公说：老婆，只是因为我去国外出差忘记带你要买的东西了，你就说我不靠谱，心里没有你，我觉得挺难过的。\u003c/p>\u003cp>句型二：告诉爱人自己的需求，而不是解决方案。\u003c/p>\u003cp>当人们把解决方案说出来后，它不一定是最优的，对方就只有同意和不同意两个选择。当对方不同意时，人们就容易感觉对方不理解自己。其实对话者也是有责任的，因为自己没有把需求讲出来。所以，跟爱人沟通时，一定经常把自己的需求讲出来，对方就会一起来探讨解决方案。\u003c/p>\u003cp>比如：老婆对老公说老公，这段时间我觉得好累，每天忙家里的公司的事儿，筋疲力竭。我想放松一下。这里老婆说自己累，想放松，就是表达自己的需求。而不是直接给出解决方案。\u003c/p>\u003cp>句型三：说出我希望，不说“你应该”\u003c/p>\u003cp>“我希望”只是告诉对方我很希望你这样做，意思是这是我需要的你爱我的方式。是从愉快的角度讲，是讲情讲爱的。说：你应该”就是从对错的角度说对方应该那么做才是对的，不那么做就是错的，。举个例子：老婆说，老公，我觉得我们最近沟通变少了，我希望晚上睡觉前可以有十分钟聊聊天可以吗？\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：大家都清楚刚才拆页里面的2个步骤和述情的句型了吗？有没有什么疑问？述情在爱的能力中有着重要意义大家同意吗？现在，我们来试着用日常生活中的一个场景，来编一个小故事，这个故事里可以运用到述情的2个步骤，识别自己有了情绪，然后运用述情的某一个句型来沟通。剧本几百字就好了，不用太多，在这个故事里面，我们设计出事情的背景，人物，起因，经过，情节，结果。沟通双方，说了什么，做了什么，请问我表述清楚了吗？那大家现在开始编剧本，我们稍后请小伙伴分享一下。大家可以自己一个人编，也可以找个拍档2个人一起编一个剧本。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>肖龙扮演老公，朱艳扮演老婆\u003c/p>\u003cp>肖龙：老婆，你怎么这么晚才回来？孩子都没人带，你心里还有这个家吗？\u003c/p>\u003cp>朱艳：（内心独白：在公司辛苦加班，回到家没句温暖的话，还被指责，觉得好不爽，但一想到这样说会吵架，就换了一个方式）老公，我也很想早点儿回家陪儿子，但是公司年底的确很忙，不得不和同事们一起加班，你那么说我，让我觉得很委屈，很不被理解和支持。工作让我觉得好疲惫呀，要是回到家可以得到你的安慰，我就会觉得很幸福，开心。\u003c/p>\u003cp>肖龙：好，来，老婆过来抱抱。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482456088000,"updated_at":1482456088000,"ria":true},{"id":1458,"topic":"新页TF3-2定级","learn_goal":"完成定级","remark":"爱的五种能力","level":"TF3-2","duration":45,"status":0,"type":0,"chaishujia":{"username":"新页","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"大家好！我叫叶斐，叶是叶子的叶，斐是成绩斐然的斐，因为我对每个阶段的自己都有不同的目标和要求，所以也给自己取了个小名叫新页，希望每天都是新的一页，每天都有新的改变。也感谢大家从百忙之中抽空出来一同学习和交流。","ratings_count":0,"texts":[{"id":3970,"quote":"\u003cp>【图书介绍】\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、事件场景 ：\u003c/strong>现在请大家闭上眼睛，仔细回忆一下在你的爱情或婚姻当中，曾经所发生的争吵或不快多数是由于什么原因导致的？是倾向于你在当下无法接受对方这样或那样的缺点吗？如果是请默默举起你的右手向我示意，因为大家都是闭眼的状态所以你可以遵从真相和内心来表达自己的想法。好的，谢谢大家的配合，请放下。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、提问：\u003c/strong>通过刚才的举手示意，有超过一半的小伙伴们选择了因当下无法接受对方的缺点而导致双方发生不快或争吵。如果再遇到这种情况，大家会怎么处理呢？处理的效果又是如何？\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、影响：\u003c/strong>其实刚才大家的反应体现了一个普遍的共性就是不接受或不允许爱人有缺点。思考一下，一个看周围的人，看到的都是别人的缺点，或是总是因为别人有缺点而产生不愉快，是不是反倒凸显自己一个更大的缺点，那就是自己的包容和接纳度不够，也就是允许的能力欠缺。\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>、解决：\u003c/strong>今天，我给大家带来一本书是知名的情感教练、婚姻家庭咨询师赵永久所著的《爱的五种能力》，这本书不仅详述了一个人应具备的哪五种爱的能力，包括情绪管理、述情、共情、允许和影响。还通过作者以及学员身上的真实的案例和简单易学的学习步骤来更好的帮助我们提升这五种能力。而今天要带拆的其中的片段也就是允许爱人有一个成长的过程，将快速的帮助大家解决刚才我们所谈论的问题。\u003c/p>\u003cp>【A1】请大家自测\u003c/p>\u003cp>在阅读片段之前，我们先请小伙伴们做一下六道自测题，了解一下你目前允许的能力如何？请按照1-5分的标准给自己打分，1代表完全不符合，5代表非常符合。\u003c/p>\u003cp>1、 我介意对方的缺点。\u003c/p>\u003cp>2、 现在让我说出对方的缺点，我信手拈来。\u003c/p>\u003cp>3、 对方在同一个事情上犯第二次错误，我会新账旧账一起算。\u003c/p>\u003cp>4、 我很容易原谅自己所犯的错误，但对于对方所犯的错误我难以快速释怀。\u003c/p>\u003cp>5、 我的注意力极少放在怎么让争吵快速平息上。\u003c/p>\u003cp>6、 和爱人争吵，对方所说的多数气话，历历在目。\u003c/p>\u003cp>【I】解释自测题\u003c/p>\u003cp>如果您六道题的总分低于12分，恭喜你，你是一个包容和接纳度较好的爱人。但如果您的总分高于24分，则很抱歉的告诉您，您的允许能力有极大的欠缺，需要认真的反思和总结，也希望通过接下来对拆页的学习，能帮助大家速提升允许的能力。\u003c/p>\u003cp>【阅读原文】\u003c/p>\u003cp>可以成长的事情，是些什么事情呢？\u003c/p>\u003cp>很多时候，这些事情就是我们认为的对方的缺点，对方做不好的事情。比方有些人不会做家务，有些人自理能力差，有些人人际交往能力差，有些人学习能力差，有些人沟通能力差等，但凡人身上的一些短板，都是可以成长的地方。\u003c/p>\u003cp>我们要允许对方有一个成长的过程，这与不允许有很大的差别。不允许的时候，当对方在这些方面的能力差时，我们会指责对方，不接纳对方。而允许的时候，我们不再指责，不再抱怨，不再想着改变对方。\u003c/p>\u003cp>其实，所有人都有短板，人的短板都是为了适应自己所成长的环境而形成的，原来的环境中不需要他们具备这些能力，所以，他们这些能力并没有得到成长。\u003c/p>\u003cp>比如，有些人在成长中父母为他操心过多，没有给他照顾自己的机会，所以，他就不需要发展出太好的照顾自己的能力，这是对他成长的环境的适应。父母做饭、做家务，而不让子女做家务的家庭，他们的孩子在这个环境中长大，做饭、做家务的能力当然就差，因为根本就没有得到锻炼的机会，没有成长这个方面的能力，差是理所当然的事情。\u003c/p>\u003cp>问题往往就在这里，在原来的家庭由于不需要这些能力，所以没有成长出来。而组建了新家庭以后，爱人却希望他们具备这些能力，当发现他们不具备时，就急于改变他们。这等于环境变了，环境要求他们具备这些能力，而他们暂时却没有。这本质上是他们对这个环境的适应出现了问题，要给他们一个适应的过程，允许他们慢慢地发展出这些能力，而不是不接受他们甚至指责。\u003c/p>\u003cp>一个新婚的学员向我诉苦说：“我渐渐发现他有一些不好的生活习惯，做事动作特别慢，洗澡、刷牙都很磨蹭。最近我的手受伤了，不能沾水，拜托他饭后洗碗，但他洗完碗常常忘记擦桌子，桌上一片狼藉。”\u003c/p>\u003cp>是的，这就是可以成长的事情，做事慢可能是长期一个人生活没有人催促形成的，洗碗而忘记擦桌子很可能是原来的家庭中父母就没有让他擦过，先不要说他这样是对还是错，在他原来的成长环境，这些都不是问题，原来的环境对他没有这些要求。\u003c/p>\u003cp>新的家庭是新的环境，对他有了新的要求，要给他一个适应和成长的过程，也就是要暂时允许他有这些特点，然后慢慢地去影响，很可能在不知不觉中，他的这些特点就得到了成长。\u003c/p>\u003cp>而往往爱人们总是很着急改变对方，看到对方这样就接受不了，开始评价对方的对与错，开始指责，结果这样可能让对方感觉新婚的生活很不幸福，对婚姻生活开始不适应起来，这不但不利于对方的成长，还会降低两人婚后生活的幸福感，严重的可能引发婚姻危机。\u003c/p>\u003cp>这些可以成长的事情，其实在每个人身上都有，我们每个人都可以成长得更好，但需要有人先允许我们这样，我们才能在这个环境中待着很舒服，才愿意在这个环境中生活，时间久了自然就会慢慢地适应这个环境。\u003c/p>\u003cp>如果爱人懂得一些影响的方法，自己也就慢慢地发生了变化，等过了一段时间，自己可能已经成长了很多，却没有任何难受的感觉，因为这个过程中，自己是被认可和允许的，而不是被否定。\u003c/p>","explains":"\u003cp>拆书家：在看完这段拆页后，不知道在场对哪个词汇印象比较深刻？\u003c/p>\u003cp>小英：允许。\u003c/p>\u003cp>拆书家：在这个片段当中是否有发现到自己也有过一些类似的心态？具体有哪些呢？\u003c/p>\u003cp>小英：就觉得对方怎么这样呀！ \u003c/p>\u003cp>拆书家：就是有不允许、不接受对方的一些感受，对吧！而今天之所以选择这样一个拆页与大家分享，是因为在婚姻生活当中，我在起初就是因为允许的能力不够，眼里看到的总是我老公身上的缺点，再加上我的个性过于强势，总是着急迫切的希望他马上改变，而我老公又恰恰是个慢性子的人，结果可想而知，婚姻总在不停的指责争吵中度过。幸好，我是一个看到问题愿意积极解决的人，在认真阅读了一些关于婚姻或心理调试的书籍之后，慢慢发现是因为自己的包容和接纳度不够，总是用己所欲而施于人的观点去要求对方，殊不知每个人都有短板，每个人家庭生长的环境不同自然具备的能力也不同，因而允许对方与自己有差异存在，允许对方有一个慢慢成长的过程，其实对双方都是一个很好的修炼更是爱的境界的提升。现在我不仅拥有了较好的允许能力，同时通过接受允许的心法训练，更好的修复我个性上的缺失，让我更懂得宽容关爱他人。\u003c/p>","interaction":"\u003cp>【A3】\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>其实所谓的允许心法就是在任何时刻，当正在发生或想起一些不愉快的事情时，能够冷静地对自己说“我允许”！通过察觉内心的感觉，让自己感到放松，把可能发生冲突而产生的心理压力逐渐降低的过程。为了加深大家对允许心法的领悟，我们现场做一个演练：小王是一个脾气有些急躁强势的女孩子，明天就是搬新家请客的好日子，为了能够把家里布置的更干净整洁，小王下班一回到家就开始马不停蹄的收拾，老公小林是个比较懒散的男孩子，从小被家长宠溺惯了，什么家务活都不会，还喜欢指挥别人。这会，小王在客厅和厨房都收拾三个小时了，刚进书房要收拾却看到老公小林一边玩网络游戏还把吃的零食垃圾堆得到处都是，小王不高兴的说：“我干得这么辛苦，你既不帮忙尽给我添麻烦！”，小林说：“不就是搬个家吗？都是亲戚朋友，那么熟了，至于那么认真收拾嘛，何况人家也不一定会来书房看！”……（这里要求小林的扮演者态度平和但始终就是不搭把手，还叫小王不要收拾，不需要用心对待他人来家里做客这事；请小王的扮演者必须有一个不允许的心态到允许的心态的转化，要求看出态度和语气的变化） ,现在进行两两分组，小蔡和小虹一组，小慧和小英一组，时间为3分钟。&nbsp;\u003c/p>\u003cp>\u003cstrong>现场角色扮演（逐字稿）：\u003c/strong>\u003c/p>\u003cp>小慧：我干得这么辛苦，你既不帮忙还给我添麻烦？\u003c/p>\u003cp>小英：不就是搬个家吗？反正亲戚朋友都很熟了，不用那么认真收拾，何况人家也未必会来书房参观呀？\u003c/p>\u003cp>小慧：亲戚朋友也是客人呀，你总不至于让客人一进门就看到乱糟糟的，是不是会让人感觉待客不够周到？\u003c/p>\u003cp>小英：会乱糟糟的吗？我感觉还好吧。\u003c/p>\u003cp>小慧：你看看，如果客人进到家里来，我会让他们知道因为客人的到来，老公前一天帮我打扫收拾家里如此干净，你说客人会不会觉得非常的开心呢？\u003c/p>\u003cp>小英：其实还好啦，本来也不乱，如果打扫太干净反倒会让客人很拘束，这里也不敢踩，那里也不敢进。其实随意一点才有家的感觉呀。\u003c/p>\u003cp>小慧：这个说法也是对的，只是我们能否把桌面摆放得更整齐一些，这样会显得更美观呀。\u003c/p>\u003cp>小英：不要紧啦，就那么一点点地方，不需要精益求精的。\u003c/p>\u003cp>小慧：其实如果我们打扫得更整洁，会让客人觉得我们非常欢迎他们，他们也会感到很开心的。\u003c/p>\u003cp>小英：没事啦，就是书房而已，再说他们也未必会进来，客厅已经很干净啦，对吧。\u003c/p>\u003cp>小慧：那行吧，你说的也对，就差书房而已，那你稍微把桌面整理一下，其余的我来做，这样可以吗?\u003c/p>\u003cp>小英：嗯，那好呀，我就把桌面打扫下，你比较细心剩下的就麻烦你来做了。\u003c/p>\u003cp>小慧：好的。\u003c/p>\u003cp>拆书家：很感谢这组小伙伴的现场演练，大体上已经把角色领悟得相对透彻了，知识点也把握得比较好。因为我们做这个练习目的就是当正在发生或想起一些不愉快的事情时，能够冷静地对自己说“我允许”，通过察觉内心的感觉，让自己感到放松，把可能发生冲突而产生的心理压力逐渐降低的过程。在这个过程中，小慧一直再慢慢调试，尽管小英非常坚持自己不搭把手的原则，但小慧在说话的方式和语气，到最后的允许退让，体现了一个心态转变的过程。作为拆书家，在前期案例的选择和准备上，未必能完全满足于当下所有小伙伴的现实体验，但有一段话对我来说很受用，也希望大家能够认真用心阅读和感受，它可以更加快速的帮助你提升允许的能力。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>拆书家：现在请小慧阅读一下这段话。\u003c/p>\u003cp>我允许。\u003c/p>\u003cp>我允许我出生在这样的家庭，我允许家里发生的一切，我允许我在这样的家庭长大。\u003c/p>\u003cp>我允许自己有这样的父母和祖先，我允许他们用他们的方式对待我，我允许他们曾经的错误，我允许他们对我所做的一切。\u003c/p>\u003cp>我允许我自己，我允许自己的成功，也允许自己的失败，我由于成功而成长，由于失败而成长。\u003cbr> 我允许有人不喜欢我、否定我、讨厌我、误会我、不理解我、仇恨我，无论别人怎么看待我，我都允许。&nbsp;\u003cbr> 我允许有人曾经伤害我、嫉妒我、打击我，我也允许我曾经伤害过、嫉妒过、打击过他人。\u003c/p>\u003cp>我允许这世界上的所有事物，对每一件事物我都允许，我允许白天，也允许晚上，我允许天晴，也允许下雨；我允许人的出生，也允许人的死亡；我允许成功，也允许失败，对于自然界的每个事物，我都允许。&nbsp;\u003cbr> 世界发生的一切事情，或在身边，或在很远的地方，我都允许它。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>感谢小慧的朗读，今天的拆页分享就到这，要求在座的小伙伴们在回去之后能细心品味“我允许”这段话，并反复朗读铭记于心。在接下来的一个月时间里，请你刻意地留心自己曾经不能允许他人的一些场景、是否已经学会用允许去接纳和包容了，并将当时的对话记录下来，事后复盘总结，以帮助自己尽快的提升允许的能力。谢谢各位！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1480294829000,"updated_at":1480294829000,"ria":true},{"id":1436,"topic":"新页TF2-4定级","learn_goal":"完成定级","remark":"爱的五种能力","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"新页","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"大家好！我叫叶斐，叶是叶子的叶，斐是成绩斐然的斐，因为我对每个阶段的自己都有不同的目标和要求，所以也给自己取了个小名叫新页，希望每天都是新的一页，每天都有新的改变。今天我要带拆的书籍是《爱的五种能力》。","ratings_count":0,"texts":[{"id":3942,"quote":"\u003cp>【图书介绍】\u003c/p>\u003cp>\u003cstrong>F 特征（核心是“书”，用于满足好奇心）：\u003c/strong>\u003c/p>\u003cp>《爱的五种能力》是由知名情感教练、婚姻家庭咨询师赵永久所著，他提出：爱一个人需要具备爱的能力，它包含情绪管理、述情、共情、允许和影响这五种具体能力。而这五种能力恰恰也是情商的具体体现。该书结合了真实的案例来详述这五种能力，帮助你重新认识爱，修复爱，拥有爱，传播爱。\u003c/p>\u003cp>\u003cstrong>A 优势（重点是“比较”，用于建立安全感）：\u003c/strong>\u003c/p>\u003cp>这本书一经推出便荣获豆瓣9.1分高分的推荐，口碑极好。著名心理学家杨凤池、麻辣情医吴迪、百合网CEO田范江都倾情推荐，甚至有许多读者买了几本几十本用来送人，他们希望更多人看到这本书，希望更多的人可以更幸福。\u003c/p>\u003cp>\u003cstrong>B 利益（强调的是“学习者”的利益，用于引发兴趣）\u003c/strong>\u003c/p>\u003cp>如果此刻你一直单身，迟迟找不到合适的人；或者全心全意对对方好，人家却不领情；在婚前信心百倍，婚后不尽人意；婆媳关系一直处得不理想，很苦恼；正考虑要不要离婚；或婚姻关系中已经出现了第三者等等，我建议阅读此书，因为这正是你所需要的。\u003c/p>\u003cp>\u003cstrong>第一个RIA\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>【阅读原文】\u003c/p>\u003cp>情绪是原始的，也是非理性的，因此，它有时是不够精细的，有时也是会搞错的，想要管理好自己的情绪，就先要学会在众多起情绪的事情里边，先把这样的情绪找出来，并学会管理它们，不要让它们总是出来打扰到你平静的心情，也不要让它们总是来影响到你的生活。\u003c/p>\u003cp>这些的情绪是这样产生的：\u003c/p>\u003cp>一个周末的下午，你约一个新认识的异性朋友两点钟见面，你提议到一个你常去的咖啡馆见面，定好地点后，你把地址通过短信发到他（她）手机上了。\u003c/p>\u003cp>你是一个守时的人，在一点五十分之前就到了，足足提前了十分钟。\u003c/p>\u003cp>看到咖啡馆里没有你约的朋友，你找了个靠窗的位置坐了下来，随后，你顺手拿起了一本杂志漫不经心的翻起来。\u003c/p>\u003cp>时间很快到了你们约定的时间，下午两点钟，他（她）还没有到，你心里有了一个对他（她）的看法：原来这是一个不太守时的人，居然迟到了。\u003c/p>\u003cp>时间已经过去了五分钟了，他（她）还没有到，你心想，他（她）居然迟到了五分钟，看来他（她）不怎么把你放在眼里，你有一点点小生气了。\u003c/p>\u003cp>十分后，他（她）还没有到，你压住心中的一些气愤，拿起手机，准备给他（她）打个电话，拨完号码，你深呼吸了一下，并把手机放在耳边听着拨号音。\u003c/p>\u003cp>“对不起，您拨打的号码已经关机！”手机里传来了这样的声音，你更加生气了，你觉得这个人简直是不把你放在眼里。\u003c/p>\u003cp>二十分钟后，他（她）还是没有到，电话依然是打不通，你已经很生气了，心想做人怎么可以这样呢？既然是遇到了事情需要晚来，也要打个电话说一声啊！\u003c/p>\u003cp>你越想越生气，觉得这样的人简直不可交，于是，你拿起手机，放下杂志，走出了咖啡馆。\u003c/p>\u003cp>你生气了，这是潜意识在对你进行提示，那么，你的潜意识在提示你什么呢？\u003c/p>\u003cp>很明显，潜意识在提示你，有人居然不尊重你，你需要给这样的人一点教训，或远离这样的人。\u003c/p>\u003cp>但是，潜意识的工作方法是纯粹感性的，是很原始的，潜意识忽略了一个重要问题，这个人不尊重你只是你的一个假设，不一定是事实，事实有很多种可能，到目前为止，你还不知道什么是事实呢？\u003c/p>\u003cp>可你已经很生气了，这就是潜意识原始和非理性的地方。\u003c/p>\u003cp>这个人不尊重你，只是你编的一个故事而已，只不过你很相信你的编的这个故事，所以，你才会很生气，甚至决定马上离开这个地方，再也不想见到这个人。\u003c/p>","explains":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>今天要带拆两个片段，刚才已经让大家先认真阅读了第一个拆页，也许此刻有的人心里会有些不服气，也许他曾经验证过他所谓的假设就是事实，因此在下一次出现类似事情的时候，不自觉地就会按照之前的假设去想象，但这仍旧不能成为你把潜意识呈现出的假想作为事实的理由，毕竟实际的可能有很多种，就算你碰巧猜中开头，也未必猜中结尾。举个我自己身上的例子吧，前段因工作调动调换到新的学院任职，寝室也随之改变，结果被换到比较破旧不堪的老校区公寓，不仅墙壁和木门都非常陈旧，连卫生间和洗浴间的木门全被白蚁蛀光了，仔细看都觉得毛骨悚然。于是联系物业来治理白蚁，还订制了贴墙纸的师傅来帮忙装修，外面阳台的墙面买来乳胶漆自己粉刷，一整天工作下来疲惫不堪。回到家后，看到桌上还堆放了饭后未收拾的碗筷，我的潜意识马上关联成我的老公不心疼我，不爱我，不帮我还给我添麻烦的场景，瞬间就气炸了，正准备开口大骂的时候。我老公满脸堆笑地说：“老婆，今天加班我也刚到家不久，想说你辛苦了一天，留了点汤回来等你喝，所以把碗筷先放着，待会你喝好了，我再一块收拾。我现在把汤热一下，你先在沙发上休息会哦。“看着他转身走进厨房的背影，却留下一脸茫然不知所措的自己。想想，如果当下我是先发了脾气，而我老公本来想体贴心疼我的却因莫名的被误会和被批评也许一下子也来气，跟着起争执，那后果是不是不堪设想，而这一切的源头竟是因为一个错误的假设引发，那多得不偿失啊！\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>现在请大家仔细回想一下，近一个月内在你的工作或家庭生活中，发生过什么样的事情在那一瞬间让你有被误解或委屈的感觉。或者是你曾经误解或让对方感觉到委屈的事情，思考两分钟，然后我找一到两个小伙伴进行分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>小英：我有一个工作的案例想和大家分享一下。就是我们那有个门店经理想在店里做个水吧，一来引入客流二来门店能够创收，并在某次会议上向公司提出需要人力物力上的支持。当下我就给她发了短信，希望她能把具体的设想和建议流程发个文字版过来，结果第二天她就发给我了。在我认真查看之后，发现这还不是个简单的事情，这可能需要业务部门的支持大过于培训部门的人力支持，而且包括我在内也还没有想好如何很好的支持到她的门店设想，所以就暂时搁浅了。加上最近事务性较多，我到昨天晚上才想到给她回复了消息，结果她立即做了回复：“没事，我知道了，你又不是负责这项事情的，是我的错，不该和你说。”一看到这个简讯，我一脸就懵了，瞬间感到委屈、感到不被尊重，心情很低落。后来我还是尽可能的调整好心情，往好的方面想也许她当时有困惑才这么说的吧。过了一会，我还是回了条短信，问她是怎么回事，她才说她感觉设想提出来之后，没有得到想要的回复，感觉不被重视，同时也困惑是不是不该和我商量要找业务部门的主管商量才是。我这才把心结放下，认真的和她进行电话沟通，告诉她一个设想的提出要给出怎样的数据同时该把策划书呈报给哪个部门较为合适。后来她很感激的对我说，谢谢我这么费心教她这么多东西，她也知道下一步该如何做了。虽然这是一件小事，但在当下确实经历了你拆页中所提到的那样的一个心路历程。\u003c/p>\u003cp>拆书家：是不是当你第一次收到她短信回复的时候，脑中立马浮现一个错误的假设？\u003c/p>\u003cp>小英：是呀，那一刻立马就感觉到很冤很委屈。\u003c/p>\u003cp>拆书家：后来你调整了情绪之后及时做了验证，让原本已经引发的不好情绪一下子通过验证让自己释怀，也化解了本来可能已经产生的误会。\u003c/p>\u003cp>小英：是的。\u003c/p>\u003cp>拆书家：非常感谢小英的分享。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":3943,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二个RIA（35-40分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一、【R】阅读原书拆页\u003c/strong>\u003c/p>\u003cp>对于因假设而起的情绪，我们知道那是自己编的故事，是假设，有时可能是事实，有时可能不是事实。我们要管理这类情绪，而不是不作假设。不作假设，人们可能就没有创新和推理的能力了，也就不能很好地分析事物了。\u003c/p>\u003cp>管理这类情绪，有两个方法，可以根据具体发生的事情的类型和重要程度，结合使用。\u003c/p>\u003cp>一个方法是：\u003cstrong>无为\u003c/strong>。所谓无为，就是知道自己暂时了解不到真相，而真相又是可以随着时间的推移而呈现出来的，并且知不知道真相关系也不是特别大，或者不知道真相也不会引起太大的不良后果，这时，选择什么也不做。简单说，就是知道自己针对眼前发生的事情，所产生的每个想法都是假设，不是事实，索性不再作任何假设，等待事情自然呈现真相。\u003c/p>\u003cp>如果你在咖啡馆等朋友，他迟到了没有来时，你管理情绪的方法是：如果他不来也不会给你带来太大的不良后果，你之后也没有特别重要的事情要做，不如就坐在那里，看看杂志，喝喝咖啡，不再作任何假设，因为你知道，你所想的种种可能，都不一定是事实，你没有必要再用各种假设来引起自己的种种情绪，进而折磨自己，你可以心平气和地享受这个下午。这样你的情绪马上就平复下来了，而且你会很享受这个时光，不会因为他的迟到而影响到你的心情，等他到时，或者他主动联系你时，你自然就知道了事情的真相。这样，你就使用“无为”的方法，完成了一次有效的情绪管理。\u003c/p>\u003cp>通常情况下，对方迟到了，都是事出有因，等你知道了原因，你可能就不会有生气这个情绪了。即便是对方迟到的原因真的是不尊重你，你知道了真相再生气也不迟，这样在十次同样的情况里边可能有八九次，你其实是不用生气的。（即便是对方不尊重你，也不要生气，因为你要\u003cstrong>允许\u003c/strong>有人不喜欢你。）\u003c/p>\u003cp>我在平时等人时，尤其是有人跟我约了咨询时，我通常会在等待时看会儿书，如果到了时间我等的人还没有到，我不会立即打电话问对方，而是采取“无为”的方式，静静地等待，一般过不了多长时间对方就到了。\u003c/p>\u003cp>另一个方法是：\u003cstrong>验证\u003c/strong>。当你有了一个假设，这个假设让你感觉事情可能很严重，你不一定要无为，你可以采取情绪管理的另一个方法，跟随情绪的提示，去验证你的假设，更早地让事实的真相呈现出来。但切记，在你的假设没有得到验证之前，你要牢牢记住，这只是你的假设，这样，你的情绪就会好得多。很多情况下，事实可能并不像你想象的那样，当你发现这一点，也就是事实并不是你假设的情况时，你的情绪就完全消失了。这样，你就有效地避免了因为潜意识这个原始的、非理想的提示方式而额外产生的情绪，那些“庸人自扰之”类的情绪就不会发生在你身上，你也就不会误会别人了。\u003c/p>\u003cp>这个方法，不只是可以管理你的一些情绪，还可以让你和他人之间少产生误会和误解，但也请你务必记得，这个方法，不是不让你作假设，而是在假设没有得到验证之前，你必须清醒地知道，这只是个假设，还不是事实，单单就这一点，就可以让你的很多没必要的情绪消失。\u003c/p>\u003cp>这两个情绪管理的方法，很多时候是要结合的，当你无法“验证”时，你只能采取无为，就像你在咖啡馆等朋友，你打电话他关机了，你无法及时验证了，这时“无为”、好好享受下午的好时光就成了最佳选择了。\u003c/p>\u003cp>管理好这种因假设而引起的情绪，让自己不要再编个故事气自己，你就可以让自己的情绪更加平静，也就能有心情更好地享受生活、享受爱情了。\u003c/p>","explains":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【I】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>其实通过第一个拆页的学习，我们已经很清楚某些潜意识的假设很容易造成当下情绪的不快，更甚者会产生不必要的误会和麻烦。而通过本拆页“无为”和“验证”的学习，能够更好的帮助我们在当下管理好情绪，而不会自己编造一个故事来让自己生气和恼怒。好比我老公，从小在父母的溺爱下养成了走到哪东西就丢到哪的坏习惯。想必每个家里都会有这么一个形象，可能是爱人也可能是孩子。不管我怎么和他强调，拿出来的东西用完要放回原位，他总是听归听做归做，几乎一点改变都没有。近来他因工作事务性繁多，经常出差，每每回来总是机票、发票、车票、报告、U盘、证件乱丢一通，为了体谅他的辛苦并保持家里环境的整洁，我毫无怨言的帮他收拾好东西。但他几乎每次找东西都要大呼小叫：“老婆，我那份报告你放哪了？”“老婆，你看见我的U盘了吗？”等等，这潜台词好像是在责怪我把他的东西乱放，让他找不着了。其实这样的潜意识是我长期的忍耐和委屈积累出来的假设，于是现在似乎变得有些条件反射了，只要他一询问我东西放哪，我就感觉内心烦躁，怒火中烧。在学习了情绪管理方法之后，我尝试就此问题和他进行交流，把我内心的假设告诉他，并进行验证。而结果却出乎意料，原来他只是习惯于用这样的方式去寻找在家里丢失的东西，毕竟从小到大他一问，父母就能找出他要找的，所以他认为我也像他父母一样，如同哆啦A梦，需要什么只管说就会有，他压根对我就没有任何责怪的意思，相反他一直很感激我，张罗好家里的一切，只怪他自己坏习惯太多想改老改不彻底。得知他是这样的想法之后，我也释怀了，后来我们协商并特地腾出一个大抽屉专门供他堆放临时乱丢的东西，他只要想找东西就去那里找，这样就不会老开口问我，我也不用老跟在他身后去收拾，而周末他也乐意腾出半天时间专门收拾好该抽屉的东西。同时我也提醒他在下次表达的时候，可以用“老婆，不好意思，我没找到什么东西，你看到了吗？”这类友好的询问语气，会让我更欣然接受。因此当我们能很好的管理起自己的情绪时，反倒会让思路开阔，头脑变得更加聪慧，竟然能够想出一个双赢的好办法，可见拥有管理好情绪的办法是多么的重要啊。\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>现在为了加深大家对“无为”和“验证”这两种管理情绪方法的理解，我们现在一起做一个演练。请大家认真听一下要演练的场景：小王和小林经常轮流请吃饭，小王的家境比小林优越一些，本来这次轮到小王请客，且请吃饭的地点又比较高档，两人一顿下来吃了800多块。结果买单的时候小王说自己忘记带钱包了。这时，小林的心情发生了变化，脸色有些难看……\u003c/p>\u003cp>现在，请每两人一组，进行演练。一个人扮演小王，一个扮演小林，请双方都运用到“无为”和“验证”这两种管理情绪办法进行一次良好的沟通。\u003c/p>\u003cp>演练时间为3分钟，现在开始。3分钟后，我会选择一位“小王”和“小林”，大家一起听听他们是如何运用这两种管理情绪办法进行沟通的。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>小虹（小王）：糟糕，我忘记带钱包了。\u003c/p>\u003cp>柒功（小林）：哦，真的没带呀。（脸色有些难看）\u003c/p>\u003cp>小虹（小王）：是呀，今天着急出门，真忘记带了。\u003c/p>\u003cp>柒功（小林）：没关系，那就这次我请，下次你请。（有些无奈）\u003c/p>\u003cp>小虹（小王）：这次本来是轮到我请的，应该我掏钱，一定是我来请，只不过是你先帮我付个钱，回头给你。\u003c/p>\u003cp>柒功（小林）：那要不我先付掉，回头你转账给我。\u003c/p>\u003cp>小虹（小王）：好的，没问题。\u003c/p>\u003cp>拆书家：在刚才的场景扮演中是是不是感觉到有些尴尬？\u003c/p>\u003cp>小虹：是呀，挺尴尬的，都不知道该怎么接话了。\u003c/p>\u003cp>小英：我听着也感觉到很尴尬。\u003c/p>\u003cp>拆书家：这是一个生活中会出现的例子，因为今天所要掌握的是情绪管理的方法，可能在对白上未必能体现得淋漓尽致，但在这样一个场景的要求下，参与对话的当事人则会立马体验到心理的微妙变化，我们可以通过事后的讨论把内心的变化说出来。现在就可以进行分享和补充了。\u003c/p>\u003cp>小英：那我来说一说吧。其实在当下被迫要付钱的内心状态是很纠结的，在那一刻只能按无为的状态来处理，让自己的心情瞬间能快速的平复下来，不要有过多的错误的假设在脑海里产生。如果对方说：“没事你先付，我一会把钱转给你。”可能那一刻我立马会很客套的说：“那算了吧，这次我先付，下次你再请也一样。”假使对方接着说：“不行，这次本来就轮到我请，我还是回去转账给你。”那这会就是个验证的状态，被迫付钱的那个人在当下心情会好受很多也会舒服很多。那假使对方是说：“那行，这次你来买，下次轮到我。”那被迫付钱的那个人在当下可能就是另一种不好的情绪体验了。这就是所谓验证得到的信息不一致，对于被迫付钱的那个人心里所产生的情绪反应也会不同。\u003c/p>\u003cp>小虹：在这个角色扮演中，如果我是小林，在发现忘带钱包的时候，我会转身向小王说你能不能先借我八百块，我明天还给你。这样就避免了我在当下假设的对方可能会因我没带钱包而被迫付钱内心有尴尬的局面，也让我们之间的关系不会出现误会和不顺。\u003c/p>\u003cp>拆书家：谢谢小英和小虹，从两个不同的角色出发进行了一次有效的情绪管理方法，特别是通过这样直接的剖析把内在的心理变化，用无为和验证的方法巧妙的化解了内心的疑虑和当下情绪的不适。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>通过刚才的场景扮演，你对这两种管理情绪办法或多或少有了初步的认识，你觉得在你的工作或家庭生活中可以如何运用这两种管理情绪办法来帮助你平复平时容易引爆你不开心的情绪点或事情呢？\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>小英：我想到我们公司一个讲情绪管理的老师说过的一句话：“就是当你想表达某种情绪的时候，请先在当下冷静30秒。”这就是一个无为的阶段，在这个阶段中让自己的情绪冷静下来，再去表达，那一刻你的理性就恢复了出现了。而验证就是在理性出现恢复的时间里所能解锁出来的解决方案。所以在我以后工作或家庭生活中找解决方案的时候不要让情绪出现得比理性更快。\u003c/p>\u003cp>拆书家：让自己刻意慢30秒下来，是吧？\u003c/p>\u003cp>小英：是的。\u003c/p>\u003cp>柒功：可慢30秒很难做到哦。\u003c/p>\u003cp>小虹：我讲一个案例，我们部门有个培训专员，工作两三年比较年轻，之前教孩子学英语，也许孩子比较调皮捣蛋，所以她经常发脾气，以至于把这样的坏习惯带到现在公司的面对成人的培训课程中来。有一次课程中，我发现她带着很强烈的情绪在批评学员，一直说是他们的秩序不好导致整个培训效果很差。我觉得她的做法不妥但也没有在当下直接指出来，而是在事后单独找她询问，她竟然没有觉得自己有发脾气，可见她对她的情绪是不自知的。后来我便静下心来慢慢和她分析这样处理的坏处是什么，怎么处理才能有好的效果，也告诉她得学会观察自己的情绪，不要把目光只是定睛在别人身上。所以在工作中我会经常用无为的方式来管理情绪，等事后再进行验证。曾经在我当培训专员的时候，我的上级因为我的一个错误当着全体学员的面批评了我还罚了我50元钱，以至于在那一周面对学员上课的时候，内心始终处于惶恐的状态，甚至有了心理阴影，所以我特别能感同身受类似的情况，尽可能去理解他人，即便对方做得不对，我也会保全她的面子再表达和沟通。\u003c/p>\u003cp>拆书家：因为你有类似的经历所以你不希望别人和你一样产生心理压力，毕竟这需要一段时间的心理建设才有可能迈过去，所以你尽可能的在当下用无为的方式去管理自己的情绪，有可能的情况下在事后再找当事人用验证的方法进行验证。柒功你有什么想分享的吗？\u003c/p>\u003cp>柒功：我爸爸特别爱叨叨，钟点工过来家里洗碗不放洗洁剂他就不停的叨叨，那我说行了，我来洗碗，结果我用水龙头冲水洗碗他也叨叨说我不懂得节省，应该要盛一盆子水来洗就好了，要不水龙头的水一直哗啦啦的流太浪费了。我都快被叨叨得疯了，不过现在的情绪管控力比之前好很多了，要不早就冒火了，但还是会忍不住，怎么办？\u003c/p>\u003cp>拆书家：那你在这个过程中是否有运用到无为或验证的情绪方法来管理自己的情绪呢？\u003c/p>\u003cp>柒功：验证？难道和他说：“老爸，你是不是觉得这水比较浪费？”，我觉得我说不出口。\u003c/p>\u003cp>拆书家：从你的案例出发，我个人感觉在这类事情上更适合用无为的方法，不是凡事都要运用到验证，它和无为都属于情绪管理方法，可以交叉使用的。特别是老人家已经这么长久的习惯养成，没有办法一下子转变，只能转变我们自身，比方我们冷静30秒或逃离当下那种让自己很困顿的场景。\u003c/p>\u003cp>柒功：不可能，我们家就这么点大，他就会一脚踹开门。\u003c/p>\u003cp>拆书家：在那30秒你应该想到的是既然改变不了爸爸，我就改变我自己，我就态度很友好的很真诚的说：“好的，爸爸，我下次会按照你说的方法来做，你放心。”\u003c/p>\u003cp>小虹：可说实话，要别人改变是很难，但改变自己也绝非易事啊。\u003c/p>\u003cp>拆书家：所以我们才聚集到一起相互学习，相互提升，相互改变。如果不尝试改变自己的心态，管理好自己的情绪，到最后受伤的可不止一个你而已，整个家庭的情绪氛围和状况都会不好的。\u003c/p>\u003cp>柒功：那看来我得尝试着顺着他来做了。\u003c/p>\u003cp>拆书家：其实从心理学的角度来考虑这个问题，特别是老人家他所谓的叨叨未必真的是需要你听进他所说的话，而是希望你能关注到他，就像我们常说的刷存在感一样，渴望得到儿女的爱。如果你那一刻不就着洗碗的话题和他一直纠结，可以直接转个话题比方他的兴趣点或者他爱看什么电视剧，最近进展到什么阶段等，结果就会不一样了，你可以尝试看看。\u003c/p>\u003cp>柒功：好的，那我试着好好改变一下自己的心理状态。虽然有时候自己很不想转变。\u003c/p>\u003cp>拆书家：你现在对你的孩子是不是很有宽容度很有耐心、爱心？\u003c/p>\u003cp>柒功：当然。\u003c/p>\u003cp>拆书家：那就把你的爸爸当成你的孩子，就像闽南方言俗语所说的“老人如小孩”，有爱心有耐心宽容的接纳。\u003c/p>\u003cp>柒功：好难哦，多年的生活积累，因为和爸爸的关系一直不好，一直容易吵架。但我愿意尝试改变看看。谢谢。 \u003c/p>\u003cp>\u003cstrong>结语（1分钟）\u003c/strong>\u003c/p>\u003cp>我们今天通过第一个片段知晓错误的假设会带来哪些不好的后果，在第二个片段之后通过无为和验证的方法来更好的管理和解决情绪问题，加上刚才大家对柒功的案例进行了热烈的讨论，从中延伸出在无为和验证之外比方转移关注点这样管控情绪的好方法，达到双赢的效果。希望大家在今后的工作、学习以及家庭生活中能始终管理好自己的情绪，避免一些不必要的误会和麻烦，让自己也让周围亲近的人愈来愈感觉与你相处非常幸福、快乐。回去之后可以认真阅读一下《爱的五种能力》这本书，里面有许多案例可以更好的辅助你学会无为和验证的情绪管理方法。谢谢各位!\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1480082418000,"updated_at":1480082418000,"ria":true},{"id":1338,"topic":"用影响的方式处理问题，用强化的方法施加影响","learn_goal":"用影响的方式处理问题，用强化的方法施加影响","remark":"","level":"TF2-4","duration":50,"status":0,"type":0,"chaishujia":{"username":"马辉","city":"珠海"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"片段一：\r\n通过学习这个片段，大家可以了解到改变别人和影响别人二者之间的区别，我们应该要用影响的方式来处理事情。通过肯定对方的某些行为的方式来潜移默化的影响对方的做法。\r\n《爱的五种能力》一书，它是由国内资深情感教练赵永久先生所著。书中详细介绍了情绪管理、述情、共情、允许、影响五种能力，及练习的具体方法。很多人因为自己没遇到爱的人，或错过了爱的机会，或拥有过又失去了爱人，开始不相信爱情，其实他们是缺乏“爱的能力”。如果想拥有爱情，你不仅要有爱的激情，更要有爱的能力。 越来越多的人面临着爱的缺失，部分源于当今的浮躁，部分源于义务教育中情感知识体系的贫瘠，部分源于原生家庭亲密关系的冷漠或者过度。当我们无法从原生家庭和学校里面获取正确的爱情能力时，走向社会势必会出现各种各样的情感问题。这本书的益处是：通过这本书，我们学会爱是一种可以培养的能力，通过觉察，我们感受自己的情绪，理解别人的情绪，通过书中提供的五种爱的能力的方法的学习和锻炼，提高大家爱的能力，从而更容易爱和被爱。\r\n片段二：学会施加影响的方法，通过及时奖励对方做的好的地方，来强化对方好的行为，从而提升和伴侣，家人和朋友的关系。","ratings_count":0,"texts":[{"id":3806,"quote":"\u003cp>片段一\u003c/p>\u003cp>影响和改变，目的都是希望对方发生一些好的变化，都是希望对方成长，但两者很不同。一个丈夫对妻子说，你从来都不化妆，不打扮自己，我不知道你是怎么想的。丈夫说这个话当然是希望妻子可以打扮自己，希望妻子可以有些改变，但妻子可能会想：我一直都是这样，从来没有变过，你这样说，是不是不爱我了？因为丈夫使用的是改变，不是影响。改变，给对方的感受是被否定，是否定对方现在的做法，希望对方换一种做法。而很多人是受不了被否定的。当有人想通过否定使其改变时，他的注意力就停留在对对他的否定上，因为他接受不了对他的否定。这就是改变的特点，等于告诉对方：你那样做不对，你要怎样怎样做。\u003c/p>\u003cp>影响的做法是：比如告诉妻子，我特别喜欢你打扮后的样子，或者你上次在商场试穿的那件衣服，特别符合你的气质，有空我陪你多买点那种风格的衣服吧。如果男朋友最近没有接送自己，女朋友如果用改变的方法可能会说：你最近怎么都不来接送我了？用影响的方法可以说：想起你以前经常接送我上下班的情景，觉得好幸福呀。影响对方是潜移默化的过程，对方感觉的是被肯定。\u003c/p>\u003cp>片段二\u003c/p>\u003cp>强化：及时奖励对方做的好的地方\u003c/p>\u003cp>人们都知道马戏团里的老虎可以钻火圈，狗熊会骑自行车，海狮会顶球。这些动物天生是不会这些技能的，那么它们是如何成为马戏高手的呢？频繁的责备是不会让一只海狮学会用鼻尖顶球额，这个方法也同样适用于丈夫。每次丈夫把穿过的衬衣投进脏衣篮里，我就感谢他，如果他投进2件脏衣服，我就吻他一下。\u003c/p>\u003cp>施加影响的方法，就是在对方做了一些自己希望他做的事情时，及时强化对方。很多人做不到不去帮助别人，因为这样他们的控制欲，或者他们的好为人师的需求就无法得到满足。他们可能特别需要通过帮助别人做事情来显示自己的价值和被需要感。什么是强化呢？这是个行为心理学的名词，说的是在操作条件反射的过程中，对于正确反应后所给与的奖励，也叫正强化。举例来说，如果人们希望自己的狗学会蹲下。那么就在它听命令时给它食物，反之不给，慢慢的狗就可以学会听主人的话蹲下。运用同样的方法可以训练狗站立，跳舞。这也是人的学习机制，比如第一次赌博赢了钱的人，他的赌博行为得到了强化，因此他继续赌博的可能就被加大。而作好事的人，第一次做了好事受到表扬，他继续做好事的可能性就会更大。\u003c/p>","explains":"\u003cp>片段一的I\u003c/p>\u003cp>1、这个拆页介绍了影响和改变的区别在于：改变是当对方做了自己不喜欢的行为时，否定对方。而影响是肯定对方做的符合自己期望的事情。 结论就是：我们应该要用影响的方法来处理事情。\u003c/p>\u003cp>2、影响和改变的不同做法带来的不同结果在于：当你采用改变的方法的时候，对方会觉得被否定，可能会引起争吵。而采用影响的方法，对方会觉得被肯定，并且可能会继续做你肯定和期望的这件事。\u003c/p>\u003cp>3、可能有的朋友会说采用影响的方法，太麻烦了，说不定我的伴侣会觉得我是不是受了什么刺激，怎么突然不像以前那样直接要求他做某些改变。也可能会有朋友觉得采用影响的方法，太温柔了，有的人啊就是吃硬不吃软。但是如果你不采用影响的方法，可能会更麻烦，可能会让你们的关系恶化。这个拆页的步骤可以理解为：1内心里明白用影响的方式和改变的方式是不同的，并且影响的方式更有效。2影响的方式就是肯定在某方面对方正在做的，或者曾经做的符合你的期望的事情的案例。\u003c/p>\u003cp>4、举个例子：比如说一对夫妻，作息时间不同，妻子早睡，老公晚睡，妻子如果用改变的方式要求老公早点儿睡觉说你怎么每天都那么晚睡觉，你每次睡觉都把我吵醒，第二天又经常起不来，对身体也不好，就不能早点儿睡呀。可是如果她换成影响的方式说：老公，我特别喜欢刚结婚的时候，每天晚上10点半左右我们洗完澡，睡前我靠在你的肩头，你握着我的手，两个人聊聊这一天忙忙碌碌的事情，觉得特别幸福。这就是用影响的方式处理事情。\u003c/p>\u003cp>片段二的I\u003c/p>\u003cp>1、这个拆页通过用训练动物的方法来说明我们在生活中，也可以通过及时奖励对方做的好的地方，来进行正强化。\u003c/p>\u003cp>2、给出的施加影响的步骤就是，步骤一：发现对方做的好的地方；步骤二，用强化的方式，可以是鼓励对方的话语，可以是一些小奖励，比如拥抱，亲吻，给他捶捶背部，捏捏肩膀，买个小礼物等，这个可以你自己选择。你要问问你自己，你还希望他这个好的行为再次出现吗？如果你想的话，那强化的这个方法就是你的最佳选择哦。\u003c/p>\u003cp>3、举个例子，老公之前出差买衣服给老婆，老婆会说：你这什么审美标准呀，你会不会买衣服呀？那老公可能下次就不愿意给老婆买衣服了。但如果老婆说：哇，老公，谢谢你，出差那么忙，还记得给我买衣服，我太喜欢这件衣服了，太适合我了。我觉得好开心好幸福呀。这个时候，老公也会觉得被认可，觉得很开心。所以你期望什么行为对方多次做，那就去强化它吧。\u003c/p>","interaction":"\u003cp>片段一的A1\u003c/p>\u003cp>大家平时在和伴侣或者家人或者朋友相处的时候，有没有出现过自己用改变的方式，而不是影响的方式要求对方，或者有没有遇到别人用改变的方式要求你，比如老婆说：你怎么总是把脏衣服到处乱丢，就不能随手丢到洗衣机里或者脏衣篮里吗？ 回忆下最近一次你遇到这种事情，是什么时候？发生了什么事情？然后运用拆页的方法，如果这个情况再来一次，你会怎么用影响的方式来处理呢？请大家想一想，待会请小伙伴们分享。\u003c/p>\u003cp>学习者案例记录：朱莹：我有个朋友是素食主义者，跟她吃饭，我就觉得她只是吃素材，营养不均衡，希望她可以营养均衡点儿。\u003c/p>\u003cp>朱艳：我儿子经常把看过的书到处扔，我说就会说看你把书扔的乱七八糟的，赶快收拾起来吧，就是要求对方改变，没有给他引导，而是否定他。如果用拆页的方法，其实偶偶我儿子也有过不乱扔书的情况，下次如果出现这样的情况，我会夸奖他说儿子我看到你把书放回书柜了，你真棒！妈妈给你点赞哦。\u003c/p>\u003cp>华子：我儿子昨天晚上刚发生的，昨天出去玩儿，很脏，回到家想让他先洗澡，他说不行，要玩一会儿再洗澡。我就要求他必须先洗澡。如果运用拆页的影响的方法，因为有时候儿子也会有很乖的的情况，如果下次出现，我就夸他：宝宝今天早早的洗澡哦，好干净，是个香宝宝哦，真棒，来，爸爸亲一下。\u003c/p>\u003cp>片段二的A3\u003c/p>\u003cp>拆书家提问设计（逐字稿）：我们刚刚学习了用强化的方式来施加影响，让对方的好的行为可以多次出现，现在我们一起做一个场景演练，大家可以简要的把剧情台词概要写下来。老婆韩梅梅，老公李雷生活在珠海香洲，李雷的爸妈生活在斗门。老人家希望李雷夫妻两个可以每周末回来斗门陪伴他们。韩梅梅其实内心里是不太愿意周末花时间跟公公婆婆待一起的，毕竟不是自己家，不自在，而且婆婆也会催她要孩子。这个周末韩梅梅和李雷又开车回斗门老家了，扮演老婆的韩梅梅主动帮婆婆做家务，陪公婆聊天，散步。李雷要运用拆页的方法，来强化老婆韩梅梅的行为，夸奖，鼓励，肯定，感谢，感恩，买小礼物，拥抱都可以。大家可以设计一下场景。待会请大家做这个场景演练。\u003c/p>\u003cp>学习者案例记录：老公-肖龙扮演：梅梅，今天我看到你陪爸妈做了不少家务，又陪爸妈散步，爸妈非常开心，作为儿子，我也为他们开心，谢谢你，我觉得好幸福呀，你今天也辛苦了。老婆：不用谢，老公，这些都是我该做的。老公：我看你今天在斗门也辛苦了，今天晚上我来做饭，刷碗吧，你就看看电视，看看你喜欢的韩剧吧。老婆：哇，老公，你太体贴了。我爱你。\u003c/p>\u003cp>片段二的A2\u003c/p>\u003cp>拆书家提问设计（逐字稿）：在坐的各位女士，不知道有没有遇到过老公忘记你的生日，忘记你们的结婚纪念日等特殊日子，虽然可能他也有偶偶记住过的情况呢？在坐的各位男士，有没有遇到过老婆把家里收拾的不够干净，或者孩子做作业拖拉，收拾文具拖拉的情况呢？大家应用所学的拆页的方法，如果再遇到类似的情况，你会怎么去强化对方的你期望出现的行为呢？需要注意的是，不能仅仅是决心，而是要写下具体的做法，要有明确的时限，要有可衡量或可观测的预期结果。因为时间关系，我们等会只选一位朋友来分享他的具体实践计划。\u003c/p>\u003cp>学习者案例记录：威雄：我每次放假回家看望爸妈，爸妈总是会做很多菜，上次国庆晚上11点多到家，我妈把菜端出来，鸡鱼菜汤饭，一个完整的晚餐，可是我已经跟老妈千叮呤万嘱咐了，我已经在公司吃完晚饭了，所以让她不用给我做饭了，后来我才知道我妈晚饭没吃，一直在等我回来一起吃饭。为什么我叮嘱后她还要做饭留给我吃呢？想起来她以前没有做饭等我的时候，我什么也没说，给老妈的感觉就是她觉得自己没做饭等我，她会有点儿内疚。运用拆页的方法，如果下次她没有做饭，我就会说幸亏老妈你没做饭，要不然我又要撑的睡不着啦。真棒，谢谢你妈妈。这么说多几次，就会强化老妈的这个不做饭的行为。\u003c/p>\u003cp>angelchen:我女儿刚上小学，感觉要使劲洪荒之力来提醒自己娃儿是我亲生的。小孩子经常做作业很拖拉，注意力不集中，拖拖拉拉，磨磨蹭蹭，有时候就会说她你写作业拖拖拉拉，要写到几点？ 如果以后出现这样的情况，尤其是当她某一次出现认真，卷面整洁的时候，我就会及时强化，对她说：今天妈妈看到你写作业特别认真，注意力很集中，那么快把作业做完了。奖励你今天晚上就可以早点儿去楼下和小朋友玩儿或者可以玩儿会实验，然后跟她一个give me five。其实她也希望可以早点儿下楼和小朋友玩儿，但是习惯了拖拉，然后每次拖拉都挨批，我想偶偶她出现不拖拉的情况，我就要及时强化她，也许以后她拖拉的情况就会减少。\u003c/p>\u003cp>朱艳：我儿子卫生方面，要催促才做一下，不催就不搞。有一次我下班回来看到房间很干净，我就说：哇塞，房间怎么那么干净，卫生是谁搞的？我儿子就说：我呀！ 我就说：哇，儿子，妈妈看到你进步了哦，以前都要我说你才做，现在你看你这么主动，我觉得你很棒哦。通过夸奖来正面强化他。\u003c/p>\u003cp>曹振华：我儿子回家不喜欢先洗澡，喜欢先玩玩具，也是个老大难问题，要和他斗智斗勇，因为一般我们是去奶奶家，再去姥姥家，这样回到家就很晚了。但也有偶偶早早去洗澡的时候，下次如果出现他先洗澡这个情况，我就会夸他：儿子，你今天早早去洗澡了，很棒哦，爸爸很高兴，是个香香的宝宝哦。然后我会奖励他看他喜欢看的动画片，让他看个一两集，或者给他喜欢的牛奶。用这个奖励的方式来强化他早点儿洗澡。\u003c/p>\u003cp>结语：\u003c/p>\u003cp>我们今天分享了改变别人和影响别人二者之间的区别，可以学到通过通过肯定的方式来潜移默化的影响对方的做法。学习了施加影响的方法，强化对方好的行为，从而提升和伴侣，家人和朋友的关系。希望大家学习了这2个拆页后，可以在生活中熟练运动，获得更好的人际关系，提升幸福感。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1479437050000,"updated_at":1479437160000,"ria":true},{"id":1279,"topic":"爱的五种能力之允许","learn_goal":"在看到自己看不惯的行为时，可以从态度和行为上做到“允许”。","remark":"","level":"TF2-3","duration":20,"status":0,"type":0,"chaishujia":{"username":"马辉","city":"珠海"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是马辉，今天我拆的是TF2-3，今天的学习目标是：在跟随我完成本次RIA现场学习后，大家可以在遇到身边的朋友，尤其是家人的一些看不惯的行为的时候，可以从态度 和 行为上 做到“允许”，具体行为就是自己对自己默念：我允许ta怎么怎么样。然后没有因为对方这个行为而起冲突。\r\n我今天分享一下我要拆的这个拆页是来自《爱的五种能力》一书，它是由国内资深情感教练赵永久先生所著。书中详细介绍了情绪管理、述情、共情、允许、影响五种能力，及练习的具体方法。很多人因为自己没遇到爱的人，或错过了爱的机会，或拥有过又失去了爱人，开始不相信爱情，其实他们是缺乏“爱的能力”。如果想拥有爱情，你不仅要有爱的激情，更要有爱的能力。 越来越多的人面临着爱的缺失，部分源于当今的浮躁，部分源于义务教育中情感知识体系的贫瘠，部分源于原生家庭亲密关系的冷漠或者过度。当我们无法从原生家庭和学校里面获取正确的爱情能力时，走向社会势必会出现各种各样的情感问题。这本书的益处是：通过这本书，我们学会爱是一种可以培养的能力，通过觉察，我们感受自己的情绪，理解别人的情绪，通过书中提供的五种爱的能力的方法的学习和锻炼，提高","ratings_count":0,"texts":[{"id":3649,"quote":"\u003cp>第五章允许\u003c/p>\u003cp>允许是解决爱情中诸多问题的一条捷径。不管是对方和自己的差异，还是对方身上的缺点，或是对方与自己家人关系不佳，只要提升自己内心允许的能力，就可以舒缓情绪。很多人找对象的时候，从来没有考虑过可以允许对方有什么样的缺点，你在实际找对象的过程中一旦遇到有缺点的人，很可能会轻易放弃。\u003c/p>\u003cp>允许，用简单的话来概括，就是包容，就是接纳。对很多事情，能够包容和接纳，不仅仅是一种生活态度，更是一种爱的能力。比如，允许他晚睡，允许他晚起。允许他有小肚子，允许他乱扔袜子，允许他是路痴，允许有人不喜欢我.......\u003c/p>\u003cp>人活在这个世界，不可能事事顺心。如果人们允许不顺的事情存在，这些事情反而可能会离去，不再影响人们，一旦不允许这些事情存在。人们其实就是在调用内心的能量与这些事情对抗，人们马上就会受到这些事情的影响，这些事情会占据人们内心的心理资源，把人们的能量消耗掉，使得人们没有能量去做眼前的其他事情。\u003c/p>\u003cp>允许是内心强大的象征。一个人越是内心强大，越有允许的能力，越是内心弱小，越没有允许的能力。\u003c/p>","explains":"\u003cp>从上面的拆页可以看到允许，在我们日常生活中的巨大价值，允许可以改善自己和家人，和朋友的关系，可以减少把能量消耗在不允许别人做某些事上面，可以让自己慢慢变的内心强大起来。\u003c/p>\u003cp>允许的步骤：1态度上允许。端正观念，相信自己和对方成长环境不同，所以处事方式不同。\u003c/p>\u003cp>2行为上允许。不批评指责，给对方成长空间。自己对自己说：我允许对方做什么什么事。\u003c/p>\u003cp>假如，有个人一直和父母一起住，一直以来父母替他做事太多，没有给他学习自己照顾自己的机会，所以他就不需要发展出太好的照顾的能力，但在新组成的家庭里，他这个特点可能就成了短板。这里我举个例子。rose和jack刚结婚，jack做事动作比较慢，洗澡，刷牙都磨磨蹭蹭。吃完饭，jack负责洗碗，洗碗的时候也是超级慢，还会忘记擦桌子。rose要是以前就会批评jack太磨叽了。但采用拆页里的方法，她就会告诉自己：jack是独生子，从小在家父母宠着，所以可以理解他父母也不要求他做家务，所以我允许jack做事慢，我允许jack忘记擦桌子。我要给jack空间，让他锻炼和成长。\u003c/p>\u003cp>再举个例子：有的父母看到孩子做事情笨手笨脚的，就会代替孩子做一些比如系鞋带，比如收拾书包，这其实也是不允许。如果使用拆页里的方法，父母就在心里对自己说， 我允许孩子收拾书包慢，我允许孩子系鞋带慢吞吞的。\u003c/p>","interaction":"\u003cp>我们刚刚学习了允许可以让我们更快乐，更容易爱，更强大，现在我们一起做一个场景演练，大家可以简要的把剧情台词概要写下来。老婆rose工作勤奋，努力的经营自己的事业，取得了一些成功。老公JACK成长在一个家庭温暖的家庭，他的父母都是乐天派，很懂得享受生活，jack觉得钱够用就行，剩下的时间应该用来享受生活的美好和陪伴家人。老婆当时看上jack，有一个很重要的原因也是觉得jack给他家的温暖感觉。但结婚后，rose慢慢会对老公指责，抱怨他不求上进，国庆之后，连续上7天班，蛮累的，10月11日下午3点多，jack就发微信对老婆说，拱北新开了家大草原西北餐厅不错，我们晚上去吃吧，然后再一起去看新电影。老婆当时正在忙工作，看到老公的短信，要是以前的话，就会气不打一处来，觉得老公对工作不上心。扮演老公的人就假装在手机上给老婆用语音发信息，约老婆晚上出去嗨，说到大草原的美食，美酒。扮演老婆的人，运用拆页的方法，第一步从态度上允许，理解老公的成长环境差异，这时候rose的内心独白可以通过自言自语的方式来表现，第二步，从行为上做到允许，老婆自己对自己说，我允许老公上班时间就开始想着下班吃好吃的，然后老婆回复老公说反正晚上也要吃饭的，那就今天晚上不做饭，我们去吃好吃的吧，老公就可以回复一个么么哒之类的秀恩爱一下，请问我表述清楚了吗？我需要提醒各位的是，在讨论和演练中，重点是应用刚才所学到的技能，而非仅仅是应对演练中的某个场景问题，因为同一个场景问题，可能不止是一个解决方法，我们今天要做的是尝试在运用所学到的允许。请问我表述清楚了吗，那我们现在开始分组讨论。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>威雄扮演老公，小敏扮演老婆。威雄给老婆打电话说：老婆老婆，我们晚上去拱北愚园吃饭吧，听同事说那里新开了一家大西北餐厅，超正点呢，烤串很不错，啤酒都是在楼下现酿的，而且还有超大屏幕可以同时看球赛，吃完饭还可以去看看电影，最近上映的湄公河行动评分很高哦。老婆看看欧米伽手表说：“老公，现在才下午3点，我好忙的呀”。威雄：“老婆老婆，你看你这段时间也辛苦了，刚好放松一下呀”。老婆心里暗想：恩，威雄从小父母都是教育他开心享受生活，我当时就喜欢他这种乐天派。所以他上班时间想着晚上吃喝玩乐，也可以理解，而且也的确连续上7天班了的确蛮累，结婚后我们也很久没有约会了。于是老婆继续对老公说：“好呀，老公那下班的时候你过来接我吧，晚上我们就幸福的去约会”。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1478829836000,"updated_at":1478830719000,"ria":true},{"id":950,"topic":"爱的五种能力之共情","learn_goal":"学会共情的方法","remark":"","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"马辉","city":"珠海"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是马辉，今天我拆的是TF2-2，今天的学习目标是大家通过这个片段的拆书学习后，可以学习共情的四个步骤，掌握共情的方法并应用到自己的生活中。这个拆页是来自《爱的五种能力》一书，它是由国内资深情感教练赵永久先生所著。书中详细介绍了情绪管理、述情、共情、允许、影响五种能力，及练习的具体方法。很多人因为自己没遇到爱的人，或错过了爱的机会，或拥有过又失去了爱人，开始不相信爱情，其实他们是缺乏“爱的能力”。如果想拥有爱情，你不仅要有爱的激情，更要有爱的能力。 越来越多的人面临着爱的缺失，部分源于当今的浮躁，部分源于义务教育中情感知识体系的贫瘠，部分源于原生家庭亲密关系的冷漠或者过度。当我们无法从原生家庭和学校里面获取正确的爱情能力时，走向社会势必会出现各种各样的情感问题。这本书的益处是：通过这本书，我们学会爱是一种可以培养的能力，这就有了理论基础。通过觉察，我们发现与人交往的过程中很多问题都是爱的能力的问题，通过书中提供的五种爱的能力的学习和锻炼，来提高大家爱的能力，更容易爱和被爱。","ratings_count":0,"texts":[{"id":2892,"quote":"\u003cp>第四章 善解人意才会爱：共情\u003c/p>\u003cp>在人们找对象的过程中，择偶条件中，特别是男性对女性的要求中，一般都少不了一条善解人意。而女性也会要求男人能够懂我，懂我也就是要求男人能够理解女人，这和男人要求女人要善解人意基本上是一回事。善解人意可以理解为共情，就是可以经常理解对方的内心感受并能照顾到对方的内心感受。特别是当对方内心有不好的感受时，比如孤独，忧愁，害怕，困惑等，善解人意的人会让爱人感觉到自己被理解，这等于在内心给了对方接纳和认可，使其感受到来自爱人的支持。\u003c/p>\u003cp>关注情就是认可她的/他的这些情绪，而不是评论她这样想对不对，下面这四个步骤的练习可以提升我们的共情能力。\u003c/p>\u003cp>第一步，接纳。\u003c/p>\u003cp>询问对方的情绪，比如：我听到你刚才叹气，是心情不好吗？比如：你好像不开心是吗？这是使用的语句一定是问句结束的，这是在向对方求证，而不是肯定的语气。\u003c/p>\u003cp>第二步，了解。\u003c/p>\u003cp>引导对方分享他内在的感受和外在发生的事情。一个人有负面的感受，一定是有原因的，哪怕这个原因不是当下刚刚发生的事情，这一步需要注意，聆听的时候，一定要把事情从头到尾听完，尽量不要打断对方，让对方感觉到被关注和接纳。\u003c/p>\u003cp>第三步，肯定。\u003c/p>\u003cp>不是肯定对方有理，正确。人的坏情绪是由大脑的一些想法引起的,想法的形成是一个逻辑过程，要肯定的就是这个逻辑过程。\u003c/p>\u003cp>第四步，启发\u003c/p>\u003cp>通过提问的方式来启发对方进行思考，进而帮助对方，启发分为2步，第一，启发对方看到自身不足，理解他人。第二引导对方去关注未来，关注解决方案。\u003c/p>","explains":"\u003cp>这个片段提供了共情的四个步骤的方法。接纳，了解，肯定和启发。就是接纳他的情绪，了解产生这个情绪的原因或事件，肯定他产生这个情绪的逻辑，启发他自己去找到解决问题的方法。可能有的人会觉得这样太麻烦了，觉得平时的沟通方法省事儿多了，也可能会觉得有的时候根本就是条件反射，比如看到对方叹了一口气，就说：年纪轻轻的，叹什么气呀？而不是询问你是不是心情不好呀？事实上，如果你不去学习这4个步骤提高自己的共情能力，会更麻烦。比如老公小强在创业，起步阶段，困难重重，结果老婆小静就说他，才遇到一点儿困难你就这样，怎么成的了大事呢？你刚开始要创业的时候我就说了你不是那块料。老公可能有一种被否定的感觉。而如果另外一个女人对小强说：是不是最近压力很大，很累呀？。。。可以跟我聊聊你最近遇到的困难吗？.....你付出那么多，劳心劳力，家人也不理解，事业还是没有起色，的确蛮郁闷的。.....那你后面打算怎么办呢？这个时候老公就有出轨的可能，因为别的女人更能和他共情。也有可能有朋友会说，那万一我问对方是不是心情不好?对方说没事儿怎么办。这个时候也不用强迫对方，只需要告诉他如果你想聊聊，我随时有空哦。这样可以给对方一点儿空间，等他想说的时候再去聆听了解具体事情。\u003c/p>","interaction":"\u003cp>A2催化应用\u003c/p>\u003cp>分步催化1\u003c/p>\u003cp>大家回忆一下，在你过往的经历里面有没有遇到过当你心情不好的时候，别人不理解你，更有甚者在旁边说风凉话，或者讲些毫无关系的事情。或者当你的伴侣或家人心情不好的时候，你没有给与共情，甚至否认对方不值得因为某件事难过，或不开心的情况呢？\u003c/p>\u003cp>angel chen:这个在我们家经常发生，我有时候在公司里有什么委屈，回家跟我老公说了，结果我老公说，这个事情你就该反省你自己，检讨是不是自己不对，你要是怎么怎么样，说不定人家就不会那么说你了，本来我的委屈只有5分，结果被他一说，我的委屈上升到10分了。\u003c/p>\u003cp>马银花：我老公也一样，我跟他说一个什么让我生气或者委屈的事儿，他也是会说你要先反省反省自己，是不是自己哪里不好，做的不对。一点儿都不理解我的情绪，搞的2个人都不开心，问题也没解决。\u003c/p>\u003cp>A2\u003c/p>\u003cp>催化应用\u003c/p>\u003cp>分步催化2\u003c/p>\u003cp>设想一下，你看到你的伴侣或者家人，或者密友情绪似乎不太好，你该怎么应用这个拆页里面的四个步骤去和对方共情呢？\u003c/p>\u003cp>angel chen：我婆婆腰椎间盘突出，平时稍微多走一点儿路，就会腰疼，我就让她去哪儿都打车，别走路，老人家节省，所以经常走路，不舍得打车。我就又心疼她又生气，就会发火说你爱走就去走吧，到时候疼起来还不是自己受罪。学了这个共情的句型后，我下次要试着先询问她是不是很难受啊？当时你是怎么考虑的呢？是不是不舍得打车，觉得儿子媳妇儿挣钱也不容易啊？\u003c/p>\u003cp>然后让她说说心里的想法，当时为啥知道可能会腰疼，还是走路了。\u003c/p>\u003cp>然后我再说，是的，我爸妈也是像您一样节省，心疼我们年轻人。\u003c/p>\u003cp>接着启发她，但是妈，你看你要是腰疼，疼好几天，我们也不会让您做家务，这样我和老公忙碌一天回来还得做家务，还得照顾您，要是您的病加重，我们还要去医院看病，又花钱，这样，您看是不是得不偿失呢？\u003c/p>\u003cp>您看看我和老公最希望的就是您健健康康的，这样我们也不用那么担心和操心。\u003c/p>\u003cp>您以后可不可以听我们的，不要走路，去哪儿都打车呢？\u003c/p>\u003cp>这个时候很可能我婆婆就会同意了，也理解了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1474522085000,"updated_at":1474522113000,"ria":true},{"id":920,"topic":"爱的五种能力之放下对与错","learn_goal":"学会放下对与错，不以自己的标准来要求控制对方","remark":"","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"马辉","city":"珠海"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是马辉，在一家新三板上市公司从事培训和招聘工作。今天我拆的是TF2-1的环节。这个环节的学习目标是在跟随我完成本次RIA现场学习后，学习者能够在跟伴侣或者家人交流时，放下对错，优先考虑对方的感受。我要拆的这个拆页是来自《爱的五种能力》一书，它是由国内资深情感教练赵永久先生所著。书中详细介绍了情绪管理、述情、共情、允许、影响五种能力，及练习的具体方法。很多人因为自己没遇到爱的人，或错过了爱的机会，或拥有过又失去了爱人，开始不相信爱情，其实他们是缺乏“爱的能力”。如果想拥有爱情，你不仅要有爱的激情，更要有爱的能力。 越来越多的人面临着爱的缺失，部分源于当今的浮躁，部分源于义务教育中情感知识体系的贫瘠，部分源于原生家庭亲密关系的冷漠或者过度。当我们无法从原生家庭和学校里面获取正确的爱情能力时，走向社会势必会出现各种各样的情感问题。这本书的益处是：通过这本书，我们学会爱是一种可以培养的能力，这就有了理论基础。通过觉察，我们发现与人交往的过程中很多问题都是爱的能力的问题，通过书中提供的五种爱的能力的学习和锻炼，来提高大家爱的能力，更容易爱和被爱。","ratings_count":0,"texts":[{"id":2855,"quote":"\u003cp>情绪管理方法之三：放下对和错。&nbsp;\u003c/p>\u003cp>生活中发生了一件事情，人们也许并没有本能的产生情绪，而是经过理性的思维加工后，导致了不良情绪的产生，进而驱动人们去做一些理性或有害的事情。在大脑的理性加工过程中，对和错的标准起着重要作用，一旦有人做的事情不符合自己的标准，就容易产生坏情绪，尤其是在跟爱人互动的过程中，这些对和错的标准，使人们在表达时通常会把“应该”二字放在句首要求别人，进而希望别人的行为符合自己的价值判断。比如，一个男人回到家里，看到家里很乱，鞋子扔的到处都是，如果家里只有他一个人这些都是自己制造出来的，他一般不会起情绪，但是，如果他结婚了，老婆跟他一起生活，在他回家时，老婆正在看电视，他就很容易起情绪了。而他起情绪的原因，是他觉得老婆“应该”把家里收拾干净。让他起情绪的原因其实并不是家里乱，而是他脑子里的“应该”，他觉得老婆“应该”打扫却没有打扫，于是他有了生气这种情绪。这就是理性导致情绪产生的过程。通常并不是事物本身导致了人们的情绪，而是人们理性上对事物的看法和评价导致了情绪。情绪是理性加工的结果，不同的理性加工会导致不同的情绪。\u003c/p>\u003cp>方法：当觉察到自己的情绪是来自对别人的要求时，在内心告诉自己，不要拿自己的标准过多的要求别人，控制别人，包括自己的爱人。他想做一些让自己愉快的事情时，如果没有伤害到别人，尽量给他人宽松的空间，让他去做。因为这样做了他会开心快乐。\u003c/p>","explains":"\u003cp>通常来说，我们对同事普通朋友反而更宽容，对伴侣或家人会更要求更多，遇到事情的直接反应是说对方这样做是不对的。不按拆页里的行动建议去做的坏处是：比如一个妻子看到老公半躺在客厅沙发上看电视，双脚放在茶几上，看到这个场景，如果老婆对老公说：茶几是用来放食物和茶水的，不是用来放脚，你这样坐没坐相，多没素质啊，这个时候如果老公说这是我家，我想怎么坐就怎么坐，在公司那么多规矩，回到家还那么多规矩，你不累我都累，双方就有可能吵起来。让我们看一下前面的拆页，假如老婆看到老公把脚放在茶几上，起了情绪了，如果老婆可以意识到自己在拿对错的衡量标准要求老公。而老公放脚，是让他放松开心的方式，双方开心快乐比辩论到底谁对谁错更重要，家是讲爱的地方。明白了这一点，双方就不会起冲突，妻子的情绪也不会被老公是否放脚到茶几上这个动作控制。\u003c/p>","interaction":"\u003cp>A1激活经验\u003c/p>\u003cp>大家平时在和伴侣或者家人相处的时候，有没有出现过自己拿自己的标准要求别人，用自己认为什么是正确的，什么是错误的标准，来要求别人，影响别人的快乐。或者有没有别人按照他的对错标准要求过你按照他的来做的，回忆下最近一次你遇到这种事情，是什么时候？发生了什么事情？请大家回想一下，然后我会请朋友分享一下他过往的经历。\u003c/p>\u003cp>1、angel chen：那天我和我老公出去，我老公开车，因为平时主要是我开车，我对路也就比较熟，现在我怀孕了，就主要是老公开车比较多，那天我们要去一个地方，他要走A路线，我就说干嘛走A路线呢，你往哪个路，哪个路走不是更快吗？我老公有些不爽，我也不高兴，最后还是坚持了老公自己的选择，方向盘在他手里。其实这也和拆页里描述的类似，我认为他走他坚持的路线是错的，我就用了自己的对错标准来要求他，他不按照我的标准来，我就有些情绪。\u003c/p>\u003cp>A1+反思加工\u003c/p>\u003cp>假如这些场景重来一次，这一次你决定运用刚才拆页里提到的这些方法，你会选择怎么做，也许这件事情能处理得更好呢？\u003c/p>\u003cp>1、angel chen：如果我当时坐后排，不坐副驾驶，也不唠叨他，他愿意怎么走就怎么走，反正都是可以到达目的地的。所以下次我就会直接坐后排，看看书啊什么的，开车的事儿就完全信任并交给他。\u003c/p>\u003cp>2、彭铁桥：我的例子和angel chen的类似。下次我也会有意识的注意自己是不是要看用自己的对错要求老婆，我会闭嘴，让她开心，我也会开心。\u003c/p>\u003cp>3、马银花：我老公经常很晚睡，我觉得那样不利于身体健康，是不对的。就要求他12点必须上床睡觉，这也是我用自己的对错在要求他，以后我会尊重他自己的意愿。\u003c/p>\u003cp>4、华子：我爸妈喜欢给我小孩儿喂饭，我觉得这样是不对的，但他们认为没有什么不对，这是他们对孩子的爱的方式的表达，所以双方由于理念不同，就会互相认为对方不对，下次遇到这种情况，只要老人开心，我就不干预了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1474124680000,"updated_at":1474124680000,"ria":true},{"id":910,"topic":"爱的五种能力之表达感受2","learn_goal":"学会表达自己的感受","remark":"","level":"TF1-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"马辉","city":"珠海"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家晚上好，我是马辉，2007年毕业于华中科技大学人文学院中文系，目前在一家新三板上市企业从事培训和招聘的工作。今天我是拆TF1-2，先介绍一下我选的这本书《爱的五种能力》，它是由国内资深情感教练赵永久先生所著，书中详细介绍了情绪管理、述情、共情、允许、影响五种能力，并给出了练习这五种能力的具体方法。很多人因为自己没遇到爱的人，或错过了爱的机会，或拥有过又失去了爱人，开始不相信爱情，其实他们是缺乏“爱的能力”。如果想拥有爱情，你不仅要有爱的激情，更要有爱的能力。 通过这本书，我们知道爱是一种可以培养的能力。通过书中提供的五种爱的能力的学习和锻炼，可以提高大家爱的能力，使我们更容易爱和被爱。之所以选择这个拆页，是因为这部分有提供具体的HOW。","ratings_count":0,"texts":[{"id":2780,"quote":"\u003cp>第三章说出感觉容易爱：述情。\u003c/p>\u003cp>很多咨询师给遭遇情感困惑的人做咨询时，给出的辅导意见经常会有一句话，你需要学会表达自己的感受。每个人成长环境不同，决定了他们表达自己感受的能力不同。学会表达自己的感受才能为爱你的人画出一条走到你内心的线路图，掌握和你相处的窍门。爱上一个人是被她吸引，但被吸引不代表了解她，如果不告诉对方自己的想法和感受，又怎能埋怨对方不懂自己呢？以下句型可以让对方更了解你。\u003c/p>\u003cp>句型一，当自己心情不好的时候，直接告诉对方。很多人在生活中的习惯和和这个句型表达的观点是相反的。比如人们常说报喜不报忧。这是很多人从小所受的教育导致。比如：我今天心情不是很好。我今天感觉很失落。\u003c/p>\u003cp>句型二：当爱人让自己感受不好或好时，告诉爱人自己的感受。\u003c/p>\u003cp>这时的句型:事实+感受。\u003c/p>\u003cp>句型三：告诉爱人自己的需求，而不是解决方案。\u003c/p>\u003cp>当人们把解决方案说出来后，它不一定是最优的，对方就只有同意和不同意两个选择。当对方不同意的时，人们就容易感觉对方不理解自己。其实对话者也是有责任的，因为自己没有把需求讲出来。所以，跟爱人沟通时，一定经常把自己的需求讲出来，对方就会一起来探讨解决方案。\u003c/p>\u003cp>句型四，说出自己喜欢的，而不是不喜欢的。\u003c/p>\u003cp>在情感关系里，人们需要经常说这个句型，让爱人知道自己喜欢什么，想要什么，向往什么。这样不但让他感觉舒服，而且知道如何做能让你开心。他就能避免在猜测纠结上浪费时间。\u003c/p>\u003cp>句型五：说出我希望，不说“你应该”\u003c/p>\u003cp>“你应该”和“我希望”有什么区别呢？“你应该”是从“正确的事”的角度讲，是讲“理”的，意思是对方应该这样做，这样做是对的，不这样做是错的，上升到了对和错的高度。\u003c/p>\u003cp>但“我希望”不一样，“我希望”没有说对方不这样做事错的，没有评价对方，只是告诉对方我很希望你这样做。意思是这是我需要的你爱我的方式。是从愉快的角度讲，是讲情讲爱的。\u003c/p>","explains":"\u003cp>大家可以看到要和伴侣进行良好沟通的5个句型是第一，当你心情不好时，直接告诉对方。不要藏在心里。第二当伴侣做了什么事情，让自己开心或者不开心的时候，可以用事实+感受的句型告诉对方，第三个句型是，告诉对方自己的需求，而不是直接给出解决方案。第四个句型，说出自己喜欢的，而不是不喜欢的。第五个句型，说我希望，而不说你应该。针对第二个句型我举个例子说明，比如出差回来，伴侣来机场接你，你可以说：看到你来接我，我觉得好开心呀。第二个句型和第五个句型我也举个例子，比如：我有一个做研发的师妹，单身，家里一直催她找男朋友，父母总觉得她在外面工作几年了还是一无所有，觉得她很失败。她一开始是沉默，后面她采用事实加感受的方式，告诉父母自己的感受，她就跟她妈说，妈，我知道你也是为我好，希望我幸福。但是你和爸爸每次那么说我，让我觉得很难过，很委屈，我自己也希望找个男朋友疼我，爱我，可是感情的事儿不是说找就能找的，我也在努力的去扩大我的生活圈子，希望可以遇到那个合适的人。我希望你们更多的鼓励我，这样我会觉得至少我还有爸妈支持我。说出来之后，她感觉好多了，而且爸妈也觉得好吧，你也是那么大人了，自己把握好就行。\u003c/p>","interaction":"\u003cp>A1激活经验\u003c/p>\u003cp>我们读了这个拆页，了解到提升爱的能力的5个句型。那么，请大家想想自己有没有经历过类似情境，有没有过相关的经验，比如当你觉得难过的时候，开心的时候，有没有藏在心里。或者有没有出现过对伴侣说：你就应该怎么怎么样的情况。请在小组内分享，每人1-2分钟。\u003c/p>\u003cp>1陈芳芳angel：我有时候会说我女儿：你应该快点儿收拾东西，你应该按时上床睡觉等等。\u003c/p>\u003cp>2威雄：过年过节我都会给我爸妈和女朋友的爸妈打电话问候。我女朋友没有给我爸妈打电话，我就会说她：你应该过年过节给我爸妈打个电话问候一下。\u003c/p>\u003cp>3马银花：我有一次下班回到家，心情很不好，很累。我老公像没看到一样，我就很生气，追到房间问他：你不知道我现在很累，心情不好，需要安慰吗？我老公说：我真的不知道啊，你没有告诉我。就是因为我没有表达自己的感受，我以为他会懂。\u003c/p>\u003cp>A2催化应用\u003c/p>\u003cp>请大家写下应用所学的5个句型的其中某一个的具体实践计划，需要注意的是，不能仅仅是决心，而是要写下具体的做法，要有明确的时限，要有可衡量或可观测的预期结果。因为时间关系，我们等会只选一位朋友来分享他的具体实践计划。\u003c/p>\u003cp>威雄：过几天中秋节了，我会跟女朋友说，今天是中秋节，我希望你可以给我爸妈打个电话，问候一下老人家，你打了电话的话，我会觉得很开心。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1473862589000,"updated_at":1473862589000,"ria":true},{"id":869,"topic":"爱的能力之表达情感","learn_goal":"学会告诉爱人感受和需求","remark":"","level":"TF1-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"马辉","city":"珠海"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家晚上好，我是马辉，今天我是拆TF1-2,我今天分享一下我要拆的这个拆页是来自《爱的五种能力》一书，它是由国内资深情感教练赵永久先生所著，书中详细介绍了情绪管理、述情、共情、允许、影响五种能力，及练习的具体方法。很多人因为自己没遇到爱的人，或错过了爱的机会，或拥有过又失去了爱人，开始不相信爱情，其实他们是缺乏“爱的能力”。如果想拥有爱情，你不仅要有爱的激情，更要有爱的能力。 越来越多的人面临着爱的缺失，部分源于当今的浮躁，部分源于义务教育中情感知识体系的贫瘠，部分源于原生家庭亲密关系的冷漠或者过度。当我们无法从原生家庭和学校里面获取正确的爱情能力时，走向社会势必会出现各种各样的情感问题。通过这本书，我们学会爱是一种可以培养的能力，这就有了理论基础。通过觉察，我们发现与人交往的过程中很多问题都是爱的能力的问题，通过书中提供的五种爱的能力的学习和锻炼，来提高大家爱的能力，更容易爱和被爱。","ratings_count":0,"texts":[{"id":2719,"quote":"\u003cp>今天的拆页来自这本书的第三章说出感觉容易爱：述情。请大家先看一下我复印的拆页。\u003c/p>\u003cp>很多咨询师给遭遇情感困惑的人做咨询时，给出的辅导意见经常会有一句话，你需要学会表达自己的感受。每个人成长环境不同，决定了他们表达自己感受的能力不同。学会表达自己的感受才能为爱你的人画出一条走到你内心的线路图，掌握和你相处的窍门。爱上一个人是被她吸引，但被吸引不代表了解她，如果不告诉对方自己的想法和感受，又怎能埋怨对方不懂自己呢？\u003c/p>\u003cp>句型一，当自己心情不好的时候，直接告诉对方。很多人在生活中的习惯和和这个句型表达的观点是相反的。比如人们常说报喜不报忧，。这是很多人从小所受的教育导致，很多人的信条就是不要把负面情绪带回家，就算自己在外面再痛苦，也不在家人面前表现出来。可如果自己内心很痛苦，又刻意隐藏，爱人怎么能知道自己心里想的是什么呢？比如：我今天心情不是很好。我今天感觉很失落。\u003c/p>\u003cp>句型二：当爱人让自己感受不好或好时，告诉爱人自己的感受。\u003c/p>\u003cp>每个人身上多少有一些情绪按钮，当对方触碰他们的时候，可能就会很不愉快。如果对方知道了这一点，就会注意。使用述情的两个基本功：事实+感受。比如：我们两人在厨房一遍做饭，一边聊天，我感觉非常开心，我很喜欢这种感觉。这也意味着，当自己的爱人做了一件自己很喜欢的事情时，如果不及时说出自己的感受强化一下，爱人就不知道自己是很喜欢他这样做的。以后这样的行为就可能不会出现太多，而自己述情之后，这样的行为可能就会越来越多。当然，这时的句型也是一样的，事实+感受。\u003c/p>\u003cp>句型三：告诉爱人自己的需求，而不是解决方案。\u003c/p>\u003cp>当人们把解决方案说出来后，它不一定是最优的，对方就只有同意和不同意两个选择。当对方不同意的时，人们就容易感觉对方不理解自己。其实对话者也是有责任的，因为自己没有把需求讲出来。所以，跟爱人沟通时，一定经常把自己的需求讲出来，对方就会一起来探讨解决方案。\u003c/p>\u003cp>句型4，说出自己喜欢的，而不是不喜欢的。\u003c/p>\u003cp>在情感关系里，人们需要经常说这个句型，让爱人知道自己喜欢什么，想要什么，向往什么。这样不但让他感觉舒服，而且知道如何做能让你开心。他就能避免在猜测纠结上浪费时间。\u003c/p>\u003cp>句型5：说出我希望，不说“你应该”\u003c/p>\u003cp>“你应该”和“我希望”有什么区别呢？“你应该”是从“正确的事”的角度讲，是讲“理”的，意思是对方应该这样做，这样做是对的，不这样做是错的，上升到了对和错的高度。\u003c/p>\u003cp>但“我希望”不一样，“我希望”没有说对方不这样做事错的，没有评价对方，只是告诉对方我很希望你这样做。意思是这是我需要的你爱我的方式。是从愉快的角度讲，是讲情讲爱的。\u003c/p>","explains":"\u003cp>大家可以看到要和伴侣进行良好沟通的5个句型是第一，当你心情不好时，直接告诉对方。第二当伴侣做了什么事情，让自己开心或者不开心的时候，用事实+感受的句型告诉对方。这里我有一个例子，就是我一个做研发的师妹，单身，家里一直催她找男朋友，父母总觉得她在外面工作几年了还是一无所有，觉得她很失败。她很难过的给我打电话。我就问她你父母那么说你的时候，你是什么感觉？她说觉得很委屈，很难过，觉得被父母否定。我就问她，那你有没有跟你父母说过，你父母那么说你，让你很委屈很难过。她说没有，我问她为什么不说呢，她说父母也不容易，也是为她好。我就跟她说下次可以试试用事实加感受的方式跟父母沟通看看，后面她又给我打电话说那天她跟家里通电话，她妈又批评她了，她就跟她妈说，妈，我知道你也是为我好，希望我幸福。但是你和爸爸每次那么说我，让我觉得很难过，很委屈，我自己也希望找个男朋友疼我，爱我，可是感情的事儿不是说找就能找的，我也在努力的去扩大我的生活圈子，希望可以遇到那个合适的人。我希望你们更多的鼓励我，这样我会觉得至少我还有爸妈支持我。说出来之后，她感觉好多了，而且爸妈也觉得好吧，你也是那么大人了，自己把握好就行。第三个句型是，告诉对方自己的需求，而不是直接给出解决方案。第四点，说出自己喜欢的，而不是不喜欢的。这里我也有个例子，第五点，说我希望，而不说你应该。\u003c/p>","interaction":"\u003cp>A1&nbsp;我们读了这个拆页，了解到提升爱的能力的6个句型。那么，请大家想想自己有没有经历过类似情境，有没有过相关的经验，请在小组内分享，每人1-2分钟。\u003c/p>\u003cp>angel:最近我有些燥，那天我女儿收拾东西，洗澡，磨磨蹭蹭40度分钟，我就很生气，着急，不停的催她。但这个过程中，我其实并没有表达出来我当时的感受，所以她并不知道我当时的感受。\u003c/p>\u003cp>雄同学：我那天拉肚子，感冒，要坐轻轨去给女朋友的妈妈庆祝生日，因为身体不舒服，把轻轨的时间记错了。结果女朋友埋怨我不靠谱。我觉得很伤心，就跟女友说我今天生病，坚持赶过去给妈妈过生日，因为不舒服记错时间，你埋怨我不靠谱让我觉得很伤心，后来女朋友就跟我道歉了。\u003c/p>\u003cp>A2&nbsp;请大家写下应用所学的6个句型的其中某一个的具体实践计划，需要注意的是，不能仅仅是决心，而是要写下具体的做法，要有明确的时限，要有可衡量或可观测的预期结果。因为时间关系，我们等会只选一位朋友来分享他的具体实践计划。\u003c/p>\u003cp>马银花：之前我先生很不理解我为什么业余时间要参加那么多各种各样的活动，比如拆书，比如头马英文演讲俱乐部。我今天晚上要跟他聊聊这个话题，告诉他我参加这些活动，一是为了提高自己的表达能力，一是为了认识更多的小伙伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1473385574000,"updated_at":1473385604000,"ria":true},{"id":782,"topic":"察觉情绪","learn_goal":"学会记录情绪","remark":"","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"马辉","city":"珠海"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是马辉，马是马到成功的马，辉是辉煌的辉，湖北襄阳人。2007年毕业于华中科技大学人文学院中文系，目前在企业从事培训和招聘的工作。毕业这几年辗转珠海，深圳，北京三地，一直很关注各种不同的培训方式，像用产品经理思维来做培训，用互联网思维来做培训，培训游戏化，社交化，从2015年开始听说拆书帮，去年听了3次angel做的拆书分享，也关注了拆书帮的微信公众号，对这种方式比较认可，自己平时读书存在读书时间少，读书速度慢，以及没有把书里介绍的一些好的方法坚持贯彻下来的问题，所以希望自己能学会这种读书方法，提升自己的读书效率和实践成果。","ratings_count":0,"texts":[{"id":2499,"quote":"\u003cp>爱自己需要第六感：情绪的觉察\u003c/p>\u003cp>觉察自己的情绪，也可以理解为第六感。\u003c/p>\u003cp>一个人能不能意识到自己起了情绪，取决于有没有觉察到自己内心感受的能力，时常觉察自己内心的人，才能意识到情绪的提示。\u003c/p>\u003cp>觉察就是意识到自己起了情绪，就像看到了情绪一样，仿佛人跳出了自己，从另外的角度看自己的内心，可以看到自己的情绪如雾一般，聚集起来又散去。\u003c/p>\u003cp>一个人带着觉察的意识时，才能看到自己的情绪。当一个人没有意识到情绪的存在时，情绪是人的主宰者，情绪会驱使人做一些不理智的事情，这些事情可能会伤害他人，而人在事情发生后才意识到自己做了什么。\u003c/p>\u003cp>我们需要战胜心中的恶魔，做自己的主人，管理好自己的情绪，就需要带着觉察去生活，这需要刻意的练习，才能做到或做的更好。\u003c/p>\u003cp>下面是一个非常有效的提升情绪觉察能力的练习方法，做完这个练习，人们会看到一个不一样的自己，很多人将会重新认识自己，并将自己的精神境界带到一个新的高度。\u003c/p>\u003cp>情绪记录：\u003c/p>\u003cp>1随身携带一个笔记本和一支笔。\u003c/p>\u003cp>2感觉到自己有情绪的时候，马上记下来。\u003c/p>\u003cp>3记录的格式：时间，地点，事件，情绪。\u003c/p>\u003cp>这样连续记录三四周，基本就可以养成随时觉察自己情绪的习惯，以后再有情绪时，就可以第一时间意识到，不会错过采取行动去应对情绪提示的机会。\u003c/p>","explains":"\u003cp>这段话讲述了一个人需要带着觉察去发现自己起了情绪，去体会自己当下的感受，去意识到情绪给自己的提示，因为人在情绪的作用下很容易失去理智，说出一些不好的话，或者作出一些不好的事儿，伤害到身边的人，中国的弘一法师有句话：“盛喜中，勿许人物；盛怒中，勿答人书。” 也就是说，极度欢喜时，不要许诺给别人东西；极度愤怒时，不要回复别人书信。为什么呢？“喜时之言，多失信；怒时之言，多失体。同时文中提供了一个记录情绪的方法，来提高对情绪觉察的能力。就是当你感觉到自己有情绪的时候，记录下来，纸笔也好，手机记录也好，把引起情绪的时间，地点，事件，情绪记录下来。是一个重新认识自己的机会。\u003c/p>","interaction":"\u003cp>A1&nbsp;我是一个内敛的人，以前有时候觉得伤心、委屈或者生气的时候，有时候是没有觉察到，被自己压抑下去了，有时候虽然觉察到了，也不愿意表达和抒发出来，还会自己宽慰自己说没事儿，告诉自己要乐观积极向上，很快就会好起来，原本以为这是好事，让自己不用被情绪主宰，。殊不知，这样的负面情绪积压下来，其实是对自己不好的，对自己的心理健康和精神状态都会有影响。没有意识到这种情绪对自己的提示。以前有一次和一个朋友一起约了去国博看黄永玉的画展，那个朋友迟到了2个小时，当时自己其实是有些生气的，但是当朋友赶到后，我还是故作轻松的说没事儿没事儿。其实我的内心里已经起了情绪，但我没有意识到此时情绪的提示作用。\u003c/p>\u003cp>A2&nbsp;以前在看这本书的时候，自己随身带了一个小本子记录自己的正面情绪和负面情绪及引发这个情绪的事件，最开始好几天才能记录一次，后面慢慢的大概每天都可以记录一次，我理解为是自己对自己情绪觉察能力稍微提高了一些。现在重读这本书，我开始在自己在手机上的有道笔记里记录下来，每天遇到什么事情让我有了什么样的情绪，自己询问自己：辉辉，你现在感觉怎么样？你是觉得开心吗？你觉得感动吗？你是觉得难过吗？你是觉得委屈吗？你觉得不满吗？。。。。按照时间，地点，事件，当时是什么情绪的格式记录，这周六我记录了一件开心的事儿，周日记录了一件失落的事儿，周一记录了一件感动的事儿，周二记录了一件焦虑的事儿。培养自己对情绪的觉察能力。收到的效果是当我分辨清楚什么事情会让我起什么样的情绪的时候，出现负面情绪的时候，就会不由自主的思考这件事为什么会让我有这个情绪，这个事情换做别人会不会也有这个情绪呢，这个事情到底是我的评判，还是客观事实呢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1472129148000,"updated_at":1472129236000,"ria":true},{"id":730,"topic":"爱的需求层次，提升爱的能力","learn_goal":"“我爱你，与你无关”这种爱的方式可取吗？","remark":"","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"fionacao","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我是拆书家，Fiona. 最近有一句很火的情感宣言“我爱你，与你无关。”今天通过RIA学习：了解爱的需求层次，认识到这种爱的方式会幸福吗？\r\n作为国内知名的情感教练赵永久，本书以通俗、易懂的语言讲解心理学中的情感心理，运用生活中诸多实例，实用性极高，深入浅出讲解如何使用、表达爱的5种能力，帮助了很多人变得更加可爱、会爱、容易爱。","ratings_count":0,"texts":[{"id":2340,"quote":"\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp; 爱的第一个层次：满足自己的需求。\u003c/p>\u003cp>这种爱是对他的心理需求，说明对方是可以满足你需要的人。本质上是爱自己，是自己对对方的需求，希望跟对方在一起来满足自己的需求，让自己更开心快乐一些。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp; 爱的第二个层次：“自以为是”地付出。\u003c/p>\u003cp>内心有爱对方的意愿，想着为对方做些事情，不过不是从对方需要的角度出发的，所以对方很难收到，就会认为对方不懂得感恩。这样的人注意力还是在自己身上，爱上了“付出”这个行为本身，只关注自己有没有付出，没有关注对方是否喜欢。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp; 爱的第三个层次：满足对方的需求。\u003c/p>\u003cp>真正的爱是满足对方的需求，是用心去体察对方需要什么，有什么需求，然后去满足他。这样的爱，其本质才是爱对方，才是真正的爱，爱的高级形式。只有这样，对方才能深深地感受到爱的存在，才能因为爱的存在而更加幸福。\u003c/p>\u003cp>想要成为爱的能力高的人吗？那就经常体察对方需要什么并满足对方吧，也请经常告诉对方，你希望什么，喜欢什么，想要什么，为对方如何爱你指明方向。\u003c/p>","explains":"\u003cp>同人的需求层次一样，爱也有需求层次。\u003c/p>\u003cp>爱的需求层次不光存在情感世界，其实是我们和所有人以及这个世界相处的原则。弗洛姆说：爱首先不是同一个特定的人的关系：它是一种态度，一种性格倾向。这种态度、性格倾向决定了一个人同整个世界的关系。如果某人只爱一个人，而对其他人漠不关心，他的爱就不是爱，而是一种共生性依恋或者是一种放大的自我主义。\u003c/p>\u003cp>1. 第一个层次：满足自己的需求。比如：我想你，看不见你时满脑子都是你。见到你就很开心，见不到就很痛苦。这其是对他人的心理需要，仅仅只是爱的低级的层次。本质上是爱自己，是你需要对方，希望跟对方在一起来满足自己的需求，让自己更开心快乐一些。“我爱你，与你无关”其实就是在满足自己的需求，这种做法并没有啥对错，只是情感相处中简单的单项需求。\u003c/p>\u003cp>2. 第二个层次：“自以为是”的付出。比如：有人认为钱多很重要，就拼命挣钱，但家人并不领情，因为家人更希望陪伴。这样的人内心有爱对方的意愿，想着为对方做些事情，而不只是让对方来满足自己。但做的都是自己认为好的事情，不是从对方需要的角度出发的，所以这样做呢，不能说错，它的坏处是对方很难收到，让付出的人会觉得对方不懂得感恩。其实他们的注意力还是在自己，爱上了“付出”这个行为本身，只关注自己有没有付出，却没有关注对方是否喜欢。\u003c/p>\u003cp>3. 第三个层次：满足对方的需求。以对方的需求为出发点，为对方做事情，而不是自己的“自以为是”。用心去观察对方需要什么？有什么需求？然后去满足他，这样的爱才是爱对方，是爱的高级形式，对方才能深深地感受到爱的存在，也因为爱的存在而更加幸福。\u003c/p>\u003cp>如何做到最高层次的爱的需求呢？就要经常体察对方需要什么并满足对方，同时也请经常告诉对方（尤其是告诉男士们），你希望什么，喜欢什么，想要什么，为对方如何爱你指明方向。比如：知道对方喜欢吃什么，就经常买什么。知道对方最近的焦虑，就为对方排解。同时也要积极告知对方你的需求，让对方以你的需求为前提来付出，去储备对彼此的感恩与情感。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆书家提问设计：请大家分组回顾下：这个周末，在跟家人（伴侣、孩子、长辈）、朋友相处模式，开启的是哪一个模式：“满足自己需求”、“付出”、“满足对方的需求”呢？ &nbsp; \u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>学习者案例记录：1）兜兜爸爸表示，生活中妈妈经常会“自以为是”的付出。觉得自己房间太乱，就老是帮他收拾，可实际他并不需要。2）Jesscia说今早她来参加拆书活动，因为老是等不到公交，就把老公硬拖出来当司机送她到会场。她实际上用的是的一个层次，来满足自己的需求。反而是老公对她是第三个层次，真正满足她的需求来爱她。3）Clair说爸妈对于她出去旅游颇为不理解，一直认为是浪费时间，以他们的方式来评判、关心她。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>拆书家提问设计：设想下，你今天回到了家中，又遭遇到上面类似的情景。在打开你固有模式之前，要不要停下来问自己，我可以有不同的处理模式吗？怎样做，才能让我和对方都开心、幸福呢？请在小组内分享你的应用。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>学习者案例记录：1）兜兜爸觉得之前对于妈妈的洁癖很不理解，现在了解到这是她的一种爱的表达，要向妈妈解释自己为啥书房乱的原因，不需要她帮忙收拾，以便她了解自己的需求，同时也会开始慢慢整理收拾书房，让妈妈放心。2）Apple说之前对儿子一直有种“你妈觉得你冷”的感觉，认为自己是对的，是对孩子的关心，因为小孩子还不懂冻不冻着。现在了解到既然孩子说自己不冷，他已经说出了需求，那先以他的需求来爱他。如果真的冻着了，以后也好让小孩子自己长个记性，知道何为冷暖。3）Clair 现在了解到这是父母在表达爱的一种方式，虽然是以自我角度为出发点，她会尽量多跟父母沟通，告诉他们旅游给她带来的好处，告诉她自己内心的需求，来让他们了解，逐步地接受。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1471092885000,"updated_at":1471092885000,"ria":true},{"id":598,"topic":"在情感关系中“爱”和“理”哪个更重要","learn_goal":"学会以“爱”的角度出发，处理情感问题","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"fionacao","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我是今天的拆书家，Fiona. 今天我们会通过RIA学习：在生活中，更多使用“情”来跟关系重要、紧密的人沟通。\r\n作为国内知名的情感教练赵永久，本书以通俗、易懂的语言讲解心理学中的情感心理，运用生活中诸多实例，实用性极高，深入浅出讲解如何使用、表达爱的5种能力，帮助了很多人变得更加可爱、会爱、容易爱。","ratings_count":0,"texts":[{"id":1690,"quote":"1. 心理学认为人做事情都是有动机的，但归根结底人类做的事情只有两类：愉快的事和正确的事。\r\na) 愉快的事受本我支配。按照弗洛伊德的理论，本我遵循快乐原则，核心是满足个人当前的需要，受潜意识的本能驱动。\r\nb) 正确的事受超我支配，超我是经由父母和社会的奖惩和鼓励逐渐发展而来的，是社会化的结果，合并了社会的价值观和标准。\r\n2. 家是承载爱情的地方，成家时为了更加幸福，如果家里有太多的正确、标准，会让人不快乐、让人压抑。那些没有爱的能力的人，其中一个重要的体现就是只讲道理、论对错，不关注别人是否愉快！跟这样的人生活在一起，的确不容易感受到幸福。\r\n3. 在爱情里既要愉快又要正确，那该怎样做呢？\r\na) 在正确的范围内作愉快的事。多给爱人及家人留些愉快的空间，让他可以做自己喜欢做的、想做的事情，舒服放松做自己。\r\nb) 用愉快的方法做正确的事。这样既强调了正确，又照顾到对方的心情，这叫既愉快又正确，在自己幸福的同时别人也幸福了。","explains":"1.人类做事的基本动机只有两个：愉快的事和正确的事。晚上想去唱歌，是愉快的事情，心情会好！上班打卡，是正确的事情，不做是错的，会受到单位的处罚。按照弗洛伊德的理论，愉快的事受本我支配，核心是满足个人当前的需要，受潜意识里的本能驱动。儿童做事情基本都是受本我支配。什么愉快做什么，想做什么做什么。正确的事受超我支配。儿童5 岁左右，经由父母和社会的惩罚和奖励，逐渐发展出超我。超我是社会化的结果，合并了社会的价值观和标准，具体表现为是非对错等，我们常常会用“应该”来表达这些。这些标准、规则的存在是为了让人们在满足自己时不要伤害他人，人类社会得以有序发展。\r\n2.家是承载爱情、亲情的地方，成家是为了更加幸福，如果家里有太多的正确、标准，会让人不快乐、让人压抑。那些没有爱的能力的人，其中一个重要的体现就是凡事只讲道理、论对错，不关注别人是否愉快！跟这样的人生活在一起，的确不容易感受到幸福。一个人很想跟另一个人在一起，一定是有一个前提的，那就是跟他在一起，是一件“愉快的事”！过多讲理，讲对错的人，总要求身边人“做正确的事’，给身边人太少做‘愉快的事”的空间，身边人就可能不喜欢跟他在一起，也找不到幸福。社会已经给了人们很多的标准，工作和生活已经有太多压力了。所以，在家里，这个承载爱情、亲情的地方，还是少讲些“正确”，多讲些“愉快”，少讲些“理”，多讲些“爱”。让每个人在家里都能开心快乐、轻松自在，而不是压抑和痛苦。\r\n3. 如何来做到呢？\r\nA. 在不触犯法律，不涉及道德，不伤害别人的前提下，少一些正确，多给爱人及家人留些愉快的空间，让他可以做自己喜欢做的、想做的事情，舒服放松的做自己。比如家人只是想要多睡一会儿、想要个自己喜欢的东西、想把今天的碗放到明天再洗等等一些而没有伤害其他人的事，就尽量允许吧，这样他们会更愉快些。家不是讲“理”的地方，家就是用来休息放松、撒娇耍赖、满足欲望的地方。\r\nB. 用愉快的方法做，比如工作中去取东西，你可以边拿变扭动身体、嘴巴里唱着歌，把这件枯燥的事情做得愉快些。而人们在要求他人做正确的事时，也是可以用愉快的方法，也就是照顾到他人的感受。比如：跟爱人一起过马路，他想闯红灯。可以这样说：“亲爱的，别着急，咱们等绿灯再走吧！”这样，既强调了正确，又照顾了对方的心情，这叫既愉快又正确。\r\n就是这样，在爱情里，在家里，甚至在各种人际关系里，我们都尽量用愉快的方法做正确的事，照顾到大家的心情，在自己幸福的同时别人也幸福了。","interaction":"A1: 拆书家提问设计：请大家分组回顾下在自己的生活中，在家里也不自觉地在讲“理”，想要去说服对方，要争个是非对错。而不是“情”考虑对方的感受？如果有以上状况，请在小组内分享。5分钟会，请每个小组分享下一个组内案例。学习者案例记录：翁豆分享：自己平时和公婆一起住，他们吃饭时筷子会放在桌上。自己觉得对宝宝来说不卫生，就企图指正公婆。但公婆确认为：她嫌弃老人家擦桌子擦得不干净，就很不开心。 拖雷分享：老婆在家喜欢用手机看小说，觉得很愉快。自己则要承担带孩子的责任，就不开心。想要跟老婆理论，老婆就直接拒绝，不想听他说。\r\nA2:拆书家提问设计：请大家分享下再遇到这样情况，你可以如何运用今天的学习去处理、应对？\r\n学习者案例记录：翁豆说，通过今天的学习，开始学会接受公婆的不同做法。因为他们老一辈的做法，虽然会有点不卫生，可不是啥上纲上线的问题，没有必要为了这种小事来争执，争个对错。自己会接受，只要在桌子上放块干净的纸巾放宝宝筷子就好了。拖雷则说：今天学会了这个好用的方法，要学会用愉快的方式来跟老婆沟通，而不是每次严厉指责，说老婆只顾自己看书不对。可以跟她很好沟通：接受她想看书的愉悦，留给她愉快的看书时间，固定小时看完书之后她也要承担照顾孩子的责任。Monica说，爸爸很暴躁，为了能让他戒烟，她决定以后用愉悦的方式跟他说，而不是指责。她想要每天读20分钟书给爸爸听，来激励他持续戒烟。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1468243764000,"updated_at":1468243958000,"ria":true}]};